static bool ssl_write_all(SSL* ssl, const char* data, u32 len) {
    u32 sent = 0;
    while (sent < len) {
        i32 n = SSL_write(ssl, data + sent, static_cast<i32>(len - sent));
        if (n <= 0) return false;
        sent += static_cast<u32>(n);
    }
    return true;
}

static void set_socket_timeouts(i32 fd, i32 secs) {
    struct timeval tv;
    tv.tv_sec = secs;
    tv.tv_usec = 0;
    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
}

static SSL_CTX* create_test_client_ctx() {
    SSL_CTX* client_ctx = SSL_CTX_new(TLS_client_method());
    if (client_ctx) SSL_CTX_set_verify(client_ctx, SSL_VERIFY_NONE, nullptr);
    return client_ctx;
}

// === Socket Setup (libuv: test-tcp-bind-error, test-tcp-flags, test-tcp-reuseport) ===

TEST(socket, nonblocking) {
    i32 fd = create_listen_socket(0).value_or(-1);
    REQUIRE(fd >= 0);
    CHECK(fcntl(fd, F_GETFL, 0) & O_NONBLOCK);
    close(fd);
}

TEST(socket, reuseport) {
    i32 fd = create_listen_socket(0).value_or(-1);
    REQUIRE(fd >= 0);
    i32 val = 0;
    socklen_t len = sizeof(val);
    getsockopt(fd, SOL_SOCKET, SO_REUSEPORT, &val, &len);
    CHECK_EQ(val, 1);
    close(fd);
}

TEST(socket, nodelay) {
    i32 fd = create_listen_socket(0).value_or(-1);
    REQUIRE(fd >= 0);
    i32 val = 0;
    socklen_t len = sizeof(val);
    getsockopt(fd, IPPROTO_TCP, TCP_NODELAY, &val, &len);
    CHECK_EQ(val, 1);
    close(fd);
}

TEST(socket, two_listeners_same_port) {
    i32 fd1 = create_listen_socket(0).value_or(-1);
    REQUIRE(fd1 >= 0);
    i32 fd2 = create_listen_socket(get_port(fd1)).value_or(-1);
    CHECK(fd2 >= 0);
    if (fd2 >= 0) close(fd2);
    close(fd1);
}

TEST(socket, connect_refused) {
    i32 fd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, 0);
    REQUIRE(fd >= 0);
    struct sockaddr_in a;
    memset(&a, 0, sizeof(a));
    a.sin_family = AF_INET;
    a.sin_port = __builtin_bswap16(19999);
    a.sin_addr.s_addr = __builtin_bswap32(0x7F000001);
    i32 rc = connect(fd, reinterpret_cast<struct sockaddr*>(&a), sizeof(a));
    CHECK(rc < 0);
    CHECK(errno == EINPROGRESS || errno == ECONNREFUSED);
    close(fd);
}

TEST(socket, double_bind_error) {
    i32 fd = socket(AF_INET, SOCK_STREAM, 0);
    REQUIRE(fd >= 0);
    struct sockaddr_in a;
    memset(&a, 0, sizeof(a));
    a.sin_family = AF_INET;
    a.sin_addr.s_addr = __builtin_bswap32(0x7F000001);
    CHECK_EQ(bind(fd, reinterpret_cast<struct sockaddr*>(&a), sizeof(a)), 0);
    a.sin_port = __builtin_bswap16(18888);
    CHECK(bind(fd, reinterpret_cast<struct sockaddr*>(&a), sizeof(a)) < 0);
    close(fd);
}

TEST(socket, double_listen_ok) {
    i32 fd = create_listen_socket(0).value_or(-1);
    REQUIRE(fd >= 0);
    CHECK_EQ(listen(fd, 4096), 0);
    close(fd);
}

// === Built-in /metrics endpoint ===

// GET /metrics returns the Prometheus exposition when the loop carries the
// cross-shard metrics registry (what main wires under --metrics).
TEST(metrics_endpoint, serves_prometheus_exposition) {
    using namespace rut;
    RealLoop* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto lfd = create_listen_socket(0);
    REQUIRE(lfd.has_value());
    const i32 listen_fd = lfd.value();
    const u16 port = get_port(listen_fd);
    REQUIRE(loop->init(0, listen_fd).has_value());

    ShardMetrics m;
    m.init();
    loop->metrics = &m;
    ShardMetrics* reg[1] = {&m};
    loop->all_shard_metrics = reg;  // enable the endpoint
    loop->shard_metrics_count = 1;

    LoopThread lt = {loop, {}, 100};
    lt.start();

    i32 c = connect_to(port);
    REQUIRE(c >= 0);
    const char kReq[] = "GET /metrics HTTP/1.1\r\nHost: x\r\n\r\n";
    REQUIRE(send_all(c, kReq, sizeof(kReq) - 1));
    char buf[8192];
    u32 total = 0;
    while (total < sizeof(buf)) {
        i32 n = recv_timeout(c, buf + total, sizeof(buf) - total, 2000);
        if (n <= 0) break;
        total += static_cast<u32>(n);
        if (buf_contains(buf, total, "rut_request_duration_seconds_count", 34)) break;
    }
    close(c);

    CHECK(buf_contains(buf, total, "200 OK", 6));
    CHECK(buf_contains(buf, total, "# TYPE rut_requests_total counter", 33));
    CHECK(buf_contains(buf, total, "rut_request_duration_seconds_bucket{le=\"+Inf\"}", 46));
    CHECK(buf_contains(buf, total, "rut_connections_active", 22));

    lt.stop();
    loop->shutdown();
    close(listen_fd);
    destroy_real_loop(loop);
}

// Without the registry wired, /metrics is just a normal path (no exposition).
