    const u32 total = static_cast<u32>(n > 0 ? n : 0);
    CHECK(!buf_contains(buf, total, "# TYPE rut_requests_total", 25));
    CHECK(!buf_contains(buf, total, "rut_request_duration_seconds_bucket", 35));

    lt.stop();
