// The @rateLimit official decorator compiles through the IR to a per-route
// limit on the RIR function (which register_jit_routes forwards to the config).
TEST(rate_limit_dsl, decorator_compiles_to_route_limit) {
    using namespace rut;
    const char* src =
        "@rateLimit(limit: 3, window: 1m)\n"
        "route GET \"/api\" { return 200 }\n";
    auto lexed = lex(Str{src, static_cast<u32>(strlen(src))});
    REQUIRE(lexed);
    auto ast = parse_file(lexed.value());
    REQUIRE(ast);
    std::unique_ptr<AstFile> ast_owned(ast.value());
    auto hir = analyze_file(*ast_owned);
    REQUIRE(hir);
    std::unique_ptr<HirModule> hir_owned(hir.value());
    auto mir = build_mir(*hir_owned);
    REQUIRE(mir);
    std::unique_ptr<MirModule> mir_owned(mir.value());
    FrontendRirModule rir{};
    auto lowered = lower_to_rir(*mir_owned, rir);
    REQUIRE(lowered);
    REQUIRE_EQ(rir.module.func_count, 1u);
    REQUIRE_EQ(rir.module.functions[0].rate_limit.count, 1u);
    CHECK_EQ(rir.module.functions[0].rate_limit.rules[0].max, 3u);
    CHECK_EQ(rir.module.functions[0].rate_limit.rules[0].window_sec, 60u);  // 1m
    CHECK_EQ(rir.module.functions[0].rate_limit.rules[0].key.count, 0u);    // default per-IP
    rir.destroy();
}

// A `timer name, every: D { }` declaration compiles through the IR to a timer
// function carrying the name + interval (register_jit_timers forwards it into
// RouteConfig.timers[]). Slice 1: the body must be empty.
TEST(timer_dsl, compiles_to_timer_function) {
    using namespace rut;
    const char* src = "timer heartbeat, every: 5s { }\n";
    auto lexed = lex(Str{src, static_cast<u32>(strlen(src))});
    REQUIRE(lexed);
    auto ast = parse_file(lexed.value());
    REQUIRE(ast);
    std::unique_ptr<AstFile> ast_owned(ast.value());
    auto hir = analyze_file(*ast_owned);
    REQUIRE(hir);
    std::unique_ptr<HirModule> hir_owned(hir.value());
    auto mir = build_mir(*hir_owned);
    REQUIRE(mir);
    std::unique_ptr<MirModule> mir_owned(mir.value());
    FrontendRirModule rir{};
    auto lowered = lower_to_rir(*mir_owned, rir);
    REQUIRE(lowered);
    REQUIRE_EQ(rir.module.func_count, 1u);
    CHECK(rir.module.functions[0].is_timer);
    CHECK_EQ(rir.module.functions[0].timer_interval_ms, 5000u);  // 5s
    CHECK(rir.module.functions[0].route_pattern.eq(Str{"heartbeat", 9}));
    rir.destroy();
}

// register_jit_routes must (a) keep a timer out of the route table / dispatch (a
// timer function is fired on schedule, not matched against request paths) and
// (b) refuse a second registration even for a timer-only config. A timer-only
// module never bumps route_count, so the precondition gates on timer_count too —
// otherwise the same timer is appended twice and fires doubly per interval.
// Uses the JIT engine, so it's gated like the other compile→JIT→register tests.
#if RUT_ENABLE_JIT_TESTS
TEST(timer_dsl, registration_idempotent_for_timer_only) {
    using namespace rut;
    const char* src = "timer t, every: 1s { }\n";
    auto lexed = lex(Str{src, static_cast<u32>(strlen(src))});
    REQUIRE(lexed);
    auto ast = parse_file(lexed.value());
    REQUIRE(ast);
    std::unique_ptr<AstFile> ast_owned(ast.value());
    auto hir = analyze_file(*ast_owned);
    REQUIRE(hir);
    std::unique_ptr<HirModule> hir_owned(hir.value());
    auto mir = build_mir(*hir_owned);
    REQUIRE(mir);
    std::unique_ptr<MirModule> mir_owned(mir.value());
    FrontendRirModule rir{};
    REQUIRE(lower_to_rir(*mir_owned, rir));
    auto cg = jit::codegen(rir.module);
    REQUIRE(cg.ok);
    jit::JitEngine engine;
    REQUIRE(engine.init());
    REQUIRE(engine.compile(cg.mod, cg.ctx));

    RouteConfig cfg{};
    REQUIRE(register_jit_routes(cfg, rir.module, engine));
    CHECK_EQ(cfg.route_count, 0u);  // a timer is NOT registered as a route
    CHECK_EQ(cfg.timer_count, 1u);
    // A second call must be refused — otherwise the timer is appended again.
    CHECK(!register_jit_routes(cfg, rir.module, engine));
    CHECK_EQ(cfg.timer_count, 1u);

    engine.shutdown();
    rir.destroy();
}
#endif  // RUT_ENABLE_JIT_TESTS

// A non-empty timer body must end in an explicit terminal statement, exactly
// like a route body (a body that never returns has nothing observable to do
// until side-effecting statements exist).
TEST(timer_dsl, rejects_body_without_terminal) {
    using namespace rut;
    const char* src = "timer t, every: 1s { let x = 1 }\n";
    auto lexed = lex(Str{src, static_cast<u32>(strlen(src))});
    REQUIRE(lexed);
    auto ast = parse_file(lexed.value());
    REQUIRE(ast);
    std::unique_ptr<AstFile> ast_owned(ast.value());
    auto hir = analyze_file(*ast_owned);
    CHECK(!hir);
}

// Timers run outside any request: req access / forward in a timer body are
// rejected with a fix-it after the shared route-body analysis.
TEST(timer_dsl, rejects_req_access_in_body) {
    using namespace rut;
    const char* src = "timer t, every: 1s { let p = req.path return 200 }\n";
    auto lexed = lex(Str{src, static_cast<u32>(strlen(src))});
    REQUIRE(lexed);
    auto ast = parse_file(lexed.value());
    REQUIRE(ast);
    std::unique_ptr<AstFile> ast_owned(ast.value());
    auto hir = analyze_file(*ast_owned);
    REQUIRE(!hir);
    CHECK(hir.error().detail.eq(
        Str{"timers run outside a request; req access and forward are not available "
            "in a timer body",
            86}));
}

TEST(timer_dsl, rejects_req_header_mutation_in_body) {
    using namespace rut;
    for (const char* method : {"set", "add"}) {
        const std::string src = std::string("timer t, every: 1s { req.") + method +
                                "(\"X-Timer\", \"v\") return 200 }\n";
        auto lexed = lex(Str{src.data(), static_cast<u32>(src.size())});
        REQUIRE(lexed);
        auto ast = parse_file(lexed.value());
        REQUIRE(ast);
        std::unique_ptr<AstFile> ast_owned(ast.value());
        auto hir = analyze_file(*ast_owned);
        REQUIRE(!hir);
        CHECK(hir.error().detail.eq(
            Str{"timers run outside a request; req access and forward are not available "
                "in a timer body",
                86}));
    }
}

// wait needs a Connection to yield/resume on; the timer invocation has none.
