// Timers don't consume HTTP-route capacity: the routes vector is sized
// kMaxRoutes + kMaxTimers, and analyze.cc caps HTTP routes at kMaxRoutes
// independently of timers. A full-route-table boundary test isn't expressible in
// source (96 brace-routes exceed the 512-token lexer cap), so this asserts the
// structural headroom that makes the independence hold.
TEST(timer_dsl, timers_have_dedicated_route_headroom) {
    using namespace rut;
    auto mod = std::make_unique<HirModule>();  // HirModule is too large for the stack
    const u32 cap = sizeof(mod->routes.data) / sizeof(mod->routes.data[0]);
    CHECK_EQ(cap, HirModule::kMaxRoutes + HirModule::kMaxTimers);
}

// Declaring more than kMaxTimers timers is a deterministic frontend error, not a
// generic runtime load failure in RouteConfig::add_timer.
TEST(timer_dsl, rejects_more_than_max_timers) {
    using namespace rut;
    std::string src;
    for (u32 i = 0; i < HirModule::kMaxTimers + 1; i++) {
        src += "timer t";
        src += std::to_string(i);
        src += ", every: 1s { }\n";
    }
    auto lexed = lex(Str{src.c_str(), static_cast<u32>(src.size())});
    REQUIRE(lexed);
    auto ast = parse_file(lexed.value());
    REQUIRE(ast);
    std::unique_ptr<AstFile> ast_owned(ast.value());
    auto hir = analyze_file(*ast_owned);
    CHECK(!hir);  // >kMaxTimers rejected in the frontend, before JIT/config
}

// A captureless probe used as a timer handler: the event loop should invoke it
// each time the timer's interval elapses.
static rut::u32 g_timer_probe_calls = 0;
static rut::u64 timer_probe_fn(void*, rut::jit::HandlerCtx*, const rut::u8*, rut::u32, void*) {
    g_timer_probe_calls++;
    return 0;
}

// The event loop fires a registered timer once its interval elapses, invoking the
// compiled handler with no Connection/Request and bumping the per-timer count.
// A shard selector within the compile-time range can still exceed the
// RUNTIME --shards value; startup validation catches it (fail fast instead
// of a silently dead timer). PR #172 review round 2.
TEST(timer_dsl, out_of_range_shard_selector_detected_at_startup) {
    using namespace rut;
    RouteConfig cfg{};
    REQUIRE(cfg.add_timer("a", 1, /*interval_ms=*/1000, &timer_probe_fn, /*shard=*/-1));
    REQUIRE(cfg.add_timer("b", 1, /*interval_ms=*/1000, &timer_probe_fn, /*shard=*/5));
    CHECK_EQ(cfg.first_out_of_range_timer_shard(/*shard_count=*/8), -1);
    CHECK_EQ(cfg.first_out_of_range_timer_shard(/*shard_count=*/5), 1);  // 'b' dead
    CHECK_EQ(cfg.first_out_of_range_timer_shard(/*shard_count=*/1), 1);
}

// Runtime filter: a shard-pinned timer fires only on the matching shard's loop.
TEST(timer, shard_pinned_timer_fires_on_matching_shard_only) {
    using namespace rut;
    RouteConfig cfg{};
    REQUIRE(cfg.add_timer("t", 1, /*interval_ms=*/1, &timer_probe_fn, /*shard=*/1));

    auto loop0 = std::make_unique<EpollEventLoop>();
    auto loop1 = std::make_unique<EpollEventLoop>();
    loop0->shard_id = 0;
    loop1->shard_id = 1;
    const RouteConfig* active = &cfg;
    loop0->config_ptr = &active;
    loop1->config_ptr = &active;

    loop0->fire_due_timers();  // arm
    loop1->fire_due_timers();  // arm
    usleep(5000);
    loop0->fire_due_timers();
    loop1->fire_due_timers();
    CHECK_EQ(loop0->timer_fire_count[0], 0u);  // wrong shard: never fires
    CHECK_GE(loop1->timer_fire_count[0], 1u);  // pinned shard fires
}

TEST(timer, event_loop_fires_due_timer) {
    using namespace rut;
    RouteConfig cfg{};
    REQUIRE(cfg.add_timer("t", 1, /*interval_ms=*/1, &timer_probe_fn));
    auto loop = std::make_unique<EpollEventLoop>();
    const RouteConfig* active = &cfg;
    loop->config_ptr = &active;
    g_timer_probe_calls = 0;

    loop->fire_due_timers();  // first call arms the deadline (now + 1ms)
    CHECK_EQ(loop->timer_fire_count[0], 0u);
    usleep(5000);             // exceed the 1ms interval
    loop->fire_due_timers();  // now due → fire
    CHECK_GE(loop->timer_fire_count[0], 1u);
    CHECK_GE(g_timer_probe_calls, 1u);
}

// The same scheduler must drive timers on the io_uring backend: main.cc prefers
// io_uring when available, so a timer wired only into epoll would never fire on
// the default host. fire_due_timers() lives in the shared CRTP base; this checks
// the io_uring loop inherits it. (No io_uring init needed — the method is pure
// scheduling over config_ptr.)
TEST(timer, io_uring_loop_fires_due_timer) {
    using namespace rut;
    RouteConfig cfg{};
    REQUIRE(cfg.add_timer("t", 1, /*interval_ms=*/1, &timer_probe_fn));
    auto loop = std::make_unique<IoUringEventLoop>();
    const RouteConfig* active = &cfg;
    loop->config_ptr = &active;
    g_timer_probe_calls = 0;

    loop->fire_due_timers();  // arm
    CHECK_EQ(loop->timer_fire_count[0], 0u);
    usleep(5000);
    loop->fire_due_timers();  // now due → fire
    CHECK_GE(loop->timer_fire_count[0], 1u);
    CHECK_GE(g_timer_probe_calls, 1u);
}

// A hot reload swapping *config_ptr must re-arm timer deadlines for the new
// config (measured from the swap), not reuse the old config's deadlines. Without
// re-arming, the just-installed timer would fire immediately on the next tick.
TEST(timer, rearms_on_config_swap) {
    using namespace rut;
    RouteConfig cfg_a{};
    REQUIRE(cfg_a.add_timer("a", 1, /*interval_ms=*/1, &timer_probe_fn));
    RouteConfig cfg_b{};
    REQUIRE(cfg_b.add_timer("b", 1, /*interval_ms=*/1, &timer_probe_fn));

    auto loop = std::make_unique<EpollEventLoop>();
    const RouteConfig* active = &cfg_a;
    loop->config_ptr = &active;
    loop->fire_due_timers();  // arm for config A

    // Hot reload: swap the active config. The next call must re-arm (not fire at
    // A's stale deadline), then fire only after B's interval elapses.
    active = &cfg_b;
    g_timer_probe_calls = 0;
    loop->fire_due_timers();  // detects the swap → re-arm, no fire
    CHECK_EQ(loop->timer_fire_count[0], 0u);
    usleep(5000);
    loop->fire_due_timers();  // B's timer now due → fire
    CHECK_GE(loop->timer_fire_count[0], 1u);
}

// The `by:` clause compiles to a composite metering-key spec on the RIR function.
TEST(rate_limit_dsl, by_clause_compiles_to_key_spec) {
    using namespace rut;
    const char* src =
        "@rateLimit(limit: 100, window: 1m, by: [ip, header(\"X-API-Key\")])\n"
        "route GET \"/api\" { return 200 }\n";
    auto lexed = lex(Str{src, static_cast<u32>(strlen(src))});
    REQUIRE(lexed);
    auto ast = parse_file(lexed.value());
    REQUIRE(ast);
    std::unique_ptr<AstFile> ast_owned(ast.value());
    auto hir = analyze_file(*ast_owned);
    REQUIRE(hir);
    std::unique_ptr<HirModule> hir_owned(hir.value());
    auto mir = build_mir(*hir_owned);
    REQUIRE(mir);
    std::unique_ptr<MirModule> mir_owned(mir.value());
    FrontendRirModule rir{};
    auto lowered = lower_to_rir(*mir_owned, rir);
    REQUIRE(lowered);
    REQUIRE_EQ(rir.module.func_count, 1u);
    REQUIRE_EQ(rir.module.functions[0].rate_limit.count, 1u);
    const auto& spec = rir.module.functions[0].rate_limit.rules[0].key;
    REQUIRE_EQ(spec.count, 2u);
    CHECK(spec.comps[0].kind == RateLimitKeyKind::Ip);
    CHECK(spec.comps[1].kind == RateLimitKeyKind::Header);
    Str hdr_name{spec.comps[1].name, spec.comps[1].name_len};
    Str want{"X-API-Key", 9};
    CHECK(hdr_name.eq(want));
    rir.destroy();
}

// rate_limit_needs_req_buf gates the h2 synth-overflow reject: only header/cookie
// keys must reject when the request buffer is unavailable (they can't be read any
// other way). ip/param keys don't read the buffer, and query keys fall back to
// the :path supplied separately — so none of those force a reject.
TEST(rate_limit, needs_req_buf_only_for_buffer_keys) {
    using namespace rut;
    // Kinds that do NOT require the request buffer.
    const RateLimitKeyKind safe_kinds[2] = {RateLimitKeyKind::Param, RateLimitKeyKind::Query};
    RateLimitRuleSet ip_only;
    REQUIRE(ip_only.add_rule(100, 1) >= 0);  // default Ip key (no components)
    CHECK(!rate_limit_needs_req_buf(ip_only));
    for (u32 i = 0; i < 2; i++) {
        RateLimitRuleSet rs;
        REQUIRE(rs.add_rule(100, 1) >= 0);
        REQUIRE(rs.rules[0].key.add(safe_kinds[i], "k", 1));
        CHECK(!rate_limit_needs_req_buf(rs));  // param / query: no reject
    }

    // Kinds that REQUIRE the buffer (no fallback) → must reject on overflow.
    const RateLimitKeyKind buffer_kinds[2] = {RateLimitKeyKind::Header, RateLimitKeyKind::Cookie};
    for (u32 i = 0; i < 2; i++) {
        RateLimitRuleSet rs;
        REQUIRE(rs.add_rule(100, 1) >= 0);
        REQUIRE(rs.rules[0].key.add(buffer_kinds[i], "k", 1));
        CHECK(rate_limit_needs_req_buf(rs));
    }

    // A buffer key on a *second* stacked rule still trips the gate.
    RateLimitRuleSet mixed;
    REQUIRE(mixed.add_rule(100, 1) >= 0);
    REQUIRE(mixed.rules[0].key.add(RateLimitKeyKind::Ip, nullptr, 0));
    REQUIRE(mixed.add_rule(10, 1) >= 0);
    REQUIRE(mixed.rules[1].key.add(RateLimitKeyKind::Cookie, "sid", 3));
    CHECK(rate_limit_needs_req_buf(mixed));
}

// HTTP/2 may split Cookie into multiple `cookie` fields; the HTTP/1 synthesis
// must join them into one `cookie:` header so cookie rate-limit keys (and the
// handler) see the full value rather than only the first field.
TEST(http2_synth, combines_split_cookie_fields) {
    using namespace rut;
    hpack::Header hs[] = {
        {{":method", 7}, {"GET", 3}},
        {{":path", 5}, {"/api", 4}},
        {{"cookie", 6}, {"a=1", 3}},
        {{"x-test", 6}, {"y", 1}},
        {{"cookie", 6}, {"sid=xyz", 7}},
    };
    u8 out[512];
    const u32 kLen = h2_synth_h1_request(hs, 5, out, sizeof(out));
    REQUIRE(kLen > 0);
    Str s{reinterpret_cast<const char*>(out), kLen};
    auto count = [&](const char* sub) {
        u32 sl = 0;
        while (sub[sl]) sl++;
        int c = 0;
        for (u32 i = 0; i + sl <= s.len; i++) {
            bool m = true;
            for (u32 j = 0; j < sl; j++)
                if (s.ptr[i + j] != sub[j]) {
                    m = false;
                    break;
                }
            if (m) c++;
        }
        return c;
    };
    CHECK_EQ(count("cookie: "), 1);                  // exactly one Cookie line
    CHECK_EQ(count("cookie: a=1; sid=xyz\r\n"), 1);  // values joined, RFC 6265 form
    CHECK_EQ(count("x-test: y\r\n"), 1);             // interleaved header preserved
}

