    CHECK_EQ(tls_state.write_calls, 0);
    CHECK_EQ(backend.pending_count, EpollBackend::kPendingCap);
    CHECK_EQ(backend.pending_completions[63].conn_id, 263u);

    close(fds[0]);
    close(fds[1]);
