namespace {
// Upstream that serves a large Content-Length body with a verifiable byte
// pattern (body[i] == i & 0xff), sent in chunks and then holds the connection
// open. Used to drive proxy-over-TLS streaming past the ciphertext buffer.
struct PatternBodyUpstream {
    i32 listen_fd = -1;
    u16 port = 0;
    u32 body_len = 0;
    std::atomic<bool> running{false};
    bool started = false;
    pthread_t thread{};

    ~PatternBodyUpstream() { teardown(); }

    static void* run(void* arg) {
        auto* s = static_cast<PatternBodyUpstream*>(arg);
        i32 client = -1;
        while (s->running.load(std::memory_order_acquire)) {
            client = accept(s->listen_fd, nullptr, nullptr);
            if (client >= 0) break;
            if (errno == EINTR) continue;
            if (errno != EAGAIN && errno != EWOULDBLOCK) break;
            usleep(1000);
        }
        if (client >= 0) {
            char req[2048];
            (void)recv_timeout(client, req, sizeof(req), 1000);
            char hdr[128];
            const int hn = snprintf(
                hdr, sizeof(hdr), "HTTP/1.1 200 OK\r\nContent-Length: %u\r\n\r\n", s->body_len);
            if (hn > 0) (void)send_all(client, hdr, static_cast<u32>(hn));
            u8 chunk[8192];
            u32 sent = 0;
            while (sent < s->body_len && s->running.load(std::memory_order_acquire)) {
                u32 n = s->body_len - sent;
                if (n > sizeof(chunk)) n = sizeof(chunk);
                for (u32 i = 0; i < n; i++) chunk[i] = static_cast<u8>((sent + i) & 0xff);
                if (!send_all(client, reinterpret_cast<char*>(chunk), n)) break;
                sent += n;
            }
            while (s->running.load(std::memory_order_acquire)) usleep(5000);
            close(client);
        }
        return nullptr;
    }

    bool setup(u32 blen) {
        body_len = blen;
        auto lfd = create_listen_socket(0);
        if (!lfd.has_value()) return false;
        listen_fd = lfd.value();
        port = get_port(listen_fd);
        running.store(true, std::memory_order_release);
        if (pthread_create(&thread, nullptr, run, this) != 0) {
            running.store(false, std::memory_order_release);
            close(listen_fd);
            listen_fd = -1;
            return false;
        }
        started = true;
        return true;
    }

    void teardown() {
        running.store(false, std::memory_order_release);
        if (started) {
            pthread_join(thread, nullptr);
            started = false;
        }
        if (listen_fd >= 0) {
            close(listen_fd);
            listen_fd = -1;
        }
    }
};

struct ScopedWatermarkTestResources {
    PatternBodyUpstream* backend = nullptr;
    Shard<IoUringEventLoop>* shard = nullptr;
    TlsServerContext* tls_server_ctx = nullptr;
    SSL_CTX* client_ctx = nullptr;
    SSL* client_ssl = nullptr;
    i32 client_fd = -1;
    i32 listen_fd = -1;
    bool shard_initialized = false;
    bool observers_armed = false;

    ~ScopedWatermarkTestResources() { cleanup(); }

    bool arm_observers() {
        u8 expected = 0;
        if (!g_iouring_tls_watermark_observer_state_for_test.compare_exchange_strong(
                expected, 1, std::memory_order_acq_rel))
            return false;
        g_iouring_tls_high_water_pauses_for_test.store(0, std::memory_order_release);
        g_iouring_tls_low_water_resumes_for_test.store(0, std::memory_order_release);
        g_iouring_tls_watermark_observer_state_for_test.store(2, std::memory_order_release);
        observers_armed = true;
        return true;
    }

    void cleanup() {
        if (observers_armed) {
            g_iouring_tls_watermark_observer_state_for_test.store(0, std::memory_order_release);
            observers_armed = false;
        }
        if (client_ssl != nullptr) {
            (void)SSL_shutdown(client_ssl);
            SSL_free(client_ssl);
            client_ssl = nullptr;
        }
        if (client_fd >= 0) {
            close(client_fd);
            client_fd = -1;
        }
        if (client_ctx != nullptr) {
            SSL_CTX_free(client_ctx);
            client_ctx = nullptr;
        }
        if (shard != nullptr && shard_initialized) {
            shard->stop();
            shard->join();
            shard->shutdown();
            shard_initialized = false;
        }
        if (backend != nullptr) backend->teardown();
        if (listen_fd >= 0) {
            close(listen_fd);
            listen_fd = -1;
        }
        if (tls_server_ctx != nullptr) {
            destroy_tls_server_context(tls_server_ctx);
            tls_server_ctx = nullptr;
        }
    }
};
}  // namespace

TEST(proxy_tls_iouring, watermark_observer_guard_scopes_callbacks_and_cleanup) {
    ScopedWatermarkTestResources resources;
    REQUIRE(resources.arm_observers());
    rut::observe_iouring_tls_high_water_pause_for_test();
    rut::observe_iouring_tls_low_water_resume_for_test();
    REQUIRE_EQ(rut::g_iouring_tls_high_water_pauses_for_test.load(std::memory_order_acquire), 1u);
    REQUIRE_EQ(rut::g_iouring_tls_low_water_resumes_for_test.load(std::memory_order_acquire), 1u);

    resources.cleanup();
    resources.cleanup();  // partial/idempotent cleanup is safe
    rut::observe_iouring_tls_high_water_pause_for_test();
    rut::observe_iouring_tls_low_water_resume_for_test();
    CHECK_EQ(rut::g_iouring_tls_high_water_pauses_for_test.load(std::memory_order_acquire), 1u);
    CHECK_EQ(rut::g_iouring_tls_low_water_resumes_for_test.load(std::memory_order_acquire), 1u);

    const i32 destructor_owned_fd = dup(STDERR_FILENO);
    REQUIRE_GE(destructor_owned_fd, 0);
    {
        ScopedWatermarkTestResources destructor_resources;
        destructor_resources.listen_fd = destructor_owned_fd;
        REQUIRE(destructor_resources.arm_observers());
        rut::observe_iouring_tls_high_water_pause_for_test();
    }
    errno = 0;
    CHECK_EQ(fcntl(destructor_owned_fd, F_GETFD), -1);
    CHECK_EQ(errno, EBADF);
    rut::observe_iouring_tls_high_water_pause_for_test();
    CHECK_EQ(rut::g_iouring_tls_high_water_pauses_for_test.load(std::memory_order_acquire), 1u);
}

// Phase 5: proxy a body 4x the ciphertext buffer (kTlsOutBufCap = 64 KiB) over
// io_uring TLS and verify it arrives byte-exact. 256 KiB cannot fit the buffer,
// so the read/drain-decoupled path must cycle the buffer fill→drain repeatedly;
// the small client SO_RCVBUF makes the client lag so tls_out_buf reaches the
// high watermark and the upstream recv is paused/resumed (kTlsOutHigh/Low).
// CI-only: needs real io_uring + TLS sockets (the sandbox can't run this).
TEST(proxy_tls_iouring, large_body_streams_through_watermark) {
    if (!iouring_socket_live()) SKIP("io_uring async socket ops unavailable in this environment");
    using namespace rut;

    constexpr u32 kBody = 256u * 1024u;  // 4x kTlsOutBufCap
    PatternBodyUpstream backend;
    REQUIRE(backend.setup(kBody));

    RouteConfig cfg{};
    auto id = cfg.add_upstream("b", 0x7F000001, backend.port);
    REQUIRE(id.has_value());
    REQUIRE(cfg.add_proxy("/dl", 0, id.value()));
    const RouteConfig* active = &cfg;

    auto tls_ctx = create_tls_server_context(kTestCertPath, kTestKeyPath);
    REQUIRE(tls_ctx.has_value());

    Shard<IoUringEventLoop> shard;
    ScopedWatermarkTestResources resources;
    resources.backend = &backend;
    resources.shard = &shard;
    resources.tls_server_ctx = tls_ctx.value();
    i32 lfd = create_listen_socket(0).value_or(-1);
    resources.listen_fd = lfd;
    REQUIRE(lfd >= 0);
    int sndbuf = 16 * 1024;
    REQUIRE_EQ(setsockopt(lfd, SOL_SOCKET, SO_SNDBUF, &sndbuf, sizeof(sndbuf)), 0);
    u16 port = get_port(lfd);
    auto shard_init = shard.init(0, lfd);
    resources.shard_initialized = shard_init.has_value();
    REQUIRE(shard_init.has_value());
    shard.loop->tls_server = tls_ctx.value();
    shard.loop->config_ptr = &active;
    REQUIRE(shard.spawn(-1).has_value());
    usleep(50000);

    resources.client_ctx = create_test_client_ctx();
    REQUIRE(resources.client_ctx != nullptr);
    // Small downstream socket buffer so the client lags the upstream and the
    // gateway's tls_out_buf actually reaches the high watermark, rather than the
    // kernel absorbing the whole body. Set it before connect so TCP negotiates
    // the bounded receive window instead of retaining an already-scaled window.
    resources.client_fd = socket(AF_INET, SOCK_STREAM, 0);
    REQUIRE(resources.client_fd >= 0);
    int rcvbuf = 16 * 1024;
    REQUIRE_EQ(setsockopt(resources.client_fd, SOL_SOCKET, SO_RCVBUF, &rcvbuf, sizeof(rcvbuf)), 0);
    sockaddr_in client_addr{};
    client_addr.sin_family = AF_INET;
    client_addr.sin_port = __builtin_bswap16(port);
    client_addr.sin_addr.s_addr = __builtin_bswap32(0x7F000001);
    REQUIRE_EQ(
        connect(
            resources.client_fd, reinterpret_cast<sockaddr*>(&client_addr), sizeof(client_addr)),
        0);
    set_socket_timeouts(resources.client_fd, 5);
    resources.client_ssl = SSL_new(resources.client_ctx);
    REQUIRE(resources.client_ssl != nullptr);
    REQUIRE(SSL_set_fd(resources.client_ssl, resources.client_fd) == 1);
    REQUIRE(SSL_connect(resources.client_ssl) == 1);
    REQUIRE(resources.arm_observers());

    const char kReq[] = "GET /dl HTTP/1.1\r\nHost: x\r\n\r\n";
    REQUIRE(ssl_write_all(resources.client_ssl, kReq, sizeof(kReq) - 1));

    // Do not begin draining until the production path reports a real high-water
    // transition. This makes the episode observable and deterministic instead
    // of inferring it from SO_RCVBUF or payload size.
    for (u32 i = 0; i < 400 && rut::g_iouring_tls_high_water_pauses_for_test.load(
                                   std::memory_order_acquire) == 0;
         ++i)
        usleep(5000);
    REQUIRE_GT(rut::g_iouring_tls_high_water_pauses_for_test.load(std::memory_order_acquire), 0u);

    static u8 in[300u * 1024u];
    u32 total = 0;
    bool hdr_done = false;
    u32 body_off = 0;
    u32 body_seen = 0;
    while (body_seen < kBody && total < sizeof(in)) {
        const i32 n =
            SSL_read(resources.client_ssl, in + total, static_cast<i32>(sizeof(in) - total));
        if (n <= 0) break;
        total += static_cast<u32>(n);
        if (!hdr_done) {
            for (u32 i = 3; i < total; i++) {
                if (in[i - 3] == '\r' && in[i - 2] == '\n' && in[i - 1] == '\r' && in[i] == '\n') {
                    hdr_done = true;
                    body_off = i + 1;
                    break;
                }
            }
        }
        if (hdr_done) body_seen = total - body_off;
    }
    CHECK(hdr_done);
    CHECK_EQ(body_seen, kBody);  // full body delivered through the watermark
    bool ok_pattern = hdr_done && body_seen == kBody;
    for (u32 i = 0; ok_pattern && i < kBody; ++i) {
        if (in[body_off + i] != static_cast<u8>(i & 0xff)) {
            ok_pattern = false;
            break;
        }
    }
    CHECK(ok_pattern);

    CHECK_GT(rut::g_iouring_tls_high_water_pauses_for_test.load(std::memory_order_acquire), 0u);
    CHECK_GT(rut::g_iouring_tls_low_water_resumes_for_test.load(std::memory_order_acquire), 0u);
    resources.cleanup();
}

// Serves one Content-Length response per accepted connection, then closes — so each
// proxied request makes a fresh upstream connect on a NEW fd. Exercises keep-alive
// proxy reuse: every request's body completion fires pause_upstream_recv (now
// cancel-by-fd), and the next request's upstream recv must not be hung/truncated by
// a stale cancel matching it.
struct ReuseUpstream {
    i32 listen_fd = -1;
    u16 port = 0;
    u32 body_len = 0;
    std::atomic<bool> running{false};
    bool started = false;
    pthread_t thread{};

    ~ReuseUpstream() { teardown(); }

    static void* run(void* arg) {
        auto* s = static_cast<ReuseUpstream*>(arg);
        while (s->running.load(std::memory_order_acquire)) {
            i32 client = accept(s->listen_fd, nullptr, nullptr);
            if (client < 0) {
                if (errno == EINTR) continue;
                usleep(500);  // non-blocking listen socket (EAGAIN) — poll
                continue;
            }
            char req[2048];
            (void)recv_timeout(client, req, sizeof(req), 1000);
            char hdr[128];
            const int hn = snprintf(
                hdr, sizeof(hdr), "HTTP/1.1 200 OK\r\nContent-Length: %u\r\n\r\n", s->body_len);
            bool ok = hn > 0 && send_all(client, hdr, static_cast<u32>(hn));
            u8 chunk[8192];
            u32 sent = 0;
            while (ok && sent < s->body_len) {
                u32 n = s->body_len - sent;
                if (n > sizeof(chunk)) n = sizeof(chunk);
                for (u32 i = 0; i < n; i++) chunk[i] = static_cast<u8>((sent + i) & 0xff);
                ok = send_all(client, reinterpret_cast<char*>(chunk), n);
                sent += n;
            }
            close(client);  // fresh upstream connect per proxied request
        }
        return nullptr;
    }

    bool setup(u32 blen) {
        body_len = blen;
        auto lfd = create_listen_socket(0);
        if (!lfd.has_value()) return false;
        listen_fd = lfd.value();
        port = get_port(listen_fd);
        running.store(true, std::memory_order_release);
        if (pthread_create(&thread, nullptr, run, this) != 0) {
            running.store(false, std::memory_order_release);
            close(listen_fd);
            listen_fd = -1;
            return false;
        }
        started = true;
        return true;
    }

    void teardown() {
        running.store(false, std::memory_order_release);
        if (started) {
            pthread_join(thread, nullptr);
            started = false;
        }
        if (listen_fd >= 0) {
            close(listen_fd);
            listen_fd = -1;
        }
    }
};

// Regression for the upstream-recv cancel-collision (now fixed by cancel-by-fd):
// many keep-alive proxied requests over one TLS connection, each ending in a body
// completion that cancels the upstream recv. A stale cancel matching the next
// request's recv would hang or truncate it — so all must complete intact. Runs on
// real io_uring (CI), under ASan in the sanitizer job.
// Drive kRequests keep-alive proxied requests over one TLS connection against
// ReuseUpstream (which closes after each response, so every request makes a fresh
// upstream connect → a cancel-by-fd at each body completion). Returns how many
// completed with an intact kBody-byte pattern body — a stale cancel matching the
// next request's recv would hang/truncate one, dropping the count. Shared by the GET
// and POST reuse regressions; uses plain early returns (no CHECK) so the caller
// owns the assertion.
static u32 run_keepalive_reuse(const char* req, u32 req_len, u32 kBody, u32 kRequests) {
    using namespace rut;
    ReuseUpstream backend;
    if (!backend.setup(kBody)) return 0;

    RouteConfig cfg{};
    auto id = cfg.add_upstream("b", 0x7F000001, backend.port);
    if (!id.has_value()) return 0;
    if (!cfg.add_proxy("/dl", 0, id.value())) return 0;  // method 0 matches GET and POST
    const RouteConfig* active = &cfg;

    auto tls_ctx = create_tls_server_context(kTestCertPath, kTestKeyPath);
    if (!tls_ctx.has_value()) return 0;

    Shard<IoUringEventLoop> shard;
    i32 lfd = create_listen_socket(0).value_or(-1);
    if (lfd < 0) return 0;
    u16 port = get_port(lfd);
    if (!shard.init(0, lfd).has_value()) return 0;
    shard.loop->tls_server = tls_ctx.value();
    shard.loop->config_ptr = &active;
    if (!shard.spawn(-1).has_value()) return 0;
    usleep(50000);

    SSL_CTX* client_ctx = create_test_client_ctx();
    i32 c = connect_to(port);
    SSL* ssl = (client_ctx != nullptr && c >= 0) ? SSL_new(client_ctx) : nullptr;
    u32 completed = 0;
    if (ssl != nullptr && SSL_set_fd(ssl, c) == 1 && SSL_connect(ssl) == 1) {
        set_socket_timeouts(c, 5);
        static u8 in[64u * 1024u];
        for (u32 r = 0; r < kRequests; r++) {
            if (!ssl_write_all(ssl, req, req_len)) break;
            u32 total = 0, body_off = 0, body_seen = 0;
            bool hdr_done = false;
            while (body_seen < kBody && total < sizeof(in)) {
                const i32 n = SSL_read(ssl, in + total, static_cast<i32>(sizeof(in) - total));
                if (n <= 0) break;  // a collision-cancelled recv surfaces here as a hang/EOF
                total += static_cast<u32>(n);
                if (!hdr_done) {
                    for (u32 i = 3; i < total; i++) {
                        if (in[i - 3] == '\r' && in[i - 2] == '\n' && in[i - 1] == '\r' &&
                            in[i] == '\n') {
                            hdr_done = true;
                            body_off = i + 1;
                            break;
                        }
                    }
                }
                if (hdr_done) body_seen = total - body_off;
            }
            if (!hdr_done || body_seen < kBody) break;
            bool pattern_ok = true;
            for (u32 i = 0; i < kBody; i++) {
                if (in[body_off + i] != static_cast<u8>(i & 0xff)) {
                    pattern_ok = false;
                    break;
                }
            }
            if (!pattern_ok) break;
            completed++;
        }
    }

    if (ssl != nullptr) {
        SSL_shutdown(ssl);
        SSL_free(ssl);
    }
    if (c >= 0) close(c);
    if (client_ctx != nullptr) SSL_CTX_free(client_ctx);
    backend.teardown();
    shard.stop();
    shard.join();
    shard.shutdown();
    close(lfd);
    destroy_tls_server_context(tls_ctx.value());
    return completed;
}

TEST(proxy_tls_iouring, keepalive_reuse_no_cancel_collision) {
    if (!iouring_socket_live()) SKIP("io_uring async socket ops unavailable in this environment");
    const char kReq[] = "GET /dl HTTP/1.1\r\nHost: x\r\n\r\n";
    // 8 KiB body: comfortably under the 16 KiB upstream_recv_buf even with headers,
    // so a one-batch loopback harvest can't -ENOBUFS-truncate the tail and masquerade
    // as a cancel-collision. Still a real multi-recv stream that pauses per request.
    CHECK_EQ(run_keepalive_reuse(kReq, sizeof(kReq) - 1, 8u * 1024u, 30u), 30u);
}

// Same reuse stress with POST: each request forwards a request body to the upstream
// before the response streams back, so the proxy exercises the request-body upload
// path ahead of every cancel-by-fd. All 30 must still complete intact.
TEST(proxy_tls_iouring, keepalive_reuse_post_body_no_cancel_collision) {
    if (!iouring_socket_live()) SKIP("io_uring async socket ops unavailable in this environment");
    const char kReq[] =
        "POST /dl HTTP/1.1\r\nHost: x\r\nContent-Length: 16\r\n\r\n0123456789abcdef";
    // 8 KiB body: comfortably under the 16 KiB upstream_recv_buf even with headers,
    // so a one-batch loopback harvest can't -ENOBUFS-truncate the tail and masquerade
    // as a cancel-collision. Still a real multi-recv stream that pauses per request.
    CHECK_EQ(run_keepalive_reuse(kReq, sizeof(kReq) - 1, 8u * 1024u, 30u), 30u);
}

// Informational proxy latency/throughput benchmark (keep-alive, real io_uring).
// Gated behind RUT_BENCH so it only runs in the dedicated bench CI job; prints
// req/s and p50/p99 per-request latency to the log so a change like cancel-by-fd
// (off the per-byte path → expected no-op) can be eyeballed against history. NOT a
// pass/fail perf gate (shared CI runners are too noisy for a stable threshold) — it
// asserts only that every request completes, so a gross regression that hangs or
// truncates still fails the job.
TEST(proxy_tls_iouring, keepalive_latency_bench) {
    if (std::getenv("RUT_BENCH") == nullptr) SKIP("set RUT_BENCH=1 to run the proxy bench");
    if (!iouring_socket_live()) SKIP("io_uring async socket ops unavailable in this environment");
    using namespace rut;

    constexpr u32 kBody = 4u * 1024u;
    constexpr u32 kN = 5000u;
    ReuseUpstream backend;
    REQUIRE(backend.setup(kBody));

    RouteConfig cfg{};
    auto id = cfg.add_upstream("b", 0x7F000001, backend.port);
    REQUIRE(id.has_value());
    REQUIRE(cfg.add_proxy("/dl", 0, id.value()));
    const RouteConfig* active = &cfg;

    auto tls_ctx = create_tls_server_context(kTestCertPath, kTestKeyPath);
    REQUIRE(tls_ctx.has_value());

    Shard<IoUringEventLoop> shard;
    i32 lfd = create_listen_socket(0).value_or(-1);
    REQUIRE(lfd >= 0);
    u16 port = get_port(lfd);
    REQUIRE(shard.init(0, lfd).has_value());
    shard.loop->tls_server = tls_ctx.value();
    shard.loop->config_ptr = &active;
    REQUIRE(shard.spawn(-1).has_value());
    usleep(50000);

    SSL_CTX* client_ctx = create_test_client_ctx();
    REQUIRE(client_ctx != nullptr);
    i32 c = connect_to(port);
    REQUIRE(c >= 0);
    set_socket_timeouts(c, 5);
    SSL* ssl = SSL_new(client_ctx);
    REQUIRE(ssl != nullptr);
    REQUIRE(SSL_set_fd(ssl, c) == 1);
    REQUIRE(SSL_connect(ssl) == 1);

    const char kReq[] = "GET /dl HTTP/1.1\r\nHost: x\r\n\r\n";
    static u8 in[64u * 1024u];
    static u64 lat_ns[kN];
    u32 completed = 0;
    auto now_ns = []() -> u64 {
        struct timespec t;
        clock_gettime(CLOCK_MONOTONIC, &t);
        return static_cast<u64>(t.tv_sec) * 1000000000ull + static_cast<u64>(t.tv_nsec);
    };
    const u64 t0 = now_ns();
    for (u32 r = 0; r < kN; r++) {
        const u64 ta = now_ns();
        if (!ssl_write_all(ssl, kReq, sizeof(kReq) - 1)) break;
        u32 total = 0, body_off = 0, body_seen = 0;
        bool hdr_done = false;
        while (body_seen < kBody && total < sizeof(in)) {
            const i32 n = SSL_read(ssl, in + total, static_cast<i32>(sizeof(in) - total));
            if (n <= 0) break;
            total += static_cast<u32>(n);
            if (!hdr_done) {
                for (u32 i = 3; i < total; i++) {
                    if (in[i - 3] == '\r' && in[i - 2] == '\n' && in[i - 1] == '\r' &&
                        in[i] == '\n') {
                        hdr_done = true;
                        body_off = i + 1;
                        break;
                    }
                }
            }
            if (hdr_done) body_seen = total - body_off;
        }
        if (!hdr_done || body_seen < kBody) break;
        lat_ns[completed++] = now_ns() - ta;
    }
    const u64 total_ns = now_ns() - t0;

    // Tear down BEFORE asserting. Shard has no destructor that stops its thread, so an
    // early return on a failed assertion would leave the io_uring shard running with
    // pointers to this frame's config/TLS state — a leaked thread and a later flaky
    // crash. Stop everything first, then report and assert.
    SSL_shutdown(ssl);
    SSL_free(ssl);
    close(c);
    SSL_CTX_free(client_ctx);
    backend.teardown();
    shard.stop();
    shard.join();
    shard.shutdown();
    close(lfd);
    destroy_tls_server_context(tls_ctx.value());

    if (completed > 0) {
        std::sort(lat_ns, lat_ns + completed);
        const u32 kP50Idx = completed / 2;
        const u32 kP99Idx = completed * 99 / 100;
        const double rps = static_cast<double>(completed) * 1e9 / static_cast<double>(total_ns);
        const double p50_us = static_cast<double>(lat_ns[kP50Idx]) / 1e3;
        const double p99_us = static_cast<double>(lat_ns[kP99Idx]) / 1e3;
        const u32 kBodyKiB = kBody / 1024u;
        fprintf(stderr,
                "[bench] proxy keep-alive over TLS: %u reqs in %.1f ms => %.0f req/s | "
                "p50=%.1f us p99=%.1f us (body=%u KiB)\n",
                completed,
                static_cast<double>(total_ns) / 1e6,
                rps,
                p50_us,
                p99_us,
                kBodyKiB);
    }
    CHECK_EQ(completed, kN);  // non-fatal: teardown already ran, so a hang/truncation
                              // regression fails cleanly without leaking the shard
}

// === ALPN selection (pure logic, no crypto) ===

TEST(alpn, picks_h2_when_offered_and_requested) {
    const u8 client[] = {2, 'h', '2', 8, 'h', 't', 't', 'p', '/', '1', '.', '1'};
    CHECK(alpn_pick(true, client, sizeof(client)) == AlpnProtocol::H2);
}

TEST(alpn, downgrades_to_http11_when_h2_not_offered) {
    const u8 client[] = {2, 'h', '2', 8, 'h', 't', 't', 'p', '/', '1', '.', '1'};
    CHECK(alpn_pick(false, client, sizeof(client)) == AlpnProtocol::Http11);
}

TEST(alpn, picks_http11_when_client_only_offers_http11) {
    const u8 client[] = {8, 'h', 't', 't', 'p', '/', '1', '.', '1'};
    CHECK(alpn_pick(true, client, sizeof(client)) == AlpnProtocol::Http11);
}

TEST(alpn, no_overlap_returns_none) {
    // Client offers only h2 but server doesn't advertise it.
    const u8 client[] = {2, 'h', '2'};
    CHECK(alpn_pick(false, client, sizeof(client)) == AlpnProtocol::None);
    // Unknown protocol with no http/1.1 fallback.
    const u8 spdy[] = {6, 's', 'p', 'd', 'y', '/', '3'};
    CHECK(alpn_pick(true, spdy, sizeof(spdy)) == AlpnProtocol::None);
}

TEST(alpn, empty_or_null_client_list_returns_none) {
    CHECK(alpn_pick(true, nullptr, 0) == AlpnProtocol::None);
    const u8 empty[] = {0};
    CHECK(alpn_pick(true, empty, 0) == AlpnProtocol::None);
}

TEST(alpn, truncated_entry_does_not_overrun) {
    // Length prefix claims 8 bytes but only 3 remain — must stop, not read OOB.
    const u8 client[] = {8, 'h', 't', 't'};
    CHECK(alpn_pick(true, client, sizeof(client)) == AlpnProtocol::None);
}

// === ALPN negotiation end-to-end over a real loopback TLS handshake ===

namespace {
// Run one real handshake: a shard with `server_offer_h2` against a client
// advertising `client_protos`. Returns the protocol the client observes the
// server selected (the same value the server stores on conn.protocol).
AlpnProtocol negotiate_alpn(bool server_offer_h2, const u8* client_protos, u32 client_len) {
    auto tls_ctx = create_tls_server_context(kTestCertPath, kTestKeyPath, server_offer_h2);
    if (!tls_ctx.has_value()) return AlpnProtocol::None;

    Shard<EpollEventLoop> shard;
    i32 lfd = create_listen_socket(0).value_or(-1);
    if (lfd < 0) {
        destroy_tls_server_context(tls_ctx.value());
        return AlpnProtocol::None;
    }
    u16 port = get_port(lfd);
    shard.init(0, lfd);
    shard.loop->tls_server = tls_ctx.value();
    shard.spawn(-1);
    usleep(50000);

    SSL_CTX* client_ctx = create_test_client_ctx();
    SSL_CTX_set_alpn_protos(client_ctx, client_protos, client_len);

    i32 c = connect_to(port);
    set_socket_timeouts(c, 2);
    SSL* ssl = SSL_new(client_ctx);
    SSL_set_fd(ssl, c);

    AlpnProtocol result = AlpnProtocol::None;
    if (SSL_connect(ssl) == 1) {
        // Client and server observe the same negotiated protocol.
        result = tls_negotiated_protocol(ssl);
    }

    SSL_shutdown(ssl);
    SSL_free(ssl);
    close(c);
    SSL_CTX_free(client_ctx);
    shard.stop();
    shard.join();
    shard.shutdown();
    close(lfd);
    destroy_tls_server_context(tls_ctx.value());
    return result;
}
}  // namespace

TEST(shard, negotiates_h2_via_alpn) {
    const u8 client[] = {2, 'h', '2', 8, 'h', 't', 't', 'p', '/', '1', '.', '1'};
    CHECK(negotiate_alpn(/*server_offer_h2=*/true, client, sizeof(client)) == AlpnProtocol::H2);
}

TEST(shard, downgrades_h2_client_when_server_offers_only_http11) {
    const u8 client[] = {2, 'h', '2', 8, 'h', 't', 't', 'p', '/', '1', '.', '1'};
    CHECK(negotiate_alpn(/*server_offer_h2=*/false, client, sizeof(client)) ==
          AlpnProtocol::Http11);
}

TEST(shard, serves_https_keepalive_requests) {
    auto tls_ctx = create_tls_server_context(kTestCertPath, kTestKeyPath);
    REQUIRE(tls_ctx.has_value());

    Shard<EpollEventLoop> shard;
    i32 lfd = create_listen_socket(0).value_or(-1);
    REQUIRE(lfd >= 0);
    u16 port = get_port(lfd);
    REQUIRE(shard.init(0, lfd).has_value());
    shard.loop->tls_server = tls_ctx.value();
    REQUIRE(shard.spawn(-1).has_value());

    usleep(50000);

    SSL_CTX* client_ctx = create_test_client_ctx();
    REQUIRE(client_ctx != nullptr);

    i32 c = connect_to(port);
    REQUIRE(c >= 0);
    set_socket_timeouts(c, 2);

    SSL* ssl = SSL_new(client_ctx);
    REQUIRE(ssl != nullptr);
    REQUIRE(SSL_set_fd(ssl, c) == 1);
    REQUIRE(SSL_connect(ssl) == 1);

    for (int i = 0; i < 3; i++) {
        REQUIRE(ssl_write_all(ssl, HTTP_REQ, HTTP_REQ_LEN));
        char buf[4096];
        i32 n = SSL_read(ssl, buf, sizeof(buf));
        CHECK(n > 0);
        if (n > 0) CHECK(has_200(buf, n));
    }

    SSL_shutdown(ssl);
    SSL_free(ssl);
    close(c);
    SSL_CTX_free(client_ctx);

    shard.stop();
    shard.join();
    shard.shutdown();
    close(lfd);
    destroy_tls_server_context(tls_ctx.value());
}

TEST(shard, recovers_after_failed_tls_handshake) {
    auto tls_ctx = create_tls_server_context(kTestCertPath, kTestKeyPath);
    REQUIRE(tls_ctx.has_value());

    Shard<EpollEventLoop> shard;
    i32 lfd = create_listen_socket(0).value_or(-1);
    REQUIRE(lfd >= 0);
    u16 port = get_port(lfd);
    REQUIRE(shard.init(0, lfd).has_value());
    shard.loop->tls_server = tls_ctx.value();
    REQUIRE(shard.spawn(-1).has_value());

    usleep(50000);

    i32 bad = connect_to(port);
    REQUIRE(bad >= 0);
    set_socket_timeouts(bad, 1);
    REQUIRE(send_all(bad, HTTP_REQ, HTTP_REQ_LEN));
    char drain[64];
    recv_timeout(bad, drain, sizeof(drain), 200);
    close(bad);

    SSL_CTX* client_ctx = create_test_client_ctx();
    REQUIRE(client_ctx != nullptr);

    i32 c = connect_to(port);
    REQUIRE(c >= 0);
    set_socket_timeouts(c, 2);

    SSL* ssl = SSL_new(client_ctx);
    REQUIRE(ssl != nullptr);
    REQUIRE(SSL_set_fd(ssl, c) == 1);
    REQUIRE(SSL_connect(ssl) == 1);
    REQUIRE(ssl_write_all(ssl, HTTP_REQ, HTTP_REQ_LEN));

    char buf[4096];
    i32 n = SSL_read(ssl, buf, sizeof(buf));
    CHECK(n > 0);
    if (n > 0) CHECK(has_200(buf, n));

    SSL_shutdown(ssl);
    SSL_free(ssl);
    close(c);
    SSL_CTX_free(client_ctx);

    shard.stop();
    shard.join();
    shard.shutdown();
    close(lfd);
    destroy_tls_server_context(tls_ctx.value());
}

// Two shards on same port (SO_REUSEPORT)
TEST(shard, two_shards_same_port) {
    i32 lfd1 = create_listen_socket(0).value_or(-1);
    REQUIRE(lfd1 >= 0);
    u16 port = get_port(lfd1);
    i32 lfd2 = create_listen_socket(port).value_or(-1);
    REQUIRE(lfd2 >= 0);

    Shard<EpollEventLoop> s1, s2;
    REQUIRE(s1.init(0, lfd1).has_value());
    REQUIRE(s2.init(1, lfd2).has_value());
    REQUIRE(s1.spawn(-1).has_value());
    REQUIRE(s2.spawn(-1).has_value());

    usleep(50000);

    // Send requests — kernel distributes across shards
    for (int i = 0; i < 5; i++) {
        i32 c = connect_to(port);
        REQUIRE(c >= 0);
        REQUIRE(send_all(c, HTTP_REQ, HTTP_REQ_LEN));
        char buf[4096];
        i32 n = recv_timeout(c, buf, sizeof(buf), 2000);
        CHECK(n > 0);
        close(c);
    }

    s1.stop();
    s2.stop();
    s1.join();
    s2.join();
    s1.shutdown();
    s2.shutdown();
    close(lfd1);
    close(lfd2);
}

