#if RUT_ENABLE_JIT_TESTS
// End-to-end wait(ms) through the real EpollEventLoop: compile a route
// that yields briefly and returns 204, register it as a JitHandler
// in the RouteConfig, drive a real TCP connection, and assert the client
// observes the 204 response after the timer fires.
//
// Timing note: EpollEventLoop now uses a one-shot yield_timer_fd + min-heap
// driven by absolute CLOCK_MONOTONIC deadlines with ms precision (no
// TimerWheel bucketing). Use a non-1s wait so this smoke test does not race
// the periodic keepalive wheel tick; exact sub-second timing is covered by
// wait_ms_precision_sub_second below.
TEST(route, wait_jit_handler_real_socket) {
    using namespace rut;  // pull in compiler helpers (lex / parse_file / ...)

    const char* src = "route GET \"/sleep\" { wait(250) return 204 }\n";
    auto lexed = lex(Str{src, static_cast<u32>(strlen(src))});
    REQUIRE(lexed);
    auto ast = parse_file(lexed.value());
    REQUIRE(ast);
    std::unique_ptr<AstFile> ast_owned(ast.value());
    auto hir = analyze_file(*ast_owned);
    REQUIRE(hir);
    std::unique_ptr<HirModule> hir_owned(hir.value());
    auto mir = build_mir(*hir_owned);
    REQUIRE(mir);
    std::unique_ptr<MirModule> mir_owned(mir.value());
    FrontendRirModule rir{};
    auto lowered = lower_to_rir(*mir_owned, rir);
    REQUIRE(lowered);
    auto cg = jit::codegen(rir.module);
    REQUIRE(cg.ok);
    jit::JitEngine engine;
    REQUIRE(engine.init());
    REQUIRE(engine.compile(cg.mod, cg.ctx));
    auto handler_fn = reinterpret_cast<jit::HandlerFn>(engine.lookup("handler_route_0"));
    REQUIRE(handler_fn != nullptr);

    RouteConfig cfg{};
    REQUIRE(cfg.add_jit_handler("/sleep", 'G', handler_fn));
    const RouteConfig* active = &cfg;

    RealLoop* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto lfd_result = create_listen_socket(0);
    REQUIRE(lfd_result.has_value());
    i32 lfd = lfd_result.value();
    u16 port = get_port(lfd);
    REQUIRE(loop->init(0, lfd).has_value());
    loop->config_ptr = &active;
    LoopThread lt = {loop, {}, 200};
    lt.start();
    // Let the loop thread register the listener before the client connects.
    // Without this, this smoke test can be flaky when it runs immediately
    // after io_uring backend tests on a busy runner.
    usleep(10000);

    i32 c = connect_to(port);
    REQUIRE(c >= 0);
    REQUIRE(send_all(c, "GET /sleep HTTP/1.1\r\nHost: x\r\n\r\n", 32));
    char buf[1024];
    i32 n = recv_timeout(c, buf, sizeof(buf), 3000);
    CHECK_GT(n, 0);
    // Response should contain the 204 status code.
    bool found_204 = false;
    for (i32 i = 0; i + 2 < n; i++) {
        if (buf[i] == '2' && buf[i + 1] == '0' && buf[i + 2] == '4') {
            found_204 = true;
            break;
        }
    }
    CHECK(found_204);
    close(c);
    lt.stop();
    loop->shutdown();
    close(lfd);
    destroy_real_loop(loop);
    engine.shutdown();
    rir.destroy();
}

// End-to-end async-yield over HTTP/2: a JIT handler that wait(ms)s then returns
// 200 must suspend its h2 stream and resume to emit the response. Before the h2
// async path this answered 503 (yielding handlers unsupported); now the stream
// parks on a real yield timer (h2_suspend_timer → schedule_yield_timer) and
// resumes through h2_resume_jit_handler to serialize the HEADERS frame. Driven
// over cleartext h2c on the real EpollEventLoop so the timer actually fires.
TEST(shard, serves_http2_async_wait_jit_handler) {
    using namespace rut;

    const char* src = "route GET \"/sleep\" { wait(50) return 200 }\n";
    auto lexed = lex(Str{src, static_cast<u32>(strlen(src))});
    REQUIRE(lexed);
    auto ast = parse_file(lexed.value());
    REQUIRE(ast);
    std::unique_ptr<AstFile> ast_owned(ast.value());
    auto hir = analyze_file(*ast_owned);
    REQUIRE(hir);
    std::unique_ptr<HirModule> hir_owned(hir.value());
    auto mir = build_mir(*hir_owned);
    REQUIRE(mir);
    std::unique_ptr<MirModule> mir_owned(mir.value());
    FrontendRirModule rir{};
    auto lowered = lower_to_rir(*mir_owned, rir);
    REQUIRE(lowered);
    auto cg = jit::codegen(rir.module);
    REQUIRE(cg.ok);
    jit::JitEngine engine;
    REQUIRE(engine.init());
    REQUIRE(engine.compile(cg.mod, cg.ctx));
    auto handler_fn = reinterpret_cast<jit::HandlerFn>(engine.lookup("handler_route_0"));
    REQUIRE(handler_fn != nullptr);

    RouteConfig cfg{};
    REQUIRE(cfg.add_jit_handler("/sleep", 'G', handler_fn));
    const RouteConfig* active = &cfg;

    RealLoop* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto lfd_result = create_listen_socket(0);
    REQUIRE(lfd_result.has_value());
    i32 lfd = lfd_result.value();
    u16 port = get_port(lfd);
    REQUIRE(loop->init(0, lfd).has_value());
    loop->config_ptr = &active;
    LoopThread lt = {loop, {}, 200};
    lt.start();
    usleep(10000);

    i32 c = connect_to(port);
    REQUIRE(c >= 0);
    set_socket_timeouts(c, 2);

    u8 out[512];
    u32 n = h2_client_prologue(out);
    n += h2_client_get(out + n, sizeof(out) - n, 1, "/sleep", 6);
    REQUIRE(write_all_fd(c, out, n));

    u8 resp[4096];
    u32 total = 0;
    for (int attempt = 0; attempt < 8 && total < sizeof(resp); attempt++) {
        i32 got =
            recv_timeout(c, reinterpret_cast<char*>(resp + total), sizeof(resp) - total, 2000);
        if (got <= 0) break;
        total += static_cast<u32>(got);
        if (h2_status_for_stream(resp, total, 1) != 0) break;
    }
    // 200 (not 503) proves the suspend/resume round-trip completed.
    CHECK_EQ(h2_status_for_stream(resp, total, 1), 200u);

    close(c);
    lt.stop();
    loop->shutdown();
    close(lfd);
    destroy_real_loop(loop);
    engine.shutdown();
    rir.destroy();
}

// Two async-yield requests in sequence on one h2 connection: after the first
// stream resumes and flushes, the connection must re-arm recv (async slot
// cleared) and serve the next stream's wait→200 the same way. Exercises the
// resume → read → next-request lifecycle in on_h2_sent that single-shot tests
// miss.
TEST(shard, serves_http2_async_wait_sequential) {
    using namespace rut;

    const char* src = "route GET \"/sleep\" { wait(30) return 200 }\n";
    auto lexed = lex(Str{src, static_cast<u32>(strlen(src))});
    REQUIRE(lexed);
    auto ast = parse_file(lexed.value());
    REQUIRE(ast);
    std::unique_ptr<AstFile> ast_owned(ast.value());
    auto hir = analyze_file(*ast_owned);
    REQUIRE(hir);
    std::unique_ptr<HirModule> hir_owned(hir.value());
    auto mir = build_mir(*hir_owned);
    REQUIRE(mir);
    std::unique_ptr<MirModule> mir_owned(mir.value());
    FrontendRirModule rir{};
    auto lowered = lower_to_rir(*mir_owned, rir);
    REQUIRE(lowered);
    auto cg = jit::codegen(rir.module);
    REQUIRE(cg.ok);
    jit::JitEngine engine;
    REQUIRE(engine.init());
    REQUIRE(engine.compile(cg.mod, cg.ctx));
    auto handler_fn = reinterpret_cast<jit::HandlerFn>(engine.lookup("handler_route_0"));
    REQUIRE(handler_fn != nullptr);

    RouteConfig cfg{};
    REQUIRE(cfg.add_jit_handler("/sleep", 'G', handler_fn));
    const RouteConfig* active = &cfg;

    RealLoop* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto lfd_result = create_listen_socket(0);
    REQUIRE(lfd_result.has_value());
    i32 lfd = lfd_result.value();
    u16 port = get_port(lfd);
    REQUIRE(loop->init(0, lfd).has_value());
    loop->config_ptr = &active;
    LoopThread lt = {loop, {}, 200};
    lt.start();
    usleep(10000);

    i32 c = connect_to(port);
    REQUIRE(c >= 0);
    set_socket_timeouts(c, 2);

    auto send_and_read_status = [&](u32 stream_id) -> u16 {
        u8 out[512];
        u32 n = 0;
        if (stream_id == 1) n = h2_client_prologue(out);  // preface + SETTINGS once
        n += h2_client_get(out + n, sizeof(out) - n, stream_id, "/sleep", 6);
        if (!write_all_fd(c, out, n)) return 0;
        u8 resp[4096];
        u32 total = 0;
        for (int attempt = 0; attempt < 8 && total < sizeof(resp); attempt++) {
            i32 got =
                recv_timeout(c, reinterpret_cast<char*>(resp + total), sizeof(resp) - total, 2000);
            if (got <= 0) break;
            total += static_cast<u32>(got);
            if (h2_status_for_stream(resp, total, stream_id) != 0) break;
        }
        return h2_status_for_stream(resp, total, stream_id);
    };

    CHECK_EQ(send_and_read_status(1), 200u);  // first wait→200
    CHECK_EQ(send_and_read_status(3), 200u);  // connection served the next stream

    close(c);
    lt.stop();
    loop->shutdown();
    close(lfd);
    destroy_real_loop(loop);
    engine.shutdown();
    rir.destroy();
}

// Two async-yield streams coalesced into one TCP read. The first parks; the
// engine must STOP processing and leave the second's HEADERS buffered (rather
// than dispatch it while a stream is already suspended → 503). After the first
// resumes, the buffered second stream is drained and also served. Regression for
// the one-at-a-time queuing fix (process() stop-after-park + on_h2_sent drain).
TEST(shard, serves_http2_async_wait_coalesced) {
    using namespace rut;

    const char* src = "route GET \"/sleep\" { wait(30) return 200 }\n";
    auto lexed = lex(Str{src, static_cast<u32>(strlen(src))});
    REQUIRE(lexed);
    auto ast = parse_file(lexed.value());
    REQUIRE(ast);
    std::unique_ptr<AstFile> ast_owned(ast.value());
    auto hir = analyze_file(*ast_owned);
    REQUIRE(hir);
    std::unique_ptr<HirModule> hir_owned(hir.value());
    auto mir = build_mir(*hir_owned);
    REQUIRE(mir);
    std::unique_ptr<MirModule> mir_owned(mir.value());
    FrontendRirModule rir{};
    auto lowered = lower_to_rir(*mir_owned, rir);
    REQUIRE(lowered);
    auto cg = jit::codegen(rir.module);
    REQUIRE(cg.ok);
    jit::JitEngine engine;
    REQUIRE(engine.init());
    REQUIRE(engine.compile(cg.mod, cg.ctx));
    auto handler_fn = reinterpret_cast<jit::HandlerFn>(engine.lookup("handler_route_0"));
    REQUIRE(handler_fn != nullptr);

    RouteConfig cfg{};
    REQUIRE(cfg.add_jit_handler("/sleep", 'G', handler_fn));
    const RouteConfig* active = &cfg;

    RealLoop* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto lfd_result = create_listen_socket(0);
    REQUIRE(lfd_result.has_value());
    i32 lfd = lfd_result.value();
    u16 port = get_port(lfd);
    REQUIRE(loop->init(0, lfd).has_value());
    loop->config_ptr = &active;
    LoopThread lt = {loop, {}, 300};
    lt.start();
    usleep(10000);

    i32 c = connect_to(port);
    REQUIRE(c >= 0);
    set_socket_timeouts(c, 2);

    // Both streams in ONE write so they arrive coalesced in a single read.
    u8 out[512];
    u32 n = h2_client_prologue(out);
    n += h2_client_get(out + n, sizeof(out) - n, 1, "/sleep", 6);
    n += h2_client_get(out + n, sizeof(out) - n, 3, "/sleep", 6);
    REQUIRE(write_all_fd(c, out, n));

    u8 resp[4096];
    u32 total = 0;
    for (int attempt = 0; attempt < 12 && total < sizeof(resp); attempt++) {
        i32 got =
            recv_timeout(c, reinterpret_cast<char*>(resp + total), sizeof(resp) - total, 2000);
        if (got <= 0) break;
        total += static_cast<u32>(got);
        if (h2_status_for_stream(resp, total, 3) != 0) break;
    }
    CHECK_EQ(h2_status_for_stream(resp, total, 1), 200u);  // first parked stream
    CHECK_EQ(h2_status_for_stream(resp, total, 3), 200u);  // queued, not 503

    close(c);
    lt.stop();
    loop->shutdown();
    close(lfd);
    destroy_real_loop(loop);
    engine.shutdown();
    rir.destroy();
}

// wait(50) — sub-second precision verification. The legacy TimerWheel
// would round this up to 1000ms (one full tick), so this test fails
// immediately if the yield_timer_fd / min-heap path regresses back to
// the wheel. Observed wall time must land well below one second.
TEST(route, wait_ms_precision_sub_second) {
    using namespace rut;

    const char* src = "route GET \"/snooze\" { wait(50) return 204 }\n";
    auto lexed = lex(Str{src, static_cast<u32>(strlen(src))});
    REQUIRE(lexed);
    auto ast = parse_file(lexed.value());
    REQUIRE(ast);
    std::unique_ptr<AstFile> ast_owned(ast.value());
    auto hir = analyze_file(*ast_owned);
    REQUIRE(hir);
    std::unique_ptr<HirModule> hir_owned(hir.value());
    auto mir = build_mir(*hir_owned);
    REQUIRE(mir);
    std::unique_ptr<MirModule> mir_owned(mir.value());
    FrontendRirModule rir{};
    auto lowered = lower_to_rir(*mir_owned, rir);
    REQUIRE(lowered);
    auto cg = jit::codegen(rir.module);
    REQUIRE(cg.ok);
    jit::JitEngine engine;
    REQUIRE(engine.init());
    REQUIRE(engine.compile(cg.mod, cg.ctx));
    auto handler_fn = reinterpret_cast<jit::HandlerFn>(engine.lookup("handler_route_0"));
    REQUIRE(handler_fn != nullptr);

    RouteConfig cfg{};
    REQUIRE(cfg.add_jit_handler("/snooze", 'G', handler_fn));
    const RouteConfig* active = &cfg;

    RealLoop* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto lfd_result = create_listen_socket(0);
    REQUIRE(lfd_result.has_value());
    i32 lfd = lfd_result.value();
    u16 port = get_port(lfd);
    REQUIRE(loop->init(0, lfd).has_value());
    loop->config_ptr = &active;
    LoopThread lt = {loop, {}, 200};
    lt.start();

    i32 c = connect_to(port);
    REQUIRE(c >= 0);

    struct timespec t0;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    send_all(c, "GET /snooze HTTP/1.1\r\nHost: x\r\n\r\n", 33);
    char buf[1024];
    i32 n = recv_timeout(c, buf, sizeof(buf), 2000);
    struct timespec t1;
    clock_gettime(CLOCK_MONOTONIC, &t1);
    // Compute delta in signed nanoseconds so tv_nsec underflow (t1.tv_nsec
    // < t0.tv_nsec) doesn't wrap to a huge u64 when the tv_sec carry should
    // handle it.
    i64 elapsed_ns = static_cast<i64>(t1.tv_sec - t0.tv_sec) * 1'000'000'000LL +
                     (static_cast<i64>(t1.tv_nsec) - static_cast<i64>(t0.tv_nsec));
    i64 elapsed_ms = elapsed_ns / 1'000'000LL;

    CHECK_GT(n, 0);
    bool found_204 = false;
    for (i32 i = 0; i + 2 < n; i++) {
        if (buf[i] == '2' && buf[i + 1] == '0' && buf[i + 2] == '4') {
            found_204 = true;
            break;
        }
    }
    CHECK(found_204);
    // 50ms wait should complete in well under a second. The legacy
    // TimerWheel rounds to 1000ms; a 500ms ceiling proves we're using
    // the yield_timer_fd / IORING_OP_TIMEOUT path. Floor at 40ms
    // protects against any accidental zero-wait regression.
    CHECK_GT(elapsed_ms, 40);
    CHECK_LT(elapsed_ms, 500);

    close(c);
    lt.stop();
    loop->shutdown();
    close(lfd);
    destroy_real_loop(loop);
    engine.shutdown();
    rir.destroy();
}

// Slice 1: a let initializer whose value drives the terminal return
// must survive across a wait. The current codegen re-materializes the
// local inside the terminal block, which works for pure initializers.
// End-to-end check via a real JIT + epoll loop that `let code = 201;
// wait(100); if code == 201 { return 201 } else { return 500 }` returns
// 201, proving the local's value reaches the branch post-yield.
TEST(route, let_across_wait_drives_return_real_socket) {
    using namespace rut;

    const char* src =
        "route GET \"/let\" { let code = 201 wait(100) if code == 201 { return 201 } else { "
        "return 500 } }\n";
    auto lexed = lex(Str{src, static_cast<u32>(strlen(src))});
    REQUIRE(lexed);
    auto ast = parse_file(lexed.value());
    REQUIRE(ast);
    std::unique_ptr<AstFile> ast_owned(ast.value());
    auto hir = analyze_file(*ast_owned);
    REQUIRE(hir);
    std::unique_ptr<HirModule> hir_owned(hir.value());
    auto mir = build_mir(*hir_owned);
    REQUIRE(mir);
    std::unique_ptr<MirModule> mir_owned(mir.value());
    FrontendRirModule rir{};
    auto lowered = lower_to_rir(*mir_owned, rir);
    REQUIRE(lowered);
    auto cg = jit::codegen(rir.module);
    REQUIRE(cg.ok);
    jit::JitEngine engine;
    REQUIRE(engine.init());
    REQUIRE(engine.compile(cg.mod, cg.ctx));
    auto handler_fn = reinterpret_cast<jit::HandlerFn>(engine.lookup("handler_route_0"));
    REQUIRE(handler_fn != nullptr);

    RouteConfig cfg{};
    REQUIRE(cfg.add_jit_handler("/let", 'G', handler_fn));
    const RouteConfig* active = &cfg;

    RealLoop* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto lfd_result = create_listen_socket(0);
    REQUIRE(lfd_result.has_value());
    i32 lfd = lfd_result.value();
    u16 port = get_port(lfd);
    REQUIRE(loop->init(0, lfd).has_value());
    loop->config_ptr = &active;
    LoopThread lt = {loop, {}, 200};
    lt.start();

    i32 c = connect_to(port);
    REQUIRE(c >= 0);
    const char kLetReq[] = "GET /let HTTP/1.1\r\nHost: x\r\n\r\n";
    struct timespec t0;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    send_all(c, kLetReq, sizeof(kLetReq) - 1);
    char buf[1024];
    i32 n = recv_timeout(c, buf, sizeof(buf), 2000);
    struct timespec t1;
    clock_gettime(CLOCK_MONOTONIC, &t1);
    i64 elapsed_ns = static_cast<i64>(t1.tv_sec - t0.tv_sec) * 1'000'000'000LL +
                     (static_cast<i64>(t1.tv_nsec) - static_cast<i64>(t0.tv_nsec));
    i64 elapsed_ms = elapsed_ns / 1'000'000LL;

    CHECK_GT(n, 0);
    bool found_201 = false;
    for (i32 i = 0; i + 2 < n; i++) {
        if (buf[i] == '2' && buf[i + 1] == '0' && buf[i + 2] == '1') {
            found_201 = true;
            break;
        }
    }
    CHECK(found_201);
    // wait(100) must actually fire — otherwise this test could pass
    // even if the yield path was bypassed and state 0 fell through
    // to state N immediately. Floor at 80ms for scheduler jitter on
    // slow CI; ceiling at 500ms to flag anything unusually slow.
    CHECK_GT(elapsed_ms, 80);
    CHECK_LT(elapsed_ms, 500);

    close(c);
    lt.stop();
    loop->shutdown();
    close(lfd);
    destroy_real_loop(loop);
    engine.shutdown();
    rir.destroy();
}

// Regression: a wait(ms) longer than keepalive_timeout must NOT be woken
// early by the 1-second TimerWheel tick. Before the fix, yielded conns
// remained on the keepalive wheel and the tick callback resumed them via
// the `pending_handler_fn` branch — a wait(2000) would fire at ~1000ms.
//
// Uses keepalive_timeout=1s + wait(2000ms) to hit the bug fast. Asserts
// elapsed >= 1700ms (clear margin above the 1s tick).
TEST(route, wait_longer_than_keepalive_not_resumed_by_wheel) {
    using namespace rut;

    const char* src = "route GET \"/deep\" { wait(2000) return 204 }\n";
    auto lexed = lex(Str{src, static_cast<u32>(strlen(src))});
    REQUIRE(lexed);
    auto ast = parse_file(lexed.value());
    REQUIRE(ast);
    std::unique_ptr<AstFile> ast_owned(ast.value());
    auto hir = analyze_file(*ast_owned);
    REQUIRE(hir);
    std::unique_ptr<HirModule> hir_owned(hir.value());
    auto mir = build_mir(*hir_owned);
    REQUIRE(mir);
    std::unique_ptr<MirModule> mir_owned(mir.value());
    FrontendRirModule rir{};
    auto lowered = lower_to_rir(*mir_owned, rir);
    REQUIRE(lowered);
    auto cg = jit::codegen(rir.module);
    REQUIRE(cg.ok);
    jit::JitEngine engine;
    REQUIRE(engine.init());
    REQUIRE(engine.compile(cg.mod, cg.ctx));
    auto handler_fn = reinterpret_cast<jit::HandlerFn>(engine.lookup("handler_route_0"));
    REQUIRE(handler_fn != nullptr);

    RouteConfig cfg{};
    REQUIRE(cfg.add_jit_handler("/deep", 'G', handler_fn));
    const RouteConfig* active = &cfg;

    RealLoop* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto lfd_result = create_listen_socket(0);
    REQUIRE(lfd_result.has_value());
    i32 lfd = lfd_result.value();
    u16 port = get_port(lfd);
    REQUIRE(loop->init(0, lfd).has_value());
    loop->config_ptr = &active;
    // Shrink keepalive so a 2s wait clearly exceeds it. Wheel tick
    // before the fix would resume the handler around 1s.
    loop->keepalive_timeout = 1;
    LoopThread lt = {loop, {}, 200};
    lt.start();

    i32 c = connect_to(port);
    REQUIRE(c >= 0);

    struct timespec t0;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    send_all(c, "GET /deep HTTP/1.1\r\nHost: x\r\n\r\n", 31);
    char buf[1024];
    i32 n = recv_timeout(c, buf, sizeof(buf), 4000);
    struct timespec t1;
    clock_gettime(CLOCK_MONOTONIC, &t1);
    // Compute delta in signed nanoseconds so tv_nsec underflow (t1.tv_nsec
    // < t0.tv_nsec) doesn't wrap to a huge u64 when the tv_sec carry should
    // handle it.
    i64 elapsed_ns = static_cast<i64>(t1.tv_sec - t0.tv_sec) * 1'000'000'000LL +
                     (static_cast<i64>(t1.tv_nsec) - static_cast<i64>(t0.tv_nsec));
    i64 elapsed_ms = elapsed_ns / 1'000'000LL;

    CHECK_GT(n, 0);
    bool found_204 = false;
    for (i32 i = 0; i + 2 < n; i++) {
        if (buf[i] == '2' && buf[i + 1] == '0' && buf[i + 2] == '4') {
            found_204 = true;
            break;
        }
    }
    CHECK(found_204);
    // Must not have been woken by the 1s wheel tick. 1700ms floor leaves
    // comfortable margin above the tick; 3000ms ceiling catches stuck
    // timers. wait(2000) on an unloaded loop lands near 2000ms.
    CHECK_GT(elapsed_ms, 1700);
    CHECK_LT(elapsed_ms, 3000);

    close(c);
    lt.stop();
    loop->shutdown();
    close(lfd);
    destroy_real_loop(loop);
    engine.shutdown();
    rir.destroy();
}
#endif

// Minimal hand-written handler that returns a Forward action. Matches the
// jit::HandlerFn ABI so callbacks_impl.h's handle_jit_outcome can dispatch
// it the same way it would a real JIT-compiled handler.
static u64 forward_upstream_0_handler(void* /*conn*/,
                                      rut::jit::HandlerCtx* /*ctx*/,
                                      const u8* /*req*/,
                                      u32 /*len*/,
                                      void* /*arena*/) {
    auto r = rut::jit::HandlerResult::make_forward(0);
    return r.pack();
}

