// Runtime defense-in-depth vector: source analysis rejects this combination,
// so a direct handler leaves a pending response mutation for handle_jit_outcome
// to reject before apply_request_policy can rewrite recv_buf.
static u64 forward_request_policy_with_pending_mutation_handler(void* raw_conn,
                                                                rut::jit::HandlerCtx* /*ctx*/,
                                                                const u8* /*req*/,
                                                                u32 /*len*/,
                                                                void* /*arena*/) {
    auto* conn = static_cast<rut::Connection*>(raw_conn);
    conn->resp_header_mutation_pending_count = 1;
    return forward_request_policy_1_handler(nullptr, nullptr, nullptr, 0, nullptr);
}

// Mirrors a compiled chain that mutates response headers and then forwards.
// X-Path deliberately borrows the synthesized request target so the h2 proxy
// must keep it stable after pending_synth is reused for response frames.
static u64 forward_with_response_mutations_handler(
    void* raw_conn, rut::jit::HandlerCtx* /*ctx*/, const u8* req, u32 len, void* /*arena*/) {
    auto* conn = static_cast<rut::Connection*>(raw_conn);
    if (len < 8) return rut::jit::HandlerResult::make_status(500).pack();
    auto add = [&](rut::ConnectionBase::RespHeaderMutationMode mode,
                   const char* name,
                   u32 name_len,
                   const char* value,
                   u32 value_len) {
        auto& mutation = conn->resp_header_mutations[conn->resp_header_mutation_count++];
        mutation.mode = mode;
        mutation.name = {name, name_len};
        mutation.value = {value, value_len};
    };
    add(rut::ConnectionBase::RespHeaderMutationMode::Set,
        "X-Path",
        6,
        reinterpret_cast<const char*>(req + 4),
        4);
    add(rut::ConnectionBase::RespHeaderMutationMode::Set,
        "X-Folded",
        8,
        reinterpret_cast<const char*>(req + 4),
        4);
    add(rut::ConnectionBase::RespHeaderMutationMode::Set, "X-Folded", 8, "final", 5);
    add(rut::ConnectionBase::RespHeaderMutationMode::Remove, "X-Remove", 8, nullptr, 0);
    add(rut::ConnectionBase::RespHeaderMutationMode::Add, "X-Multi", 7, "second", 6);
    return rut::jit::HandlerResult::make_forward(0).pack();
}

// Mirrors a chain-after mutation whose value is req.params.id. The matcher
// originally exposes the value from Http2Conn::hdr_scratch; the serving layer
// must re-anchor it before the upstream response reuses pending_synth.
static u64 forward_with_param_mutation_handler(
    void* raw_conn, rut::jit::HandlerCtx* ctx, const u8*, u32, void*) {
    if (ctx == nullptr || ctx->route_param_count != 1)
        return rut::jit::HandlerResult::make_status(500).pack();
    auto* conn = static_cast<rut::Connection*>(raw_conn);
    auto& mutation = conn->resp_header_mutations[conn->resp_header_mutation_count++];
    mutation.mode = rut::ConnectionBase::RespHeaderMutationMode::Set;
    mutation.name = {"X-Param", 7};
    mutation.value = {ctx->route_params[0].value, ctx->route_params[0].value_len};
    return rut::jit::HandlerResult::make_forward(0).pack();
}

static u64 wait_then_forward_with_request_overrides_handler(
    void* raw_conn, rut::jit::HandlerCtx* ctx, const u8* req, u32 len, void*) {
    if (ctx != nullptr && ctx->state == 7) return rut::jit::HandlerResult::make_forward(0).pack();
    auto find_value = [&](const char* prefix, u32 prefix_len, u32 value_len) -> const char* {
        for (u32 i = 0; i + prefix_len + value_len <= len; i++) {
            if (__builtin_memcmp(req + i, prefix, prefix_len) == 0)
                return reinterpret_cast<const char*>(req + i + prefix_len);
        }
        return nullptr;
    };
    const char* path = find_value("x-new-path: ", 12, 10);
    const char* token = find_value("x-token: ", 9, 7);
    if (path == nullptr || token == nullptr)
        return rut::jit::HandlerResult::make_status(500).pack();
    auto* conn = static_cast<rut::Connection*>(raw_conn);
    conn->req_path_overridden = true;
    conn->req_path_override = {path, 10};
    conn->req_header_override_count = 1;
    conn->req_header_overrides[0] = {{"X-Copied", 8}, {token, 7}};
    conn->req_header_append_mask = 0;
    return rut::jit::HandlerResult::make_yield_payload(
               7, rut::jit::YieldKind::Timer, /*milliseconds=*/20)
        .pack();
}

#if RUT_ENABLE_JIT_TESTS
// Test-only RIR/JIT fixture for target-transform H2 coverage.  There is
// intentionally no source syntax for this effect yet, so these handlers are
// built from the real RIR opcode and compiled through the production JIT.
struct H2TargetTransformJit {
    FrontendRirModule rir{};
    jit::JitEngine engine{};
    jit::HandlerFn handler_fn = nullptr;
    bool engine_ready = false;

    ~H2TargetTransformJit() {
        if (engine_ready) engine.shutdown();
        rir.destroy();
    }

    static Str literal(const char* text) {
        u32 len = 0;
        while (text[len] != '\0') len++;
        return {text, len};
    }

    bool init(bool with_timer, bool with_request_policy = false) {
        if (!rir.init(2, 1)) return false;
        rir::Builder b;
        b.init(&rir.module);

        auto fn_result =
            b.create_function(with_timer ? literal("target_resume") : literal("target_initial"),
                              literal("/api"),
                              'G');
        if (!fn_result) return false;
        auto* fn = fn_result.value();
        auto entry_result = b.create_block(fn, literal("entry"));
        if (!entry_result) return false;
        const auto entry = entry_result.value();
        auto emit_forward = [&](rir::ValueId upstream) -> rir::VoidResult {
            if (!with_request_policy) return b.emit_ret_forward(upstream);
            auto policy = b.emit_const_i32(1);
            if (!policy) return rir::err(rir::RirError::InvalidState);
            return b.emit_ret_forward(upstream, policy.value());
        };

        if (!with_timer) {
            b.set_insert_point(fn, entry);
            if (!b.emit_req_set_target_transform(1)) return false;
            auto upstream = b.emit_const_i32(0);
            if (!upstream || !emit_forward(upstream.value())) return false;
        } else {
            auto resume_result = b.create_block(fn, literal("resume"));
            if (!resume_result) return false;
            const auto resume = resume_result.value();
            const u32 payloads[] = {20};
            const u8 kinds[] = {static_cast<u8>(jit::YieldKind::Timer)};
            if (!b.set_yield_payload(fn, payloads, 1, kinds)) return false;
            const rir::BlockId resume_blocks[] = {entry, resume};
            if (!b.set_explicit_resume_blocks(fn, resume_blocks, 2)) return false;

            b.set_insert_point(fn, entry);
            if (!b.emit_yield_timer(20, 1)) return false;
            b.set_insert_point(fn, resume);
            if (!b.emit_req_set_target_transform(1)) return false;
            auto upstream = b.emit_const_i32(0);
            if (!upstream || !emit_forward(upstream.value())) return false;
        }

        auto cg = jit::codegen(rir.module);
        if (!cg.ok || !engine.init()) return false;
        engine_ready = true;
        if (!engine.compile(cg.mod, cg.ctx)) return false;
        const char* symbol = with_timer ? "handler_target_resume" : "handler_target_initial";
        handler_fn = reinterpret_cast<jit::HandlerFn>(engine.lookup(symbol));
        return handler_fn != nullptr;
    }
};

static u64 h2_target_transform_plain_200_handler(
    void* /*conn*/, jit::HandlerCtx* /*ctx*/, const u8* /*req*/, u32 /*len*/, void* /*arena*/) {
    return jit::HandlerResult::make_status(200).pack();
}

template <typename Loop>
struct H2TargetTransformShardGuard {
    Shard<Loop>& shard;
    i32& listen_fd;
    i32 client_fd = -1;
    bool spawned = false;

    ~H2TargetTransformShardGuard() {
        if (client_fd >= 0) close(client_fd);
        if (spawned) {
            shard.stop();
            shard.join();
        }
        shard.shutdown();
        if (listen_fd >= 0) close(listen_fd);
    }
};

#endif

// End-to-end: a JIT handler returning Forward must kick off the same
// proxy flow as a RouteAction::Proxy match. Before the JIT forward wire-up,
// handle_jit_outcome::Forward returned 500; this test guards against that
// regression. Mirrors replay_gap::proxy_route_enters_proxy_state but with
// the JitHandler route action.
TEST(route, forward_jit_handler_enters_proxy_state) {
    using namespace rut;

    RouteConfig cfg{};
    auto up = cfg.add_upstream("backend", 0x7F000001, 9999);
    REQUIRE(up.has_value());
    REQUIRE_EQ(up.value(), 0u);  // first upstream → id 0 in cfg
    REQUIRE(cfg.add_jit_handler("/api", 'G', &forward_upstream_0_handler));
    const RouteConfig* active = &cfg;

    RealLoop* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto lfd_result = create_listen_socket(0);
    REQUIRE(lfd_result.has_value());
    i32 lfd = lfd_result.value();
    u16 port = get_port(lfd);
    REQUIRE(loop->init(0, lfd).has_value());
    loop->config_ptr = &active;
    LoopThread lt = {loop, {}, 100};
    lt.start();

    i32 c = connect_to(port);
    REQUIRE(c >= 0);
    send_all(c, "GET /api HTTP/1.1\r\nHost: x\r\n\r\n", 30);

    // The request triggers the JIT handler → Forward → submit_connect
    // to 127.0.0.1:9999. No upstream is listening, so the connect will
    // fail with ECONNREFUSED and the loop will send a 502 (or close).
    // The assertion we care about is that a 502 came back — proving
    // Forward routed through the proxy path instead of the pre-fix
    // 500 response.
    char buf[1024];
    i32 n = recv_timeout(c, buf, sizeof(buf), 500);
    CHECK_GT(n, 0);
    bool found_502 = false;
    for (i32 i = 0; i + 2 < n; i++) {
        if (buf[i] == '5' && buf[i + 1] == '0' && buf[i + 2] == '2') {
            found_502 = true;
            break;
        }
    }
    CHECK(found_502);

    close(c);
    lt.stop();
    loop->shutdown();
    close(lfd);
    destroy_real_loop(loop);
}

// Regression for the #127 review: a JIT `return forward(<upstream>)` route must
// honor the upstream max_inflight cap, same as the direct RouteAction::Proxy
// path. With cap 1, while a slow forwarded request holds the slot, a second
// concurrent forward to the same backend is shed with 503 — before the fix the
// JIT Forward branch skipped the acquire and would open a second upstream
// connection, exceeding the cap.
TEST(upstream_concurrency_e2e, jit_forward_honors_max_inflight) {
    using namespace rut;
    SlowResponseServer backend;
    REQUIRE(backend.setup(400));  // hold each upstream conn ~400ms

    RouteConfig cfg{};
    auto id = cfg.add_upstream("b", 0x7F000001, backend.port);
    REQUIRE(id.has_value());
    REQUIRE_EQ(id.value(), 0u);  // forward_upstream_0_handler forwards to id 0
    REQUIRE(cfg.add_jit_handler("/p", 'G', &forward_upstream_0_handler));
    REQUIRE(cfg.set_upstream_max_inflight(id.value(), 1));
    const RouteConfig* active = &cfg;

    UpstreamConcurrency cc{};  // fresh shared gauge for this test
    cc.reset();

    RealLoop* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto lfd = create_listen_socket(0);
    REQUIRE(lfd.has_value());
    const i32 listen_fd = lfd.value();
    const u16 port = get_port(listen_fd);
    REQUIRE(loop->init(0, listen_fd).has_value());
    loop->config_ptr = &active;
    loop->upstream_cc = &cc;
    LoopThread lt = {loop, {}, 5000};
    lt.start();

    const char kReq[] = "GET /p HTTP/1.1\r\nHost: x\r\n\r\n";
    char buf[1024];

    // c1 takes the only slot via the JIT forward path (backend holds ~400ms).
    i32 c1 = connect_to(port);
    REQUIRE(c1 >= 0);
    REQUIRE(send_all(c1, kReq, sizeof(kReq) - 1));
    usleep(150000);  // 150ms: c1's slot is acquired, backend is sleeping

    // c2 forwards to the same backend at capacity → 503.
    i32 c2 = connect_to(port);
    REQUIRE(c2 >= 0);
    REQUIRE(send_all(c2, kReq, sizeof(kReq) - 1));
    i32 n2 = recv_timeout(c2, buf, sizeof(buf), 2000);
    CHECK(n2 > 0 && buf_contains(buf, static_cast<u32>(n2), "503", 3));
    close(c2);

    // c1 completes (200) and frees the slot.
    i32 n1 = recv_timeout(c1, buf, sizeof(buf), 2000);
    CHECK(n1 > 0 && buf_contains(buf, static_cast<u32>(n1), "200", 3));
    close(c1);

    lt.stop();
    loop->shutdown();
    close(listen_fd);
    destroy_real_loop(loop);
}

// Bad upstream_id (out of bounds) → handle_jit_outcome must return 502
// rather than crash or hang. Guards the defensive bound check in the
// Forward branch.
static u64 forward_upstream_99_handler(void* /*conn*/,
                                       rut::jit::HandlerCtx* /*ctx*/,
                                       const u8* /*req*/,
                                       u32 /*len*/,
                                       void* /*arena*/) {
    auto r = rut::jit::HandlerResult::make_forward(99);
    return r.pack();
}

TEST(route, forward_jit_handler_rejects_unknown_upstream_id) {
    using namespace rut;

    RouteConfig cfg{};
    // Only one upstream at id 0; handler returns 99.
    REQUIRE(cfg.add_upstream("backend", 0x7F000001, 9999));
    REQUIRE(cfg.add_jit_handler("/api", 'G', &forward_upstream_99_handler));
    const RouteConfig* active = &cfg;

    RealLoop* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto lfd_result = create_listen_socket(0);
    REQUIRE(lfd_result.has_value());
    i32 lfd = lfd_result.value();
    u16 port = get_port(lfd);
    REQUIRE(loop->init(0, lfd).has_value());
    loop->config_ptr = &active;
    LoopThread lt = {loop, {}, 100};
    lt.start();

    i32 c = connect_to(port);
    REQUIRE(c >= 0);
    send_all(c, "GET /api HTTP/1.1\r\nHost: x\r\n\r\n", 30);
    char buf[1024];
    i32 n = recv_timeout(c, buf, sizeof(buf), 500);
    CHECK_GT(n, 0);
    bool found_502 = false;
    for (i32 i = 0; i + 2 < n; i++) {
        if (buf[i] == '5' && buf[i + 1] == '0' && buf[i + 2] == '2') {
            found_502 = true;
            break;
        }
    }
    CHECK(found_502);

    close(c);
    lt.stop();
    loop->shutdown();
    close(lfd);
    destroy_real_loop(loop);
}

// Minimal hand-written JIT handler that returns ReturnStatus(200)
// with upstream_id = 1 — the ABI slot for a 1-based response-body
// index. Used to validate the runtime body-render path without
// needing the (not-yet-wired) compiler pipeline for bodies.
static u64 return_200_with_body_1_handler(void* /*conn*/,
                                          rut::jit::HandlerCtx* /*ctx*/,
                                          const u8* /*req*/,
                                          u32 /*len*/,
                                          void* /*arena*/) {
    rut::jit::HandlerResult r{rut::jit::HandlerAction::ReturnStatus,
                              200,
                              /*upstream_id=*/1,
                              0,
                              rut::jit::YieldKind::HttpGet};
    return r.pack();
}

// End-to-end: handler returns ReturnStatus with body_idx=1;
// RouteConfig has a body pre-registered; runtime formats response
// with the body bytes + matching Content-Length + default Content-Type.
// HTTP/2: a JIT handler returning a status + body, served over h2c. Exercises
// the native h2 dispatch → request synthesis → handler invoke → HEADERS+DATA.
TEST(shard, serves_http2_jit_handler_with_body) {
    using namespace rut;

    RouteConfig cfg{};
    const char kBody[] = "Hello, world";
    REQUIRE_EQ(cfg.add_response_body(kBody, sizeof(kBody) - 1), 1u);
    REQUIRE(cfg.add_jit_handler("/hello", 'G', &return_200_with_body_1_handler));

    Shard<EpollEventLoop> shard;
    i32 lfd = create_listen_socket(0).value_or(-1);
    REQUIRE(lfd >= 0);
    u16 port = get_port(lfd);
    REQUIRE(shard.init(0, lfd).has_value());
    shard.route_config = &cfg;
    REQUIRE(shard.spawn(-1).has_value());
    usleep(50000);

    i32 c = connect_to(port);
    REQUIRE(c >= 0);
    set_socket_timeouts(c, 2);

    u8 out[512];
    u32 n = h2_client_prologue(out);
    n += h2_client_get(out + n, sizeof(out) - n, 1, "/hello", 6);
    REQUIRE(write_all_fd(c, out, n));

    u8 resp[4096];
    u32 total = 0;
    for (int attempt = 0; attempt < 6 && total < sizeof(resp); attempt++) {
        i32 got =
            recv_timeout(c, reinterpret_cast<char*>(resp + total), sizeof(resp) - total, 2000);
        if (got <= 0) break;
        total += static_cast<u32>(got);
        u8 body[256];
        if (h2_status_for_stream(resp, total, 1) != 0 &&
            h2_body_for_stream(resp, total, 1, body, sizeof(body)) >= sizeof(kBody) - 1)
            break;
    }
    CHECK_EQ(h2_status_for_stream(resp, total, 1), 200u);
    u8 body[256];
    u32 blen = h2_body_for_stream(resp, total, 1, body, sizeof(body));
    CHECK_EQ(blen, sizeof(kBody) - 1);
    bool body_ok = blen == sizeof(kBody) - 1;
    for (u32 i = 0; i < blen && body_ok; i++)
        if (body[i] != static_cast<u8>(kBody[i])) body_ok = false;
    CHECK(body_ok);

    close(c);
    shard.stop();
    shard.join();
    shard.shutdown();
    close(lfd);
}

TEST(route, jit_handler_custom_body_real_socket) {
    using namespace rut;

    RouteConfig cfg{};
    const char kBody[] = "Hello, world";
    const u16 body_idx = cfg.add_response_body(kBody, sizeof(kBody) - 1);
    REQUIRE_EQ(body_idx, 1u);
    REQUIRE(cfg.add_jit_handler("/hello", 'G', &return_200_with_body_1_handler));
    const RouteConfig* active = &cfg;

    RealLoop* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto lfd_result = create_listen_socket(0);
    REQUIRE(lfd_result.has_value());
    i32 lfd = lfd_result.value();
    u16 port = get_port(lfd);
    REQUIRE(loop->init(0, lfd).has_value());
    loop->config_ptr = &active;
    LoopThread lt = {loop, {}, 100};
    lt.start();

    i32 c = connect_to(port);
    REQUIRE(c >= 0);
    const char kReq[] = "GET /hello HTTP/1.1\r\nHost: x\r\n\r\n";
    send_all(c, kReq, sizeof(kReq) - 1);
    char buf[2048];
    i32 n = recv_timeout(c, buf, sizeof(buf), 10000);
    REQUIRE_GT(n, 0);
    buf[n < static_cast<i32>(sizeof(buf)) ? n : static_cast<i32>(sizeof(buf)) - 1] = '\0';

    // Response must contain "200", "Content-Length: 12", default
    // Content-Type, and the body bytes literal.
    const Str response{buf, static_cast<u32>(n)};
    bool has_200 = false;
    bool has_cl = false;
    bool has_ct = false;
    bool has_body = false;
    for (u32 i = 0; i + 2 < response.len; i++) {
        if (response.ptr[i] == '2' && response.ptr[i + 1] == '0' && response.ptr[i + 2] == '0') {
            has_200 = true;
            break;
        }
    }
    static const char kCL[] = "Content-Length: 12";
    for (u32 i = 0; i + sizeof(kCL) - 1 <= response.len; i++) {
        bool match = true;
        for (u32 j = 0; j < sizeof(kCL) - 1; j++) {
            if (response.ptr[i + j] != static_cast<u8>(kCL[j])) {
                match = false;
                break;
            }
        }
        if (match) {
            has_cl = true;
            break;
        }
    }
    static const char kCT[] = "Content-Type: text/plain";
    for (u32 i = 0; i + sizeof(kCT) - 1 <= response.len; i++) {
        bool match = true;
        for (u32 j = 0; j < sizeof(kCT) - 1; j++) {
            if (response.ptr[i + j] != static_cast<u8>(kCT[j])) {
                match = false;
                break;
            }
        }
        if (match) {
            has_ct = true;
            break;
        }
    }
    for (u32 i = 0; i + sizeof(kBody) - 1 <= response.len; i++) {
        bool match = true;
        for (u32 j = 0; j < sizeof(kBody) - 1; j++) {
            if (response.ptr[i + j] != static_cast<u8>(kBody[j])) {
                match = false;
                break;
            }
        }
        if (match) {
            has_body = true;
            break;
        }
    }
    CHECK(has_200);
    CHECK(has_cl);
    CHECK(has_ct);
    CHECK(has_body);

    close(c);
    lt.stop();
    loop->shutdown();
    close(lfd);
    destroy_real_loop(loop);
}

struct ScriptedUpstreamServer {
    i32 listen_fd = -1;
    u16 port = 0;
    const char* response = nullptr;
    u32 response_len = 0;
    bool keep_open = false;  // hold the connection open after replying (HTTP keep-alive)
    char request[1024]{};
    std::atomic<u32> request_len{0};
    std::atomic<bool> running{false};
    bool started = false;
    pthread_t thread{};

    ~ScriptedUpstreamServer() { teardown(); }

    static bool set_blocking(i32 fd) {
        i32 flags = fcntl(fd, F_GETFL, 0);
        if (flags < 0) return false;
        return fcntl(fd, F_SETFL, flags & ~O_NONBLOCK) == 0;
    }

    static void* run(void* arg) {
        auto* server = static_cast<ScriptedUpstreamServer*>(arg);
        i32 client = -1;
        const i32 accept_fd = server->listen_fd;
        while (server->running.load(std::memory_order_acquire)) {
            client = accept(accept_fd, nullptr, nullptr);
            if (client >= 0) break;
            if (errno == EINTR) continue;
            if (errno != EAGAIN && errno != EWOULDBLOCK) break;
            usleep(1000);
        }
        if (client >= 0) {
            if (set_blocking(client)) {
                const i32 got =
                    recv_timeout(client, server->request, sizeof(server->request), 1000);
                if (got > 0)
                    server->request_len.store(static_cast<u32>(got), std::memory_order_release);
                if (server->response != nullptr && server->response_len > 0) {
                    (void)send_all(client, server->response, server->response_len);
                }
                // keep_open simulates a keep-alive upstream that does NOT close
                // after a body-less response — the case that would hang an h2
                // proxy waiting for EOF if no-body statuses weren't special-cased.
                while (server->keep_open && server->running.load(std::memory_order_acquire))
                    usleep(5000);
            }
            close(client);
        }
        return nullptr;
    }

    bool setup(const char* bytes, u32 len) {
        auto lfd_result = create_listen_socket(0);
        if (!lfd_result.has_value()) return false;
        listen_fd = lfd_result.value();
        port = get_port(listen_fd);
        response = bytes;
        response_len = len;
        running.store(true, std::memory_order_release);
        if (pthread_create(&thread, nullptr, run, this) != 0) {
            running.store(false, std::memory_order_release);
            close(listen_fd);
            listen_fd = -1;
            return false;
        }
        started = true;
        return true;
    }

    void teardown() {
        running.store(false, std::memory_order_release);
        if (started) {
            pthread_join(thread, nullptr);
            started = false;
        }
        if (listen_fd >= 0) {
            close(listen_fd);
            listen_fd = -1;
        }
    }
};

struct ScopedProxyLoop {
    RealLoop* loop = nullptr;
    i32 listen_fd = -1;
    u16 port = 0;
    LoopThread lt{};
    bool loop_started = false;
    UpstreamPool* pool = nullptr;  // wired only when enable_reuse=true (idle reuse)

    ~ScopedProxyLoop() { teardown(); }

    bool setup(const RouteConfig** active,
               i32 iters,
               bool enable_reuse = false,
               const ListenerSpec* declared_listener = nullptr) {
        loop = create_real_loop();
        if (loop == nullptr) return false;
        auto lfd_result = create_listen_socket(0);
        if (!lfd_result.has_value()) {
            teardown();
            return false;
        }
        listen_fd = lfd_result.value();
        port = get_port(listen_fd);
        if (!loop->init(0, listen_fd).has_value()) {
            teardown();
            return false;
        }
        loop->config_ptr = active;
        if (enable_reuse) {
            pool = new UpstreamPool();
            pool->init();
            loop->upstream = pool;  // enable HTTP/1 idle upstream connection reuse
        }
        if (declared_listener != nullptr) {
            auto context = derive_listener_context(listen_fd, *declared_listener);
            if (!context) {
                teardown();
                return false;
            }
            // Install before the loop thread starts, matching run_shards()'s
            // post-init/pre-spawn listener-context contract.
            loop->listener_context = context.value();
        }
        lt.loop = loop;
        lt.thread = {};
        lt.max_iters = iters;
        lt.start();
        loop_started = true;
        return true;
    }

    void teardown() {
        if (loop_started) {
            lt.stop();
            loop_started = false;
        }
        if (loop != nullptr) {
            loop->shutdown();
        }
        if (listen_fd >= 0) {
            close(listen_fd);
            listen_fd = -1;
        }
        port = 0;
        if (loop != nullptr) {
            destroy_real_loop(loop);
            loop = nullptr;
        }
        if (pool != nullptr) {
            pool->shutdown();
            delete pool;
            pool = nullptr;
        }
    }
};

// Upstream that serves many keep-alive requests per TCP connection and counts how
// many distinct connections it accepted — so a test can prove the gateway reused a
// single upstream socket across several proxied requests. Each request ends at the
// CRLFCRLF header terminator (GETs have no body); each gets a fixed keep-alive 200.
struct KeepAliveCountingUpstream {
    i32 listen_fd = -1;
    u16 port = 0;
    std::atomic<int> accept_count{0};
    std::atomic<bool> running{false};
    bool started = false;
    pthread_t thread{};

    ~KeepAliveCountingUpstream() { teardown(); }

    static void* run(void* arg) {
        auto* s = static_cast<KeepAliveCountingUpstream*>(arg);
        static const char kResp[] =
            "HTTP/1.1 200 OK\r\nContent-Length: 2\r\nConnection: keep-alive\r\n\r\nhi";
        while (s->running.load(std::memory_order_acquire)) {
            i32 c = accept(s->listen_fd, nullptr, nullptr);
            if (c < 0) {
                if (errno == EINTR || errno == EAGAIN || errno == EWOULDBLOCK) {
                    usleep(1000);
                    continue;
                }
                break;
            }
            s->accept_count.fetch_add(1, std::memory_order_relaxed);
            char buf[4096];
            u32 have = 0;
            while (s->running.load(std::memory_order_acquire)) {
                i32 n = recv_timeout(c, buf + have, sizeof(buf) - have, 1000);
                if (n <= 0) break;  // peer closed / idle timeout → end this connection
                have += static_cast<u32>(n);
                u32 scan = 0;
                for (u32 i = scan; i + 4 <= have; i++) {
                    if (buf[i] == '\r' && buf[i + 1] == '\n' && buf[i + 2] == '\r' &&
                        buf[i + 3] == '\n') {
                        (void)send_all(c, kResp, sizeof(kResp) - 1);
                        scan = i + 4;
                    }
                }
                if (scan > 0) {
                    __builtin_memmove(buf, buf + scan, have - scan);
                    have -= scan;
                }
            }
            close(c);
        }
        return nullptr;
    }

    bool setup() {
        auto lfd = create_listen_socket(0);
        if (!lfd.has_value()) return false;
        listen_fd = lfd.value();
        port = get_port(listen_fd);
        running.store(true, std::memory_order_release);
        started = (pthread_create(&thread, nullptr, &run, this) == 0);
        return started;
    }

    void teardown() {
        running.store(false, std::memory_order_release);
        if (started) {
            pthread_join(thread, nullptr);
            started = false;
        }
        if (listen_fd >= 0) {
            close(listen_fd);
            listen_fd = -1;
        }
    }
};

template <typename ShardT>
bool wait_for_idle_pool_count(ShardT& shard, u32 expected, u32 timeout_ms = 1000) {
    for (u32 waited = 0; waited < timeout_ms; waited++) {
        if (shard.upstream &&
            shard.upstream->idle_count.load(std::memory_order_acquire) >= expected)
            return true;
        usleep(1000);
    }
    return shard.upstream && shard.upstream->idle_count.load(std::memory_order_acquire) >= expected;
}

// End-to-end: three sequential keep-alive requests on ONE client connection to a
// proxy route must share a SINGLE upstream connection — the gateway returns the
// upstream fd to the per-shard idle pool after each response and borrows it back
// for the next request, so the backend accepts exactly one TCP connection.
TEST(proxy_reuse, reuses_idle_upstream_across_keepalive_requests) {
    KeepAliveCountingUpstream backend;
    REQUIRE(backend.setup());

    RouteConfig cfg{};
    auto uid = cfg.add_upstream("api", 0x7F000001, backend.port);
    REQUIRE(uid.has_value());
    REQUIRE(cfg.add_proxy("/api", 0, static_cast<u16>(uid.value())));
    const RouteConfig* active = &cfg;

    ScopedProxyLoop proxy;
    REQUIRE(proxy.setup(&active, 4000, /*enable_reuse=*/true));

    i32 c = connect_to(proxy.port);
    REQUIRE(c >= 0);
    set_socket_timeouts(c, 2);

    for (int i = 0; i < 3; i++) {
        const char kReq[] = "GET /api HTTP/1.1\r\nHost: x\r\n\r\n";
        REQUIRE(send_all(c, kReq, sizeof(kReq) - 1));
        char buf[256];
        i32 n = recv_timeout(c, buf, sizeof(buf), 2000);
        REQUIRE_GT(n, 0);
        CHECK(buf_contains(buf, static_cast<u32>(n), "200", 3));
    }
    close(c);
    usleep(50000);

    CHECK_EQ(backend.accept_count.load(), 1);  // one upstream connection, reused 3×
    CHECK_EQ(proxy.pool->idle_count, 1u);      // parked for the next request

    proxy.teardown();
}

// io_uring variant of the reuse e2e (Shard wires the pool for both backends). Unlike
// epoll's synchronous detach, io_uring defers the pool-return until the cancelled
// multishot recv drains, so the test waits until the fd actually re-enters the pool
// before the next request borrows it. Skips where io_uring is unavailable.
TEST(proxy_reuse, reuses_idle_upstream_iouring) {
    if (!iouring_socket_live()) SKIP("io_uring async socket ops unavailable in this environment");
    KeepAliveCountingUpstream backend;
    REQUIRE(backend.setup());

    RouteConfig cfg{};
    auto uid = cfg.add_upstream("api", 0x7F000001, backend.port);
    REQUIRE(uid.has_value());
    REQUIRE(cfg.add_proxy("/api", 0, static_cast<u16>(uid.value())));

    Shard<IoUringEventLoop> shard;
    i32 lfd = create_listen_socket(0).value_or(-1);
    REQUIRE(lfd >= 0);
    u16 port = get_port(lfd);
    REQUIRE(shard.init(0, lfd).has_value());
    shard.route_config = &cfg;
    REQUIRE(shard.spawn(-1).has_value());
    usleep(50000);

    i32 c = connect_to(port);
    REQUIRE(c >= 0);
    set_socket_timeouts(c, 2);

    for (int i = 0; i < 3; i++) {
        const char kReq[] = "GET /api HTTP/1.1\r\nHost: x\r\n\r\n";
        REQUIRE(send_all(c, kReq, sizeof(kReq) - 1));
        char buf[256];
        i32 n = recv_timeout(c, buf, sizeof(buf), 2000);
        REQUIRE_GT(n, 0);
        CHECK(buf_contains(buf, static_cast<u32>(n), "200", 3));
        REQUIRE(wait_for_idle_pool_count(shard, 1));  // deferred recv-cancel drained
    }
    close(c);
    usleep(50000);

    CHECK_EQ(backend.accept_count.load(), 1);  // one upstream connection, reused 3×

    shard.stop();
    shard.join();
    shard.shutdown();
    close(lfd);
}

// A request carrying Connection: close is forwarded to the origin as such, so the
// upstream fd must not be pooled: the origin is allowed to close it after the response.
// This mirrors the parsed-request keep-alive gate in the epoll path.
TEST(proxy_reuse, iouring_connection_close_request_not_pooled) {
    if (!iouring_socket_live()) SKIP("io_uring async socket ops unavailable in this environment");
    KeepAliveCountingUpstream backend;
    REQUIRE(backend.setup());

    RouteConfig cfg{};
    auto uid = cfg.add_upstream("api", 0x7F000001, backend.port);
    REQUIRE(uid.has_value());
    REQUIRE(cfg.add_proxy("/api", 0, static_cast<u16>(uid.value())));

    Shard<IoUringEventLoop> shard;
    i32 lfd = create_listen_socket(0).value_or(-1);
    REQUIRE(lfd >= 0);
    u16 port = get_port(lfd);
    REQUIRE(shard.init(0, lfd).has_value());
    shard.route_config = &cfg;
    REQUIRE(shard.spawn(-1).has_value());
    usleep(50000);

    // Three requests, each on its own downstream connection that asks the gateway to
    // close after the response (Connection: close → proxy_stream_complete tears the
    // conn down while the deferred upstream pool-return is mid-drain).
    for (int i = 0; i < 3; i++) {
        i32 c = connect_to(port);
        REQUIRE(c >= 0);
        set_socket_timeouts(c, 2);
        const char kReq[] = "GET /api HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n";
        REQUIRE(send_all(c, kReq, sizeof(kReq) - 1));
        char buf[256];
        i32 n = recv_timeout(c, buf, sizeof(buf), 2000);
        REQUIRE_GT(n, 0);
        CHECK(buf_contains(buf, static_cast<u32>(n), "200", 3));
        close(c);
    }
    usleep(50000);

    CHECK_EQ(backend.accept_count.load(), 3);
    CHECK_EQ(shard.upstream->idle_count.load(std::memory_order_acquire), 0u);

    shard.stop();
    shard.join();
    shard.shutdown();
    close(lfd);
}

// Unit-level coverage for the io_uring deferred idle-pool return guards. These
// drive try_deferred_upstream_rearm directly (the recv-drain terminal site) on a
// non-spawned shard, so they run without live io_uring async completions: only
// the shard's io_uring queue init must succeed (skipped otherwise). The end-to-end
// reuse paths above still cover the wired data path on CI/real Linux.
//
// F1 (config recheck): a hot reload between parking idle_return_fd and the recv
//   drain must close the parked fd rather than pool a stale-config socket.
// F2 (stale bytes): surplus upstream bytes copied into upstream_recv_buf while the
//   cancel drained desync reuse, so the fd must be closed, not pooled.
TEST(proxy_reuse, deferred_idle_return_guards_iouring) {
    Shard<IoUringEventLoop> shard;
    i32 lfd = create_listen_socket(0).value_or(-1);
    REQUIRE(lfd >= 0);
    if (!shard.init(0, lfd).has_value()) {
        close(lfd);
        SKIP("io_uring queue init unavailable in this environment");
    }
    RouteConfig cfg_a{};
    RouteConfig cfg_b{};

    // Match + empty buffer → pooled and reusable.
    {
        shard.active_config = &cfg_a;
        auto& c = shard.loop->conns[0];
        c.reset();
        i32 sv[2];
        REQUIRE_EQ(socketpair(AF_UNIX, SOCK_STREAM, 0, sv), 0);
        c.idle_return_fd = sv[0];
        c.idle_return_uid = 5;
        c.idle_return_bidx = 0;
        c.idle_return_config = &cfg_a;
        shard.loop->try_deferred_upstream_rearm(c);
        CHECK_EQ(c.idle_return_fd, -1);            // parked fd consumed
        CHECK_EQ(shard.upstream->idle_count, 1u);  // pooled, not closed
        CHECK_EQ(shard.upstream->take_idle(5, 0), sv[0]);
        close(sv[0]);
        close(sv[1]);
    }
    // Config swapped under the parked fd → closed, never pooled.
    {
        shard.active_config = &cfg_a;
        auto& c = shard.loop->conns[1];
        c.reset();
        i32 sv[2];
        REQUIRE_EQ(socketpair(AF_UNIX, SOCK_STREAM, 0, sv), 0);
        c.idle_return_fd = sv[0];
        c.idle_return_uid = 6;
        c.idle_return_bidx = 0;
        c.idle_return_config = &cfg_b;  // parked under a now-superseded config
        shard.loop->try_deferred_upstream_rearm(c);
        CHECK_EQ(c.idle_return_fd, -1);
        CHECK_EQ(shard.upstream->idle_count, 0u);  // refused: not pooled
        CHECK(::close(sv[0]) < 0);                 // try_deferred already closed it
        close(sv[1]);
    }
    // Config matches but stale bytes were copied into upstream_recv_buf → closed and
    // the stale buffer is dropped so a later request cannot parse it as a response.
    {
        shard.active_config = &cfg_a;
        auto& c = shard.loop->conns[2];
        c.reset();
        i32 sv[2];
        REQUIRE_EQ(socketpair(AF_UNIX, SOCK_STREAM, 0, sv), 0);
        u8 slice[64];
        c.upstream_recv_buf.bind(slice, sizeof(slice));
        const u8 junk[3] = {'a', 'b', 'c'};
        c.upstream_recv_buf.write(junk, 3);
        c.idle_return_fd = sv[0];
        c.idle_return_uid = 7;
        c.idle_return_bidx = 0;
        c.idle_return_config = &cfg_a;
        shard.loop->try_deferred_upstream_rearm(c);
        CHECK_EQ(c.idle_return_fd, -1);
        CHECK_EQ(shard.upstream->idle_count, 0u);  // refused: desynced socket
        CHECK_EQ(c.upstream_recv_buf.len(), 0u);
        CHECK(::close(sv[0]) < 0);  // closed, not pooled
        c.upstream_recv_buf.bind(nullptr, 0);
        close(sv[1]);
    }

    // A positive stale idle-return CQE rolls bytes back out of upstream_recv_buf before
    // the deferred drain runs; the separate marker must still make the fd non-reusable.
    {
        shard.active_config = &cfg_a;
        auto& c = shard.loop->conns[4];
        c.reset();
        i32 sv[2];
        REQUIRE_EQ(socketpair(AF_UNIX, SOCK_STREAM, 0, sv), 0);
        c.upstream_recv_idle_stale_bytes = true;
        c.idle_return_fd = sv[0];
        c.idle_return_uid = 9;
        c.idle_return_bidx = 0;
        c.idle_return_config = &cfg_a;
        shard.loop->try_deferred_upstream_rearm(c);
        CHECK_EQ(c.idle_return_fd, -1);
        CHECK(!c.upstream_recv_idle_stale_bytes);
        CHECK_EQ(shard.upstream->idle_count.load(std::memory_order_acquire), 0u);
        CHECK(::close(sv[0]) < 0);
        close(sv[1]);
    }

    // Idle-return cancellation marks the old recv terminal/data stale even when
    // resp_fully_buffered was already cleared by proxy completion.
    {
        shard.active_config = &cfg_a;
        auto& c = shard.loop->conns[3];
        c.reset();
        i32 sv[2];
        REQUIRE_EQ(socketpair(AF_UNIX, SOCK_STREAM, 0, sv), 0);
        c.id = 3;
        c.upstream_fd = sv[0];
        c.upstream_recv_armed = true;
        c.resp_fully_buffered = false;
        c.upstream_recv_terminal_stale = false;
        shard.loop->return_idle_upstream(c, 8, 0);
        CHECK(c.upstream_recv_terminal_stale);
        if (c.idle_return_fd >= 0) {
            close(c.idle_return_fd);
            c.idle_return_fd = -1;
        }
        close(sv[1]);
    }

    shard.shutdown();
    close(lfd);
}

// F3: forced drain-deadline shutdown and normal shard shutdown must close a parked
// idle_return_fd whose recv cancel may never drain. No leak, no double-close.
TEST(proxy_reuse, force_close_all_closes_deferred_idle_fd_iouring) {
    Shard<IoUringEventLoop> shard;
    i32 lfd = create_listen_socket(0).value_or(-1);
    REQUIRE(lfd >= 0);
    if (!shard.init(0, lfd).has_value()) {
        close(lfd);
        SKIP("io_uring queue init unavailable in this environment");
    }
    RouteConfig cfg{};
    shard.active_config = &cfg;

    // Live client (fd >= 0) with a parked upstream fd whose recv is still draining.
    auto& live = shard.loop->conns[0];
    live.reset();
    i32 cli[2];
    i32 up0[2];
    REQUIRE_EQ(socketpair(AF_UNIX, SOCK_STREAM, 0, cli), 0);
    REQUIRE_EQ(socketpair(AF_UNIX, SOCK_STREAM, 0, up0), 0);
    live.fd = cli[0];
    live.pending_ops = 0;
    live.upstream_recv_cancel_inflight = true;  // recv draining → close_conn defers
    live.idle_return_fd = up0[0];
    live.idle_return_uid = 9;
    live.idle_return_bidx = 0;
    live.idle_return_config = &cfg;

    // Already-deferred-closed slot (client fd already gone).
    auto& deferred = shard.loop->conns[1];
    deferred.reset();
    i32 up1[2];
    REQUIRE_EQ(socketpair(AF_UNIX, SOCK_STREAM, 0, up1), 0);
    deferred.fd = -1;
    deferred.idle_return_fd = up1[0];
    deferred.idle_return_uid = 11;
    deferred.idle_return_bidx = 0;

    shard.loop->force_close_all();

    CHECK_EQ(live.idle_return_fd, -1);
    CHECK_EQ(deferred.idle_return_fd, -1);
    CHECK(::close(cli[0]) < 0);  // client fd closed by close_conn
    CHECK(::close(up0[0]) < 0);  // parked upstream fd closed (live-client case)
    CHECK(::close(up1[0]) < 0);  // parked upstream fd closed (deferred-close case)
    close(cli[1]);
    close(up0[1]);
    close(up1[1]);

    // Normal shutdown has no drain-deadline force_close_all call, but must still
    // scan per-connection parked fds before destroying the loop.
    auto& normal = shard.loop->conns[2];
    normal.reset();
    i32 up2[2];
    REQUIRE_EQ(socketpair(AF_UNIX, SOCK_STREAM, 0, up2), 0);
    normal.idle_return_fd = up2[0];

    shard.shutdown();
    CHECK(::close(up2[0]) < 0);
    close(up2[1]);
    close(lfd);
}

// End-to-end proxy over HTTP/2: an h2c client requests a RouteAction::Proxy
// route; the runtime forwards a synthesized h1 request to a real upstream, buffers
// the upstream's h1 response, and re-encodes it as h2 HEADERS+DATA. Asserts the
// h2 client sees the re-framed :status and body (proves h2_proxy_begin →
// h2_on_upstream_* → h2_proxy_finish, not the old 503).
TEST(shard, serves_http2_proxy) {
    ScriptedUpstreamServer backend;
    static const char kResp[] =
        "HTTP/1.1 200 OK\r\n"
        "Content-Length: 5\r\n"
        "X-Backend: rut\r\n"
        "Te: gzip\r\n"           // hop-by-hop — must NOT be forwarded to the h2 client
        "Connection: x-hop\r\n"  // nominates x-hop as connection-specific (hop-by-hop)
        "X-Hop: secret\r\n"      // ...so this must NOT be forwarded either
        "Connection: x-two\r\n"  // a SECOND Connection field — its token is hop-by-hop too
        "X-Two: also-secret\r\n"
        "\r\n"
        "hello";
    REQUIRE(backend.setup(kResp, sizeof(kResp) - 1));

    RouteConfig cfg;
    auto id = cfg.add_upstream("b", 0x7F000001, backend.port);
    REQUIRE(id.has_value());
    REQUIRE(cfg.add_proxy("/api", 0, id.value()));

    Shard<EpollEventLoop> shard;
    i32 lfd = create_listen_socket(0).value_or(-1);
    REQUIRE(lfd >= 0);
    u16 port = get_port(lfd);
    REQUIRE(shard.init(0, lfd).has_value());
    shard.route_config = &cfg;
    REQUIRE(shard.spawn(-1).has_value());
    usleep(50000);

    i32 c = connect_to(port);
    REQUIRE(c >= 0);
    set_socket_timeouts(c, 2);

    u8 out[512];
    u32 n = h2_client_prologue(out);
    n += h2_client_get(out + n, sizeof(out) - n, 1, "/api", 4);
    REQUIRE(write_all_fd(c, out, n));

    u8 resp[4096];
    u32 total = 0;
    u8 body[64];
    u32 blen = 0;
    for (int attempt = 0; attempt < 10 && total < sizeof(resp); attempt++) {
        i32 got =
            recv_timeout(c, reinterpret_cast<char*>(resp + total), sizeof(resp) - total, 2000);
        if (got <= 0) break;
        total += static_cast<u32>(got);
        blen = h2_body_for_stream(resp, total, 1, body, sizeof(body));
        if (h2_status_for_stream(resp, total, 1) != 0 && blen == 5) break;
    }
    CHECK_EQ(h2_status_for_stream(resp, total, 1), 200u);  // re-framed upstream :status
    CHECK_EQ(blen, 5u);                                    // re-framed upstream body
    bool body_ok = blen == 5;
    const char* want = "hello";
    for (u32 i = 0; i < blen && body_ok; i++)
        if (body[i] != static_cast<u8>(want[i])) body_ok = false;
    CHECK(body_ok);
    // Header re-framing: a normal upstream header is forwarded (lowercased per
    // RFC 7540 §8.1.2); the hop-by-hop `te` and the field nominated by the
    // upstream `Connection` header (`x-hop`) are filtered out.
    CHECK(h2_response_has_header(resp, total, 1, "x-backend", "rut"));
    CHECK(!h2_response_has_header(resp, total, 1, "te", "gzip"));
    CHECK(!h2_response_has_header(resp, total, 1, "x-hop", "secret"));
    CHECK(!h2_response_has_header(resp, total, 1, "x-two", "also-secret"));  // 2nd Connection field

    close(c);
    shard.stop();
    shard.join();
    shard.shutdown();
    close(lfd);
}

TEST(shard, serves_http2_jit_forward_with_response_mutations) {
    ScriptedUpstreamServer backend;
    static const char kResp[] =
        "HTTP/1.1 200 OK\r\n"
        "Content-Length: 2\r\n"
        "X-Path: origin\r\n"
        "X-Remove: origin\r\n"
        "X-Multi: first\r\n"
        "\r\n"
        "ok";
    REQUIRE(backend.setup(kResp, sizeof(kResp) - 1));

    RouteConfig cfg;
    auto id = cfg.add_upstream("b", 0x7F000001, backend.port);
    REQUIRE(id.has_value());
    REQUIRE_EQ(id.value(), 0u);
    REQUIRE(cfg.add_jit_handler("/api", 'G', &forward_with_response_mutations_handler));

    Shard<EpollEventLoop> shard;
    i32 lfd = create_listen_socket(0).value_or(-1);
    REQUIRE(lfd >= 0);
    u16 port = get_port(lfd);
    REQUIRE(shard.init(0, lfd).has_value());
    shard.route_config = &cfg;
    REQUIRE(shard.spawn(-1).has_value());
    usleep(50000);

    i32 c = connect_to(port);
    REQUIRE(c >= 0);
    set_socket_timeouts(c, 2);
    u8 out[512];
    u32 n = h2_client_prologue(out);
    n += h2_client_get(out + n, sizeof(out) - n, 1, "/api", 4);
    REQUIRE(write_all_fd(c, out, n));

    u8 resp[4096];
    u32 total = 0;
    for (int attempt = 0; attempt < 10 && total < sizeof(resp); attempt++) {
        i32 got =
            recv_timeout(c, reinterpret_cast<char*>(resp + total), sizeof(resp) - total, 2000);
        if (got <= 0) break;
        total += static_cast<u32>(got);
        if (h2_status_for_stream(resp, total, 1) != 0) break;
    }
    CHECK_EQ(h2_status_for_stream(resp, total, 1), 200u);
    CHECK(h2_response_has_header(resp, total, 1, "x-path", "/api"));
    CHECK(h2_response_has_header(resp, total, 1, "x-folded", "final"));
    CHECK(!h2_response_has_header(resp, total, 1, "x-path", "origin"));
    CHECK(!h2_response_has_header(resp, total, 1, "x-remove", "origin"));
    CHECK(h2_response_has_header(resp, total, 1, "x-multi", "first"));
    CHECK(h2_response_has_header(resp, total, 1, "x-multi", "second"));

    close(c);
    shard.stop();
    shard.join();
    shard.shutdown();
    close(lfd);
}

