TEST(route, jit_handler_unknown_body_idx_falls_back) {
    using namespace rut;

    RouteConfig cfg{};
    // No response bodies registered. upstream_id=99 is out of range.
    REQUIRE(cfg.add_jit_handler("/hello", 'G', &return_200_with_body_99_handler));
    const RouteConfig* active = &cfg;

    RealLoop* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto lfd_result = create_listen_socket(0);
    REQUIRE(lfd_result.has_value());
    i32 lfd = lfd_result.value();
    u16 port = get_port(lfd);
    REQUIRE(loop->init(0, lfd).has_value());
    loop->config_ptr = &active;
    // Time-based hang-guard, not an iteration cap: under a loaded CI runner
    // spurious wakeups can burn a 100-iteration cap before the request even
    // lands (the #175 flake class), killing the loop mid-scenario.
    LoopThread lt = {loop, {}, 0, 15000};
    lt.start();

    i32 c = connect_to(port);
    REQUIRE(c >= 0);
    const char kReq[] = "GET /hello HTTP/1.1\r\nHost: x\r\n\r\n";
    send_all(c, kReq, sizeof(kReq) - 1);
    char buf[1024];
    i32 n = recv_timeout(c, buf, sizeof(buf), 10000);
    REQUIRE_GT(n, 0);
    // Assert the default reason-phrase body — not just that 200 is
    // anywhere in the response. For 200 the default body is "OK" (2
    // bytes), and format_static_response does NOT emit Content-Type,
    // so the response shape is distinct from the custom-body path.
    const Str response{buf, static_cast<u32>(n)};
    auto has = [&](const char* needle, u32 nlen) {
        return buf_contains(
            reinterpret_cast<const char*>(response.ptr), response.len, needle, nlen);
    };
    CHECK(has("200 OK", 6));
    CHECK(has("Content-Length: 2\r\n", 19));
    // Default formatter must NOT emit Content-Type — that would mean
    // the custom-body path ran despite the out-of-range index.
    CHECK(!has("Content-Type:", 13));
    // Body bytes at end of response: "...\r\n\r\nOK".
    CHECK(has("\r\n\r\nOK", 6));

    close(c);
    lt.stop();
    loop->shutdown();
    close(lfd);
    destroy_real_loop(loop);
}

// Handler returns ReturnStatus with a valid headers_idx but an
// out-of-range body_idx. The dispatch path must still render the
// default reason-phrase body so the response isn't silently empty —
// matches the no-headers fallback behavior of format_static_response.
static u64 return_200_body_99_headers_1_handler(void* /*conn*/,
                                                rut::jit::HandlerCtx* /*ctx*/,
                                                const u8* /*req*/,
                                                u32 /*len*/,
                                                void* /*arena*/) {
    rut::jit::HandlerResult r{rut::jit::HandlerAction::ReturnStatus,
                              200,
                              /*upstream_id=*/99,  // body_idx: out of range
                              /*next_state=*/1,    // headers_idx: valid
                              rut::jit::YieldKind::HttpGet};
    return r.pack();
}

// HTTP/2: a JIT handler returning custom response headers, served over h2c.
TEST(shard, serves_http2_jit_handler_with_headers) {
    using namespace rut;

    RouteConfig cfg{};
    const char* keys[] = {"X-Service"};  // mixed case → must be lowercased for h2
    u32 key_lens[] = {9};
    const char* vals[] = {"auth"};
    u32 val_lens[] = {4};
    REQUIRE_EQ(cfg.add_response_header_set(keys, key_lens, vals, val_lens, 1), 1u);
    REQUIRE(cfg.add_jit_handler("/hello", 'G', &return_200_body_99_headers_1_handler));

    Shard<EpollEventLoop> shard;
    i32 lfd = create_listen_socket(0).value_or(-1);
    REQUIRE(lfd >= 0);
    u16 port = get_port(lfd);
    REQUIRE(shard.init(0, lfd).has_value());
    shard.route_config = &cfg;
    REQUIRE(shard.spawn(-1).has_value());
    usleep(50000);

    i32 c = connect_to(port);
    REQUIRE(c >= 0);
    set_socket_timeouts(c, 2);

    u8 out[512];
    u32 n = h2_client_prologue(out);
    n += h2_client_get(out + n, sizeof(out) - n, 1, "/hello", 6);
    REQUIRE(write_all_fd(c, out, n));

    u8 resp[4096];
    u32 total = 0;
    for (int attempt = 0; attempt < 6 && total < sizeof(resp); attempt++) {
        i32 got =
            recv_timeout(c, reinterpret_cast<char*>(resp + total), sizeof(resp) - total, 2000);
        if (got <= 0) break;
        total += static_cast<u32>(got);
        if (h2_status_for_stream(resp, total, 1) != 0) break;
    }
    CHECK_EQ(h2_status_for_stream(resp, total, 1), 200u);
    // Header name lowercased to "x-service" for HTTP/2 compliance.
    CHECK(h2_response_has_header(resp, total, 1, "x-service", "auth"));

    close(c);
    shard.stop();
    shard.join();
    shard.shutdown();
    close(lfd);
}

// A JIT handler that inspects the request body (passed as the synthesized
// HTTP/1 bytes) and returns 200 iff it equals "ping".
static u64 h2_echo_body_handler(
    void* /*conn*/, rut::jit::HandlerCtx* /*ctx*/, const u8* req, u32 len, void* /*arena*/) {
    u32 body_off = len;
    for (u32 i = 0; i + 3 < len; i++) {
        if (req[i] == '\r' && req[i + 1] == '\n' && req[i + 2] == '\r' && req[i + 3] == '\n') {
            body_off = i + 4;
            break;
        }
    }
    const u32 blen = len - body_off;
    const bool ok = blen == 4 && req[body_off] == 'p' && req[body_off + 1] == 'i' &&
                    req[body_off + 2] == 'n' && req[body_off + 3] == 'g';
    rut::jit::HandlerResult r{rut::jit::HandlerAction::ReturnStatus,
                              static_cast<u16>(ok ? 200 : 400),
                              /*upstream_id=*/0,
                              /*next_state=*/0,
                              rut::jit::YieldKind::HttpGet};
    return r.pack();
}

// A body-reading handler for an h2 request that omitted content-length. The
// bridge synthesizes a content-length so the HTTP/1-shaped parse exposes the
// DATA bytes; the handler verifies both the injected header and the body.
static u64 h2_no_cl_body_handler(
    void* /*conn*/, rut::jit::HandlerCtx* /*ctx*/, const u8* req, u32 len, void* /*arena*/) {
    u32 body_off = len;
    bool saw_content_length = false;
    for (u32 i = 0; i + 3 < len; i++) {
        if (i + 15 <= len && req[i] == 'c' && req[i + 1] == 'o' && req[i + 2] == 'n' &&
            req[i + 3] == 't' && req[i + 4] == 'e' && req[i + 5] == 'n' && req[i + 6] == 't' &&
            req[i + 7] == '-' && req[i + 8] == 'l' && req[i + 9] == 'e' && req[i + 10] == 'n' &&
            req[i + 11] == 'g' && req[i + 12] == 't' && req[i + 13] == 'h' && req[i + 14] == ':') {
            saw_content_length = true;
        }
        if (req[i] == '\r' && req[i + 1] == '\n' && req[i + 2] == '\r' && req[i + 3] == '\n') {
            body_off = i + 4;
            break;
        }
    }
    const u32 blen = len - body_off;
    const bool ok = saw_content_length && blen == 4 && req[body_off] == 'p' &&
                    req[body_off + 1] == 'i' && req[body_off + 2] == 'n' &&
                    req[body_off + 3] == 'g';
    rut::jit::HandlerResult r{rut::jit::HandlerAction::ReturnStatus,
                              static_cast<u16>(ok ? 200 : 400),
                              /*upstream_id=*/0,
                              /*next_state=*/0,
                              rut::jit::YieldKind::HttpGet};
    return r.pack();
}

static u64 h2_ignore_body_handler(void* /*conn*/,
                                  rut::jit::HandlerCtx* /*ctx*/,
                                  const u8* /*req*/,
                                  u32 /*len*/,
                                  void* /*arena*/) {
    rut::jit::HandlerResult r{rut::jit::HandlerAction::ReturnStatus,
                              200,
                              /*upstream_id=*/0,
                              /*next_state=*/0,
                              rut::jit::YieldKind::HttpGet};
    return r.pack();
}

static u64 h2_reject_body_handler(void* /*conn*/,
                                  rut::jit::HandlerCtx* /*ctx*/,
                                  const u8* /*req*/,
                                  u32 /*len*/,
                                  void* /*arena*/) {
    rut::jit::HandlerResult r{rut::jit::HandlerAction::ReturnStatus,
                              401,
                              /*upstream_id=*/0,
                              /*next_state=*/0,
                              rut::jit::YieldKind::HttpGet};
    return r.pack();
}

// HTTP/2 request body: HEADERS (no END_STREAM) + a DATA frame; the handler
// (needs_req_body) runs only after the body arrives and sees it.
TEST(shard, serves_http2_request_body) {
    using namespace rut;

    RouteConfig cfg{};
    REQUIRE(cfg.add_jit_handler("/upload", 'G', &h2_echo_body_handler, /*needs_req_body=*/true));

    Shard<EpollEventLoop> shard;
    i32 lfd = create_listen_socket(0).value_or(-1);
    REQUIRE(lfd >= 0);
    u16 port = get_port(lfd);
    REQUIRE(shard.init(0, lfd).has_value());
    shard.route_config = &cfg;
    REQUIRE(shard.spawn(-1).has_value());
    usleep(50000);

    i32 c = connect_to(port);
    REQUIRE(c >= 0);
    set_socket_timeouts(c, 2);

    u8 out[512];
    u32 n = h2_client_prologue(out);
    const hpack::Header hs[] = {
        {{":method", 7}, {"GET", 3}},
        {{":scheme", 7}, {"http", 4}},
        {{":path", 5}, {"/upload", 7}},
        {{":authority", 10}, {"localhost", 9}},
        {{"content-length", 14}, {"4", 1}},
    };
    n += http2_write_headers(out + n, sizeof(out) - n, 1, hs, 5, /*end_stream=*/false);
    n += http2_write_data(out + n, 1, reinterpret_cast<const u8*>("ping"), 4, /*end_stream=*/true);
    REQUIRE(write_all_fd(c, out, n));

    u8 resp[4096];
    u32 total = 0;
    for (int attempt = 0; attempt < 6 && total < sizeof(resp); attempt++) {
        i32 got =
            recv_timeout(c, reinterpret_cast<char*>(resp + total), sizeof(resp) - total, 2000);
        if (got <= 0) break;
        total += static_cast<u32>(got);
        if (h2_status_for_stream(resp, total, 1) != 0) break;
    }
    CHECK_EQ(h2_status_for_stream(resp, total, 1), 200u);  // handler saw "ping"

    close(c);
    shard.stop();
    shard.join();
    shard.shutdown();
    close(lfd);
}

// A body-reading stream deferred for DATA and a coalesced proxy stream both want
// pending_synth. The proxy stream must be refused (503) while the body stream is
// pending — not allowed to overwrite the deferred request's bytes — and the body
// stream must still complete correctly. Regression for the pending_synth aliasing
// fix.
TEST(shard, serves_http2_body_defer_blocks_concurrent_async) {
    using namespace rut;

    RouteConfig cfg{};
    REQUIRE(cfg.add_jit_handler("/upload", 'G', &h2_echo_body_handler, /*needs_req_body=*/true));
    auto id = cfg.add_upstream("dead", 0x7F000001, 9);  // discard port; never connected
    REQUIRE(id.has_value());
    REQUIRE(cfg.add_proxy("/api", 0, id.value()));

    Shard<EpollEventLoop> shard;
    i32 lfd = create_listen_socket(0).value_or(-1);
    REQUIRE(lfd >= 0);
    u16 port = get_port(lfd);
    REQUIRE(shard.init(0, lfd).has_value());
    shard.route_config = &cfg;
    REQUIRE(shard.spawn(-1).has_value());
    usleep(50000);

    i32 c = connect_to(port);
    REQUIRE(c >= 0);
    set_socket_timeouts(c, 2);

    // Coalesced: stream 1 POST body (defers for DATA), stream 3 proxy GET (would
    // suspend → must be refused 503 while stream 1 is pending), then stream 1's
    // DATA terminator.
    u8 out[512];
    u32 n = h2_client_prologue(out);
    const hpack::Header up[] = {
        {{":method", 7}, {"GET", 3}},
        {{":scheme", 7}, {"http", 4}},
        {{":path", 5}, {"/upload", 7}},
        {{":authority", 10}, {"localhost", 9}},
        {{"content-length", 14}, {"4", 1}},
    };
    n += http2_write_headers(out + n, sizeof(out) - n, 1, up, 5, /*end_stream=*/false);
    n += h2_client_get(out + n, sizeof(out) - n, 3, "/api", 4);
    n += http2_write_data(out + n, 1, reinterpret_cast<const u8*>("ping"), 4, /*end_stream=*/true);
    REQUIRE(write_all_fd(c, out, n));

    u8 resp[4096];
    u32 total = 0;
    for (int attempt = 0; attempt < 8 && total < sizeof(resp); attempt++) {
        i32 got =
            recv_timeout(c, reinterpret_cast<char*>(resp + total), sizeof(resp) - total, 2000);
        if (got <= 0) break;
        total += static_cast<u32>(got);
        if (h2_status_for_stream(resp, total, 1) != 0 && h2_status_for_stream(resp, total, 3) != 0)
            break;
    }
    CHECK_EQ(h2_status_for_stream(resp, total, 1),
             200u);  // body handler saw "ping" (not corrupted)
    CHECK_EQ(h2_status_for_stream(resp, total, 3), 503u);  // proxy refused while body pending

    close(c);
    shard.stop();
    shard.join();
    shard.shutdown();
    close(lfd);
}

