        i32 c = connect_to(port);
        REQUIRE(c >= 0);
        REQUIRE(send_all(c, req, req_len));
        char buf[1024];
        i32 n = recv_timeout(c, buf, sizeof(buf), 2000);
        CHECK_GT(n, 0);
