static bool read_public_close_response(
    i32 fd, u32 expected_body_len, char* out, u32 capacity, u32& length) {
    length = 0;
    u32 header_end = 0;
    for (u32 attempt = 0; attempt < 32 && length < capacity; attempt++) {
        const i32 got = recv_timeout(fd, out + length, static_cast<i32>(capacity - length), 3000);
        if (got <= 0) return false;
        length += static_cast<u32>(got);
        if (header_end == 0) {
            for (u32 i = 0; i + 3 < length; i++) {
                if (out[i] == '\r' && out[i + 1] == '\n' && out[i + 2] == '\r' &&
                    out[i + 3] == '\n') {
                    header_end = i + 4;
                    break;
                }
            }
        }
        if (header_end != 0) {
            const u32 expected = header_end + expected_body_len;
            if (length > expected) return false;
            if (length == expected) break;
        }
    }
    if (header_end == 0 || length != header_end + expected_body_len) return false;
    char eof_buf[64];
    return recv_timeout(fd, eof_buf, sizeof(eof_buf), 3000) == 0;
}

static bool read_public_head_response(
    i32 fd, bool expect_eof, char* out, u32 capacity, u32& length, i32 timeout_ms = 3000) {
    length = 0;
    u32 header_end = 0;
    for (u32 attempt = 0; attempt < 32 && length < capacity; attempt++) {
        const i32 got = recv_timeout(fd, out + length, capacity - length, timeout_ms);
        if (got <= 0) return false;
        length += static_cast<u32>(got);
        for (u32 i = 0; i + 3 < length; i++) {
            if (out[i] == '\r' && out[i + 1] == '\n' && out[i + 2] == '\r' && out[i + 3] == '\n') {
                header_end = i + 4;
                break;
            }
        }
        if (header_end != 0) break;
    }
    if (header_end == 0 || length != header_end) return false;
    char extra[64];
    const i32 tail = recv_timeout(fd, extra, sizeof(extra), expect_eof ? 3000 : 100);
    return expect_eof ? tail == 0 : tail == -EAGAIN;
}

static bool normalize_public_date(char* data, u32 length) {
    u32 count = 0;
    for (u32 i = 0; i < length;) {
        if (length - i < 6) break;
        if (memcmp(data + i, "Date: ", 6) != 0) {
            i++;
            continue;
        }
        count++;
        if (i < 2 || length - i < 37 || data[i - 2] != '\r' || data[i + 35] != '\r' ||
            data[i + 36] != '\n')
            return false;
        for (u32 j = 0; j < 29; j++) data[i + 6 + j] = 'X';
        i += 6;
    }
    return count == 1;
}
