#if RUT_ENABLE_JIT_TESTS
TEST(shard, serves_http2_jit_target_transform_initial_fails_closed) {
    H2TargetTransformJit compiled;
    REQUIRE(compiled.init(/*with_timer=*/false));

    RecordingUpstream backend;
    REQUIRE(backend.setup());
    RouteConfig cfg{};
    REQUIRE_EQ(cfg.add_target_transform({{"/api/", 5}, {"/v1/", 4}}), 1u);
    auto upstream = cfg.add_upstream("backend", 0x7F000001, backend.port);
    REQUIRE(upstream.has_value());
    REQUIRE_EQ(upstream.value(), 0u);
    REQUIRE(cfg.add_jit_handler("/api", 'G', compiled.handler_fn));

    Shard<EpollEventLoop> shard;
    i32 listen_fd = create_listen_socket(0).value_or(-1);
    REQUIRE(listen_fd >= 0);
    H2TargetTransformShardGuard<EpollEventLoop> guard{shard, listen_fd};
    const u16 port = get_port(listen_fd);
    REQUIRE(shard.init(0, listen_fd).has_value());
    shard.route_config = &cfg;
    REQUIRE(shard.spawn(-1).has_value());
    guard.spawned = true;
    usleep(50000);

    guard.client_fd = connect_to(port);
    REQUIRE(guard.client_fd >= 0);
    set_socket_timeouts(guard.client_fd, 2);
    u8 request[512];
    u32 request_len = h2_client_prologue(request);
    request_len +=
        h2_client_get(request + request_len, sizeof(request) - request_len, 1, "/api", 4);
    REQUIRE(write_all_fd(guard.client_fd, request, request_len));

    u8 response[4096];
    u32 response_len = 0;
    for (int attempt = 0; attempt < 10 && response_len < sizeof(response); attempt++) {
        const i32 got = recv_timeout(guard.client_fd,
                                     reinterpret_cast<char*>(response + response_len),
                                     sizeof(response) - response_len,
                                     2000);
        if (got <= 0) break;
        response_len += static_cast<u32>(got);
        if (h2_status_for_stream(response, response_len, 1) != 0) break;
    }
    CHECK_EQ(h2_status_for_stream(response, response_len, 1), 400u);
    usleep(100000);
    CHECK_EQ(backend.accepted_count.load(std::memory_order_acquire), 0u);
    CHECK_EQ(backend.request_count.load(std::memory_order_acquire), 0u);
}

TEST(shard, serves_http2_jit_target_transform_after_timer_resume_fails_closed) {
    H2TargetTransformJit compiled;
    REQUIRE(compiled.init(/*with_timer=*/true));

    // Pin the first invocation's contract independently of socket timing: the
    // compiled entry block yields and must not record the effect. The real
    // request below still drives both initial dispatch and timer resume.
    Connection probe;
    probe.reset();
    jit::HandlerCtx probe_ctx{};
    static constexpr char kProbeRequest[] = "GET /api HTTP/1.1\r\nHost: localhost\r\n\r\n";
    const auto first =
        jit::HandlerResult::unpack(compiled.handler_fn(&probe,
                                                       &probe_ctx,
                                                       reinterpret_cast<const u8*>(kProbeRequest),
                                                       sizeof(kProbeRequest) - 1,
                                                       nullptr));
    CHECK_EQ(first.action, jit::HandlerAction::Yield);
    CHECK_EQ(first.yield_kind, jit::YieldKind::Timer);
    CHECK_FALSE(probe.target_transform_recorded);

    RecordingUpstream backend;
    REQUIRE(backend.setup());
    RouteConfig cfg{};
    REQUIRE_EQ(cfg.add_target_transform({{"/api/", 5}, {"/v1/", 4}}), 1u);
    auto upstream = cfg.add_upstream("backend", 0x7F000001, backend.port);
    REQUIRE(upstream.has_value());
    REQUIRE_EQ(upstream.value(), 0u);
    REQUIRE(cfg.add_jit_handler("/api", 'G', compiled.handler_fn));
    REQUIRE(cfg.add_jit_handler("/plain", 'G', &h2_target_transform_plain_200_handler));

    Shard<EpollEventLoop> shard;
    i32 listen_fd = create_listen_socket(0).value_or(-1);
    REQUIRE(listen_fd >= 0);
    H2TargetTransformShardGuard<EpollEventLoop> guard{shard, listen_fd};
    const u16 port = get_port(listen_fd);
    REQUIRE(shard.init(0, listen_fd).has_value());
    shard.route_config = &cfg;
    REQUIRE(shard.spawn(-1).has_value());
    guard.spawned = true;
    usleep(50000);
    const u64 epoch_before = shard.epoch.epoch.load(std::memory_order_acquire);

    guard.client_fd = connect_to(port);
    REQUIRE(guard.client_fd >= 0);
    set_socket_timeouts(guard.client_fd, 2);
    u8 request[512];
    u32 request_len = h2_client_prologue(request);
    request_len +=
        h2_client_get(request + request_len, sizeof(request) - request_len, 1, "/api", 4);
    REQUIRE(write_all_fd(guard.client_fd, request, request_len));

    u8 response[4096];
    u32 response_len = 0;
    for (int attempt = 0; attempt < 12 && response_len < sizeof(response); attempt++) {
        const i32 got = recv_timeout(guard.client_fd,
                                     reinterpret_cast<char*>(response + response_len),
                                     sizeof(response) - response_len,
                                     2000);
        if (got <= 0) break;
        response_len += static_cast<u32>(got);
        if (h2_status_for_stream(response, response_len, 1) != 0) break;
    }
    CHECK_EQ(h2_status_for_stream(response, response_len, 1), 400u);
    const u64 epoch_after = shard.epoch.epoch.load(std::memory_order_acquire);
    // Extra H2 receive batches add balanced enter/leave pairs. The parked
    // target request contributes one async enter when its timer is armed and
    // one leave in h2_resume_jit_handler's local-400 branch. Omitting that
    // resume leave leaves an odd delta, so require a monotonic even delta.
    CHECK_GE(epoch_after, epoch_before);
    const u64 epoch_delta = epoch_after >= epoch_before ? epoch_after - epoch_before : 0;
    CHECK_GE(epoch_delta, 2u);
    CHECK_EQ(epoch_delta % 2u, 0u);
    usleep(100000);
    CHECK_EQ(backend.accepted_count.load(std::memory_order_acquire), 0u);
    CHECK_EQ(backend.request_count.load(std::memory_order_acquire), 0u);

    // The resumed target-transform branch must clear the H2 async slot and
    // config epoch before sending its local 400. A second stream on the same
    // connection is the externally visible proof of that cleanup.
    u8 second_request[256];
    const u32 second_len = h2_client_get(second_request, sizeof(second_request), 3, "/plain", 6);
    REQUIRE(write_all_fd(guard.client_fd, second_request, second_len));
    u8 second_response[4096];
    u32 second_response_len = 0;
    for (int attempt = 0; attempt < 10 && second_response_len < sizeof(second_response);
         attempt++) {
        const i32 got = recv_timeout(guard.client_fd,
                                     reinterpret_cast<char*>(second_response + second_response_len),
                                     sizeof(second_response) - second_response_len,
                                     2000);
        if (got <= 0) break;
        second_response_len += static_cast<u32>(got);
        if (h2_status_for_stream(second_response, second_response_len, 3) != 0) break;
    }
    CHECK_EQ(h2_status_for_stream(second_response, second_response_len, 3), 200u);
}
TEST(route, target_transform_jit_rebuilds_request_policy_h1_wire) {
    H2TargetTransformJit compiled;
    REQUIRE(compiled.init(/*with_timer=*/false, /*with_request_policy=*/true));

    RecordingUpstream backend;
    REQUIRE(backend.setup());
    RouteConfig cfg{};
    char strip[] = "/api/";
    char replace[] = "/";
    REQUIRE_EQ(cfg.add_target_transform({{strip, 5}, {replace, 1}}), 1u);
    auto upstream = cfg.add_upstream("backend", 0x7F000001, backend.port);
    REQUIRE(upstream.has_value());
    REQUIRE_EQ(upstream.value(), 0u);
    REQUIRE(cfg.add_jit_handler("/api", 'G', compiled.handler_fn));
    const RouteConfig* active = &cfg;

    ScopedProxyLoop proxy;
    REQUIRE(proxy.setup(&active, 1000));
    struct ClientFdGuard {
        i32 fd;
        ~ClientFdGuard() {
            if (fd >= 0) close(fd);
        }
    };

    struct Vector {
        const char* target;
        const char* expected_target;
    } vectors[] = {{"/api/", "/"}, {"/api/x", "/x"}, {"/api/x?y=1", "/x?y=1"}};
    for (u32 i = 0; i < 3; i++) {
        char request[512];
        const int request_len = snprintf(request,
                                         sizeof(request),
                                         "GET %s HTTP/1.1\r\n"
                                         "Host: client.example\r\n"
                                         "X-Test: one\r\n\r\n",
                                         vectors[i].target);
        REQUIRE_GT(request_len, 0);
        REQUIRE_LT(request_len, static_cast<int>(sizeof(request)));
        ClientFdGuard client{connect_to(proxy.port)};
        REQUIRE_GE(client.fd, 0);
        set_socket_timeouts(client.fd, 2);
        char response[1024];
        REQUIRE(send_all(client.fd, request, static_cast<u32>(request_len)));
        const i32 response_len = recv_timeout(client.fd, response, sizeof(response), 2000);
        CHECK_GT(response_len, 0);
        if (response_len > 0)
            CHECK(buf_contains(response, static_cast<u32>(response_len), "HTTP/1.1 200", 12));

        const u32 expected_count = i + 1;
        for (u32 waited = 0;
             waited < 400 && backend.request_count.load(std::memory_order_acquire) < expected_count;
             waited++)
            usleep(5000);
        REQUIRE_EQ(backend.accepted_count.load(std::memory_order_acquire), expected_count);
        REQUIRE_EQ(backend.request_count.load(std::memory_order_acquire), expected_count);

        char expected[512];
        const int expected_len = snprintf(expected,
                                          sizeof(expected),
                                          "GET %s HTTP/1.1\r\n"
                                          "Host: 127.0.0.1:%u\r\n"
                                          "X-Test: one\r\n\r\n",
                                          vectors[i].expected_target,
                                          backend.port);
        REQUIRE_GT(expected_len, 0);
        REQUIRE_LT(expected_len, static_cast<int>(sizeof(expected)));
        CHECK_EQ(backend.request_history_len[i], static_cast<u32>(expected_len));
        CHECK_EQ(memcmp(backend.request_history[i], expected, static_cast<size_t>(expected_len)),
                 0);
    }

    const u32 accepted_before = backend.accepted_count.load(std::memory_order_acquire);
    const u32 requests_before = backend.request_count.load(std::memory_order_acquire);
    static constexpr char kInvalid[] =
        "GET /api/%7Euser HTTP/1.1\r\nHost: client.example\r\nX-Test: one\r\n\r\n";
    ClientFdGuard client{connect_to(proxy.port)};
    REQUIRE_GE(client.fd, 0);
    set_socket_timeouts(client.fd, 2);
    REQUIRE(send_all(client.fd, kInvalid, sizeof(kInvalid) - 1));
    char response[1024];
    const i32 response_len = recv_timeout(client.fd, response, sizeof(response), 2000);
    CHECK_GT(response_len, 0);
    if (response_len > 0)
        CHECK(buf_contains(response, static_cast<u32>(response_len), "HTTP/1.1 400", 12));
    usleep(100000);
    CHECK_EQ(backend.accepted_count.load(std::memory_order_acquire), accepted_before);
    CHECK_EQ(backend.request_count.load(std::memory_order_acquire), requests_before);
}

TEST(route, target_transform_public_source_reaches_h1_backend_wire) {
    struct JitResources {
        FrontendRirModule rir{};
        jit::JitEngine engine{};
        ~JitResources() {
            engine.shutdown();
            rir.destroy();
        }
    } resources;
    RecordingUpstream backend;
    REQUIRE(backend.setup());

    char source[1600];
    const int source_len =
        snprintf(source,
                 sizeof(source),
                 "upstream backend at \"127.0.0.1:%u\"\n"
                 "route GET \"/api\" { return forward(backend, "
                 "target_transform: { strip_prefix: \"/api/\", replace_prefix: \"/\" }, "
                 "request_policy: { version: \"HTTP/1.1\", host: \"upstream\", "
                 "connection: \"omit\", strip_headers: [\"Connection\", \"Keep-Alive\", "
                 "\"TE\", \"Expect\", \"Upgrade\"] }) }\n",
                 backend.port);
    REQUIRE_GT(source_len, 0);
    REQUIRE_LT(source_len, static_cast<int>(sizeof(source)));

    auto lexed = lex(Str{source, static_cast<u32>(source_len)});
    REQUIRE(lexed);
    auto ast = parse_file(lexed.value());
    REQUIRE(ast);
    std::unique_ptr<AstFile> ast_owned(ast.value());
    auto hir = analyze_file(*ast_owned);
    REQUIRE(hir);
    std::unique_ptr<HirModule> hir_owned(hir.value());
    auto mir = build_mir(*hir_owned);
    REQUIRE(mir);
    std::unique_ptr<MirModule> mir_owned(mir.value());
    REQUIRE(lower_to_rir(*mir_owned, resources.rir));
    REQUIRE_EQ(resources.rir.module.target_transform_count, 1u);
    CHECK(resources.rir.module.target_transforms[0].strip_prefix.eq({"/api/", 5}));
    CHECK(resources.rir.module.target_transforms[0].replace_prefix.eq({"/", 1}));

    const auto& block = resources.rir.module.functions[0].blocks[0];
    REQUIRE_EQ(block.inst_count, 4u);
    CHECK_EQ(block.insts[0].op, rir::Opcode::ConstI32);
    CHECK_EQ(block.insts[0].imm.i32_val, 0);
    CHECK_EQ(block.insts[1].op, rir::Opcode::ConstI32);
    CHECK_EQ(block.insts[1].imm.i32_val, 1);
    CHECK_EQ(block.insts[2].op, rir::Opcode::ReqSetTargetTransform);
    CHECK_EQ(block.insts[2].imm.i32_val, 1);
    CHECK_EQ(block.insts[3].op, rir::Opcode::RetForward);
    CHECK_EQ(block.insts[3].operand_count, 2u);
    CHECK_EQ(block.insts[3].operands[0].id, block.insts[0].result.id);
    CHECK_EQ(block.insts[3].operands[1].id, block.insts[1].result.id);

    auto cg = jit::codegen(resources.rir.module);
    REQUIRE(cg.ok);
    REQUIRE(resources.engine.init());
    REQUIRE(resources.engine.compile(cg.mod, cg.ctx));
    RouteConfig cfg{};
    REQUIRE(populate_route_config(cfg, resources.rir.module));
    REQUIRE_EQ(cfg.target_transform_count, 1u);
    CHECK(cfg.target_transforms[0].strip_prefix.eq({"/api/", 5}));
    REQUIRE(register_jit_routes(cfg, resources.rir.module, resources.engine));
    const RouteConfig* active = &cfg;

    struct ClientFdGuard {
        i32 fd;
        ~ClientFdGuard() {
            if (fd >= 0) close(fd);
        }
    };
    ScopedProxyLoop proxy;
    REQUIRE(proxy.setup(&active, 1200));

    struct Vector {
        const char* target;
        const char* expected_target;
    } vectors[] = {{"/api/", "/"}, {"/api/x", "/x"}, {"/api/x?y=1", "/x?y=1"}};
    for (u32 i = 0; i < 3; i++) {
        char request[256];
        const int request_len = snprintf(request,
                                         sizeof(request),
                                         "GET %s HTTP/1.1\r\nHost: client.example\r\n"
                                         "Connection: keep-alive\r\nX-Test: one\r\n\r\n",
                                         vectors[i].target);
        REQUIRE_GT(request_len, 0);
        REQUIRE_LT(request_len, static_cast<int>(sizeof(request)));
        ClientFdGuard client{connect_to(proxy.port)};
        REQUIRE_GE(client.fd, 0);
        set_socket_timeouts(client.fd, 2);
        REQUIRE(send_all(client.fd, request, static_cast<u32>(request_len)));
        char response[1024];
        const i32 response_len = recv_timeout(client.fd, response, sizeof(response), 2000);
        REQUIRE_GT(response_len, 0);
        REQUIRE(buf_contains(response, static_cast<u32>(response_len), "HTTP/1.1 200", 12));

        const u32 expected_count = i + 1;
        for (u32 waited = 0;
             waited < 400 && backend.request_count.load(std::memory_order_acquire) < expected_count;
             waited++)
            usleep(5000);
        REQUIRE_EQ(backend.accepted_count.load(std::memory_order_acquire), expected_count);
        REQUIRE_EQ(backend.request_count.load(std::memory_order_acquire), expected_count);

        char expected[256];
        const int expected_len = snprintf(expected,
                                          sizeof(expected),
                                          "GET %s HTTP/1.1\r\nHost: 127.0.0.1:%u\r\n"
                                          "X-Test: one\r\n\r\n",
                                          vectors[i].expected_target,
                                          backend.port);
        REQUIRE_GT(expected_len, 0);
        REQUIRE_LT(expected_len, static_cast<int>(sizeof(expected)));
        CHECK_EQ(backend.request_history_len[i], static_cast<u32>(expected_len));
        CHECK_EQ(memcmp(backend.request_history[i], expected, static_cast<size_t>(expected_len)),
                 0);
    }

    const u32 accepted_before = backend.accepted_count.load(std::memory_order_acquire);
    const u32 requests_before = backend.request_count.load(std::memory_order_acquire);
    static constexpr char kInvalid[] =
        "GET /api/%7Euser HTTP/1.1\r\nHost: client.example\r\nX-Test: one\r\n\r\n";
    ClientFdGuard invalid_client{connect_to(proxy.port)};
    REQUIRE_GE(invalid_client.fd, 0);
    set_socket_timeouts(invalid_client.fd, 2);
    REQUIRE(send_all(invalid_client.fd, kInvalid, sizeof(kInvalid) - 1));
    char invalid_response[1024];
    const i32 invalid_len =
        recv_timeout(invalid_client.fd, invalid_response, sizeof(invalid_response), 2000);
    REQUIRE_GT(invalid_len, 0);
    REQUIRE(buf_contains(invalid_response,
                         static_cast<u32>(invalid_len),
                         "HTTP/1.1 400",
                         sizeof("HTTP/1.1 400") - 1));
    bool invalid_backend_clean = true;
    for (u32 waited = 0; waited < 100; waited++) {
        if (backend.accepted_count.load(std::memory_order_acquire) != accepted_before ||
            backend.request_count.load(std::memory_order_acquire) != requests_before)
            invalid_backend_clean = false;
        usleep(5000);
    }
    CHECK(invalid_backend_clean);
    CHECK_EQ(backend.accepted_count.load(std::memory_order_acquire), accepted_before);
    CHECK_EQ(backend.request_count.load(std::memory_order_acquire), requests_before);
}
#endif

static bool run_strict_response_rejection_case(const char* response) {
    RecordingUpstream backend;
    backend.response = response;
    backend.response_len = static_cast<u32>(strlen(response));
    if (!backend.setup()) return false;
    RouteConfig cfg{};
    auto id = cfg.add_upstream("backend", 0x7F000001, backend.port);
    if (!id.has_value() || cfg.add_response_policy(test_response_policy_spec()) != 1u ||
        !cfg.add_jit_handler("/api", 'G', &forward_request_and_response_policy_handler))
        return false;
    const RouteConfig* active = &cfg;
    ScopedProxyLoop proxy;
    if (!proxy.setup(&active, 1000)) return false;
    i32 client = connect_to(proxy.port);
    if (client < 0) return false;
    set_socket_timeouts(client, 2);
    static constexpr char kRequest[] = "GET /api HTTP/1.1\r\nHost: client.example\r\n\r\n";
    if (!send_all(client, kRequest, sizeof(kRequest) - 1)) {
        close(client);
        return false;
    }
    char out[512];
    const i32 n = recv_timeout(client, out, sizeof(out), 2000);
    close(client);
    return n > 0 && buf_contains(out, static_cast<u32>(n), "502", 3) &&
           backend.accepted_count.load(std::memory_order_acquire) == 1u;
}

TEST(route, response_policy_rejects_strict_invalid_final_vectors) {
    static constexpr const char* kCases[] = {
        "HTTP/1.1 100 Continue\r\nContent-Length: 0\r\n\r\n",
        "HTTP/1.1 103 Early Hints\r\nContent-Length: 0\r\n\r\n",
        "HTTP/1.1 101 Switching Protocols\r\nContent-Length: 0\r\n\r\n",
        "HTTP/1.0 200 OK\r\nContent-Length: 0\r\n\r\n",
        "HTTP/1.1 200\r\nContent-Length: 0\r\n\r\n",
        "HTTP/1.1 200 OK\r\n\r\n",
        "HTTP/1.1 200 OK\r\nContent-Length: 0\r\nContent-Length: 0\r\n\r\n",
        "HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n",
        ("HTTP/1.1 200 OK\r\nConnection: Foo\r\ncOnNeCtIoN: Bar\r\n"
         "Content-Length: 0\r\n\r\n"),
        "HTTP/1.1 200 OK\r\nProxy-Connection: keep-alive\r\nContent-Length: 0\r\n\r\n",
        "HTTP/1.1 200 OK\r\nX-Accel-Redirect: /private\r\nContent-Length: 0\r\n\r\n",
        "HTTP/1.1 200 OK\r\nLocation: /private\r\nContent-Length: 0\r\n\r\n",
        "HTTP/1.1 200 OK\r\nBad Header: x\r\nContent-Length: 0\r\n\r\n",
        "HTTP/1.1 200 OK\r\nContent-Length: 1\r\n\r\nxx",
    };
    for (const char* response : kCases) CHECK(run_strict_response_rejection_case(response));

    char truncated[4096]{};
    u32 truncated_len = 0;
    const int prefix_len = snprintf(truncated, sizeof(truncated), "HTTP/1.1 200 OK\r\n");
    REQUIRE_GT(prefix_len, 0);
    truncated_len = static_cast<u32>(prefix_len);
    for (u32 i = 0; i < 70; i++) {
        const int written = snprintf(
            truncated + truncated_len, sizeof(truncated) - truncated_len, "X-Fill-%u: v\r\n", i);
        REQUIRE_GT(written, 0);
        truncated_len += static_cast<u32>(written);
        REQUIRE_LT(truncated_len, static_cast<u32>(sizeof(truncated)));
    }
    const int suffix_len = snprintf(
        truncated + truncated_len, sizeof(truncated) - truncated_len, "Content-Length: 0\r\n\r\n");
    REQUIRE_GT(suffix_len, 0);
    truncated_len += static_cast<u32>(suffix_len);
    REQUIRE_LT(truncated_len, static_cast<u32>(sizeof(truncated)));
    CHECK(run_strict_response_rejection_case(truncated));
}

TEST(route, forward_request_policy_rebuilds_nginx_h11_headers) {
    using namespace rut;
    struct JitResources {
        FrontendRirModule rir{};
        jit::JitEngine engine{};
        ~JitResources() {
            engine.shutdown();
            rir.destroy();
        }
    } resources;
    RecordingUpstream upstream;
    REQUIRE(upstream.setup());
    char source[1024];
    const int source_len = snprintf(
        source,
        sizeof(source),
        "upstream backend at \"127.0.0.1:%u\"\n"
        "route GET \"/api\" { return forward(backend, request_policy: { "
        "version: \"HTTP/1.1\", host: \"upstream\", connection: \"omit\", "
        "strip_headers: [\"Connection\", \"Keep-Alive\", \"TE\", \"Expect\", \"Upgrade\"] }) }\n",
        upstream.port);
    REQUIRE_GT(source_len, 0);
    REQUIRE_LT(source_len, static_cast<int>(sizeof(source)));
    auto lexed = lex(Str{source, static_cast<u32>(source_len)});
    REQUIRE(lexed);
    auto ast = parse_file(lexed.value());
    REQUIRE(ast);
    std::unique_ptr<AstFile> ast_owned(ast.value());
    auto hir = analyze_file(*ast_owned);
    REQUIRE(hir);
    std::unique_ptr<HirModule> hir_owned(hir.value());
    auto mir = build_mir(*hir_owned);
    REQUIRE(mir);
    std::unique_ptr<MirModule> mir_owned(mir.value());
    auto& rir = resources.rir;
    REQUIRE(lower_to_rir(*mir_owned, rir));
    auto cg = jit::codegen(rir.module);
    REQUIRE(cg.ok);
    auto& engine = resources.engine;
    REQUIRE(engine.init());
    REQUIRE(engine.compile(cg.mod, cg.ctx));
    RouteConfig cfg{};
    REQUIRE(populate_route_config(cfg, rir.module));
    REQUIRE(register_jit_routes(cfg, rir.module, engine));
    const RouteConfig* active = &cfg;
    ScopedProxyLoop proxy;
    REQUIRE(proxy.setup(&active, 1000));

    const char request[] =
        "GET /api?q=raw%2Fquery HTTP/1.1\r\n"
        "Host:\tclient.example \t\r\n"
        "Connection: Foo, Bar\r\n"
        "Connection:\tBaz\t\r\n"
        "Foo:\t retained-one \t\r\n"
        "Bar:retained-two\r\n"
        "Keep-Alive: timeout=5\r\n"
        "TE: trailers\r\n"
        "Expect: 100-continue\r\n"
        "Upgrade: websocket\r\n"
        "Proxy-Connection:\tkeep-alive \t\r\n"
        "Trailer:\tX-Trailer\t\r\n"
        "X-Duplicate: one\r\n"
        "X-Duplicate:\t two \t\r\n\r\n";
    i32 client = connect_to(proxy.port);
    REQUIRE_GE(client, 0);
    REQUIRE(send_all(client, request, sizeof(request) - 1));
    char response[1024];
    const i32 response_read = recv_timeout(client, response, sizeof(response), 2000);
    const u32 response_len = response_read > 0 ? static_cast<u32>(response_read) : 0;
    close(client);
    CHECK_GT(response_len, 0u);

    for (u32 i = 0; i < 200 && upstream.request_count.load(std::memory_order_acquire) == 0; i++)
        usleep(5000);
    REQUIRE_EQ(upstream.request_count.load(std::memory_order_acquire), 1u);
    const Str forwarded{upstream.request, upstream.request_len};
    char expected[2048];
    const int expected_len = snprintf(expected,
                                      sizeof(expected),
                                      "GET /api?q=raw%%2Fquery HTTP/1.1\r\n"
                                      "Host: 127.0.0.1:%u\r\n"
                                      "Foo: retained-one\r\n"
                                      "Bar: retained-two\r\n"
                                      "Proxy-Connection: keep-alive\r\n"
                                      "Trailer: X-Trailer\r\n"
                                      "X-Duplicate: one\r\n"
                                      "X-Duplicate: two\r\n\r\n",
                                      upstream.port);
    REQUIRE_GT(expected_len, 0);
    REQUIRE_LT(expected_len, static_cast<int>(sizeof(expected)));
    CHECK_EQ(forwarded.len, static_cast<u32>(expected_len));
    CHECK(memcmp(forwarded.ptr, expected, static_cast<size_t>(expected_len)) == 0);

    // Header-only policy rejects framing, upgrade, and non-origin targets before
    // opening or writing an upstream socket. The recorder must see no second
    // accept or request for any of these fail-closed vectors.
    struct RejectedVector {
        const char* request;
        const char* expected_status;
    };
    const RejectedVector rejected[] = {
        {"GET /api HTTP/1.1\r\nHost: client.example\r\ntRaNsFeR-EnCoDiNg: identity\r\n\r\n", "400"},
        // Absolute-form cannot route to this origin-form entry, so the existing
        // unmatched-route fallback is 200; importantly it still never connects.
        {"GET http://client.example/api HTTP/1.1\r\nHost: client.example\r\n\r\n", "200"},
        {"GET /api HTTP/1.1\r\nHost: client.example\r\nConnection: Upgrade\r\n"
         "Upgrade: websocket\r\n\r\n",
         "400"},
    };
    for (const RejectedVector& vector : rejected) {
        const u32 accepted_before = upstream.accepted_count.load(std::memory_order_acquire);
        const u32 requests_before = upstream.request_count.load(std::memory_order_acquire);
        client = connect_to(proxy.port);
        REQUIRE_GE(client, 0);
        REQUIRE(send_all(client, vector.request, static_cast<u32>(strlen(vector.request))));
        char reject_response[512];
        const i32 reject_response_len =
            recv_timeout(client, reject_response, sizeof(reject_response), 2000);
        close(client);
        CHECK_GT(reject_response_len, 0);
        CHECK(buf_contains(reject_response,
                           static_cast<u32>(reject_response_len),
                           vector.expected_status,
                           static_cast<u32>(strlen(vector.expected_status))));
        usleep(100000);
        CHECK_EQ(upstream.accepted_count.load(std::memory_order_acquire), accepted_before);
        CHECK_EQ(upstream.request_count.load(std::memory_order_acquire), requests_before);
    }
}

TEST(route, request_policy_buffers_fixed_content_length_body) {
    using namespace rut;
    RecordingUpstream backend;
    REQUIRE(backend.setup());
    RouteConfig cfg{};
    auto id = cfg.add_upstream("backend", 0x7F000001, backend.port);
    REQUIRE(id.has_value());
    // Any-method registration is the direct equivalent of the converter's
    // method-omitted route and lets this test exercise POST without another ABI.
    REQUIRE(cfg.add_jit_handler("/api", 0, &forward_request_policy_1_handler));
    const RouteConfig* active = &cfg;
    ScopedProxyLoop proxy;
    REQUIRE(proxy.setup(&active, 1000));

    auto read_response = [](i32 fd) {
        char response[512];
        const i32 n = recv_timeout(fd, response, sizeof(response), 2000);
        return n > 0 && buf_contains(response, static_cast<u32>(n), "200", 3);
    };
    auto wait_requests = [&](u32 count) {
        for (u32 i = 0; i < 400 && backend.request_count.load(std::memory_order_acquire) < count;
             i++)
            usleep(5000);
    };

    // Coalesced header + binary body. The recorder is binary-safe and the
    // gateway must not allocate/connect before the complete body is available.
    const u8 coalesced_body[] = {0x00, 0x61, 0x0d, 0x0a, 0xff, 0x7f};
    char coalesced[512];
    const int coalesced_head = snprintf(coalesced,
                                        sizeof(coalesced),
                                        "POST /api?q=body HTTP/1.1\r\nHost: client.example\r\n"
                                        "Content-Length: 6\r\nX-Test: yes\r\n\r\n");
    REQUIRE_GT(coalesced_head, 0);
    REQUIRE_LT(static_cast<u32>(coalesced_head) + sizeof(coalesced_body),
               static_cast<u32>(sizeof(coalesced)));
    memcpy(coalesced + coalesced_head, coalesced_body, sizeof(coalesced_body));
    i32 client = connect_to(proxy.port);
    REQUIRE_GE(client, 0);
    set_socket_timeouts(client, 2);
    REQUIRE(send_all(client, coalesced, static_cast<u32>(coalesced_head) + sizeof(coalesced_body)));
    CHECK(read_response(client));
    close(client);
    wait_requests(1);
    REQUIRE_EQ(backend.accepted_count.load(std::memory_order_acquire), 1u);
    REQUIRE_EQ(backend.request_count.load(std::memory_order_acquire), 1u);
    CHECK_EQ(backend.request_body_len, static_cast<u32>(sizeof(coalesced_body)));
    CHECK(memcmp(backend.request + backend.request_header_len,
                 coalesced_body,
                 sizeof(coalesced_body)) == 0);
    CHECK(buf_contains(backend.request,
                       backend.request_header_len,
                       "Content-Length: 6\r\n",
                       static_cast<u32>(strlen("Content-Length: 6\r\n"))));

    // Segmented body: no backend accept is allowed after the header and a
    // prefix, then the final bytes complete exactly one upstream request.
    static constexpr char kSegmentedHead[] =
        "POST /api HTTP/1.1\r\nHost: client.example\r\nContent-Length: 5\r\n\r\n";
    client = connect_to(proxy.port);
    REQUIRE_GE(client, 0);
    set_socket_timeouts(client, 2);
    REQUIRE(send_all(client, kSegmentedHead, sizeof(kSegmentedHead) - 1));
    REQUIRE(send_all(client, "he", 2));
    usleep(100000);
    CHECK_EQ(backend.accepted_count.load(std::memory_order_acquire), 1u);
    CHECK_EQ(backend.request_count.load(std::memory_order_acquire), 1u);
    REQUIRE(send_all(client, "llo", 3));
    CHECK(read_response(client));
    close(client);
    wait_requests(2);
    REQUIRE_EQ(backend.accepted_count.load(std::memory_order_acquire), 2u);
    REQUIRE_EQ(backend.request_count.load(std::memory_order_acquire), 2u);
    CHECK_EQ(backend.request_body_len, 5u);
    CHECK(memcmp(backend.request + backend.request_header_len, "hello", 5) == 0);

    // Explicit zero is a completed fixed body, not the old header-only reject.
    static constexpr char kZero[] =
        "POST /api HTTP/1.1\r\nHost: client.example\r\nContent-Length: 0\r\n\r\n";
    client = connect_to(proxy.port);
    REQUIRE_GE(client, 0);
    set_socket_timeouts(client, 2);
    REQUIRE(send_all(client, kZero, sizeof(kZero) - 1));
    CHECK(read_response(client));
    close(client);
    wait_requests(3);
    REQUIRE_EQ(backend.accepted_count.load(std::memory_order_acquire), 3u);
    CHECK_EQ(backend.request_body_len, 0u);
    CHECK(buf_contains(backend.request,
                       backend.request_header_len,
                       "Content-Length: 0\r\n",
                       static_cast<u32>(strlen("Content-Length: 0\r\n"))));

    // Bytes after the declared body are retained as a separate downstream
    // suffix; they must not become part of request 1's upstream body.
    static constexpr char kWithSuffix[] =
        "POST /api HTTP/1.1\r\nHost: client.example\r\nContent-Length: 3\r\n\r\n"
        "abcGET /api HTTP/1.1\r\nHost: client.example\r\n\r\n";
    client = connect_to(proxy.port);
    REQUIRE_GE(client, 0);
    set_socket_timeouts(client, 2);
    REQUIRE(send_all(client, kWithSuffix, sizeof(kWithSuffix) - 1));
    CHECK(read_response(client));
    wait_requests(5);
    REQUIRE_EQ(backend.accepted_count.load(std::memory_order_acquire), 5u);
    REQUIRE_EQ(backend.request_count.load(std::memory_order_acquire), 5u);
    CHECK_EQ(backend.request_history_header_len[3] + 3u, backend.request_history_len[3]);
    CHECK(memcmp(backend.request_history[3] + backend.request_history_header_len[3], "abc", 3) ==
          0);
    CHECK_EQ(backend.request_history_header_len[4], backend.request_history_len[4]);
    close(client);

    const u32 accepted_before = backend.accepted_count.load(std::memory_order_acquire);
    const u32 requests_before = backend.request_count.load(std::memory_order_acquire);
    struct Rejected {
        const char* wire;
        u32 len;
    } rejected[] = {
        {"POST /api HTTP/1.1\r\nHost: x\r\nContent-Length: 5\r\n"
         "Content-Length: 5\r\n\r\nhello",
         0},
        {"POST /api HTTP/1.1\r\nHost: x\r\nTransfer-Encoding: identity\r\n\r\n", 0},
        {"POST /api HTTP/1.1\r\nHost: x\r\nTE: trailers\r\nContent-Length: 0\r\n\r\n", 0},
        {"POST /api HTTP/1.1\r\nHost: x\r\nExpect: 100-continue\r\n"
         "Content-Length: 0\r\n\r\n",
         0},
        {"POST /api HTTP/1.1\r\nHost: x\r\nUpgrade: websocket\r\n"
         "Content-Length: 0\r\n\r\n",
         0},
        {"POST /api HTTP/1.1\r\nHost: x\r\nContent-Length: 20000\r\n\r\n", 0},
    };
    for (auto& vector : rejected) {
        vector.len = static_cast<u32>(strlen(vector.wire));
        client = connect_to(proxy.port);
        REQUIRE_GE(client, 0);
        set_socket_timeouts(client, 2);
        REQUIRE(send_all(client, vector.wire, vector.len));
        char response[512];
        const i32 n = recv_timeout(client, response, sizeof(response), 2000);
        CHECK(n > 0 && buf_contains(response, static_cast<u32>(n), "400", 3));
        close(client);
        usleep(50000);
        CHECK_EQ(backend.accepted_count.load(std::memory_order_acquire), accepted_before);
        CHECK_EQ(backend.request_count.load(std::memory_order_acquire), requests_before);
    }

    // EOF before the declared body is complete must not create an upstream.
    client = connect_to(proxy.port);
    REQUIRE_GE(client, 0);
    set_socket_timeouts(client, 2);
    static constexpr char kTruncated[] =
        "POST /api HTTP/1.1\r\nHost: x\r\nContent-Length: 5\r\n\r\nhe";
    REQUIRE(send_all(client, kTruncated, sizeof(kTruncated) - 1));
    shutdown(client, SHUT_WR);
    usleep(150000);
    CHECK_EQ(backend.accepted_count.load(std::memory_order_acquire), accepted_before);
    CHECK_EQ(backend.request_count.load(std::memory_order_acquire), requests_before);
    close(client);
}

TEST(route, request_policy_fixed_body_exact_buffer_boundary) {
    using namespace rut;
    RecordingUpstream backend;
    REQUIRE(backend.setup());
    RouteConfig cfg{};
    auto id = cfg.add_upstream("backend", 0x7F000001, backend.port);
    REQUIRE(id.has_value());
    REQUIRE(cfg.add_jit_handler("/api", 0, &forward_request_policy_1_handler));
    const RouteConfig* active = &cfg;
    ScopedProxyLoop proxy;
    REQUIRE(proxy.setup(&active, 1000));

    // The preflight and materializer each have a 16 KiB slice. The original
    // request uses a short client Host while the rebuilt request uses the
    // selected IPv4:port authority, so derive the actual maximum from both
    // header lengths rather than assuming the two layouts are equal. The
    // Content-Length digit count is part of each header, so iterate to the
    // fixed point at the decimal-width boundary.
    // Include the actual runtime recorder port in the rebuilt authority.
    auto actual_header_len = [&](u32 body_len, bool rebuilt) -> u32 {
        char header[256];
        const int n = snprintf(header,
                               sizeof(header),
                               "POST /api HTTP/1.1\r\nHost: %s\r\nContent-Length: %u\r\n\r\n",
                               rebuilt ? "127.0.0.1" : "x",
                               body_len);
        CHECK_GT(n, 0);
        if (n <= 0) return 0;
        u32 result = static_cast<u32>(n);
        if (rebuilt && backend.port != 80) {
            // The production policy appends :<port> to the IPv4 authority for
            // this non-default test port.
            char authority[32];
            const int authority_len = snprintf(authority, sizeof(authority), ":%u", backend.port);
            CHECK_GT(authority_len, 0);
            if (authority_len <= 0) return result;
            result += static_cast<u32>(authority_len);
        }
        return result;
    };
    u32 body_len = SlicePool::kSliceSize;
    for (u32 i = 0; i < 8; i++) {
        const u32 original = actual_header_len(body_len, false);
        const u32 rebuilt = actual_header_len(body_len, true);
        const u32 next = SlicePool::kSliceSize - std::max(original, rebuilt);
        if (next == body_len) break;
        body_len = next;
    }
    const u32 original_header_len = actual_header_len(body_len, false);
    const u32 rebuilt_header_len = actual_header_len(body_len, true);
    REQUIRE_EQ(body_len + std::max(original_header_len, rebuilt_header_len), SlicePool::kSliceSize);

    char request_header[256];
    const int request_header_len = snprintf(request_header,
                                            sizeof(request_header),
                                            "POST /api HTTP/1.1\r\nHost: x\r\n"
                                            "Content-Length: %u\r\n\r\n",
                                            body_len);
    REQUIRE_GT(request_header_len, 0);
    const u32 request_len = static_cast<u32>(request_header_len) + body_len;
    std::unique_ptr<u8[]> request(new u8[request_len]);
    memcpy(request.get(), request_header, static_cast<size_t>(request_header_len));
    for (u32 i = 0; i < body_len; i++)
        request[request_header_len + i] = static_cast<u8>(i * 29u + 7u);

    i32 client = connect_to(proxy.port);
    REQUIRE_GE(client, 0);
    set_socket_timeouts(client, 3);
    REQUIRE(send_all(client, reinterpret_cast<const char*>(request.get()), request_len));
    char response[512];
    const i32 response_len = recv_timeout(client, response, sizeof(response), 3000);
    REQUIRE_GT(response_len, 0);
    CHECK(buf_contains(response, static_cast<u32>(response_len), "200", 3));
    close(client);

    for (u32 i = 0; i < 400 && backend.request_count.load(std::memory_order_acquire) < 1; i++)
        usleep(5000);
    REQUIRE_EQ(backend.accepted_count.load(std::memory_order_acquire), 1u);
    REQUIRE_EQ(backend.request_count.load(std::memory_order_acquire), 1u);
    CHECK_EQ(backend.request_len, SlicePool::kSliceSize);
    CHECK_EQ(backend.request_body_len, body_len);
    CHECK_EQ(backend.request_header_len, rebuilt_header_len);
    for (u32 i = 0; i < body_len; i++)
        CHECK_EQ(static_cast<u8>(backend.request[backend.request_header_len + i]),
                 static_cast<u8>(i * 29u + 7u));

    // The adjacent value must fail policy validation before an upstream accept.
    // This specifically covers the one-byte boundary, not merely a distant
    // large Content-Length rejection.
    const u32 accepted_before = backend.accepted_count.load(std::memory_order_acquire);
    const u32 requests_before = backend.request_count.load(std::memory_order_acquire);
    char over_header[256];
    const u32 over_body_len = body_len + 1;
    const int over_header_len = snprintf(over_header,
                                         sizeof(over_header),
                                         "POST /api HTTP/1.1\r\nHost: x\r\n"
                                         "Content-Length: %u\r\n\r\n",
                                         over_body_len);
    REQUIRE_GT(over_header_len, 0);
    const u32 over_len = static_cast<u32>(over_header_len) + over_body_len;
    std::unique_ptr<u8[]> over_request(new u8[over_len]);
    memcpy(over_request.get(), over_header, static_cast<size_t>(over_header_len));
    memset(over_request.get() + over_header_len, 0xA5, over_body_len);
    client = connect_to(proxy.port);
    REQUIRE_GE(client, 0);
    set_socket_timeouts(client, 2);
    REQUIRE(send_all(client, reinterpret_cast<const char*>(over_request.get()), over_len));
    char rejected[512];
    const i32 rejected_len = recv_timeout(client, rejected, sizeof(rejected), 2000);
    CHECK(rejected_len > 0 && buf_contains(rejected, static_cast<u32>(rejected_len), "400", 3));
    close(client);
    usleep(100000);
    CHECK_EQ(backend.accepted_count.load(std::memory_order_acquire), accepted_before);
    CHECK_EQ(backend.request_count.load(std::memory_order_acquire), requests_before);
}

TEST(shard, serves_http2_jit_request_policy_fails_closed) {
    using namespace rut;
    RecordingUpstream backend;
    REQUIRE(backend.setup());

    RouteConfig cfg{};
    auto id = cfg.add_upstream("backend", 0x7F000001, backend.port);
    REQUIRE(id.has_value());
    REQUIRE(cfg.add_jit_handler("/api", 'G', &forward_request_policy_1_handler));

    Shard<EpollEventLoop> shard;
    i32 lfd = create_listen_socket(0).value_or(-1);
    REQUIRE(lfd >= 0);
    struct FdGuard {
        i32 fd;
        ~FdGuard() {
            if (fd >= 0) close(fd);
        }
    } listener{lfd};
    REQUIRE(shard.init(0, lfd).has_value());
    shard.route_config = &cfg;
    struct ShardGuard {
        Shard<EpollEventLoop>& shard;
        i32& listen_fd;
        i32 client_fd = -1;
        bool spawned = false;
        ~ShardGuard() {
            if (client_fd >= 0) close(client_fd);
            if (spawned) {
                shard.stop();
                shard.join();
            }
            shard.shutdown();
            if (listen_fd >= 0) close(listen_fd);
        }
    } guard{shard, lfd};
    listener.fd = -1;
    REQUIRE(shard.spawn(-1).has_value());
    guard.spawned = true;
    usleep(50000);

    guard.client_fd = connect_to(get_port(lfd));
    REQUIRE(guard.client_fd >= 0);
    set_socket_timeouts(guard.client_fd, 2);
    u8 out[512];
    u32 n = h2_client_prologue(out);
    n += h2_client_get(out + n, sizeof(out) - n, 1, "/api", 4);
    REQUIRE(write_all_fd(guard.client_fd, out, n));

    u8 response[4096];
    u32 total = 0;
    for (int attempt = 0; attempt < 8 && total < sizeof(response); attempt++) {
        i32 got = recv_timeout(guard.client_fd,
                               reinterpret_cast<char*>(response + total),
                               sizeof(response) - total,
                               2000);
        if (got <= 0) break;
        total += static_cast<u32>(got);
        if (h2_status_for_stream(response, total, 1) != 0) break;
    }
    CHECK_EQ(h2_status_for_stream(response, total, 1), 400u);
    usleep(100000);
    CHECK_EQ(backend.accepted_count.load(std::memory_order_acquire), 0u);
    CHECK_EQ(backend.request_count.load(std::memory_order_acquire), 0u);
}

TEST(route, response_policy_rejects_before_upstream_accept) {
    using namespace rut;
    RecordingUpstream backend;
    REQUIRE(backend.setup());
    RouteConfig cfg{};
    auto id = cfg.add_upstream("backend", 0x7F000001, backend.port);
    REQUIRE(id.has_value());
    REQUIRE(cfg.add_upstream_backend(id.value(), 0x7F000001, backend.port));
    REQUIRE_EQ(cfg.add_response_policy(test_response_policy_spec()), 1u);
    REQUIRE(cfg.add_jit_handler("/api", 'G', &forward_response_policy_1_handler));
    const RouteConfig* active = &cfg;
    ScopedProxyLoop proxy;
    REQUIRE(proxy.setup(&active, 1000));

    struct ClientGuard {
        i32 fd;
        ~ClientGuard() {
            if (fd >= 0) close(fd);
        }
    } client{connect_to(proxy.port)};
    REQUIRE(client.fd >= 0);
    set_socket_timeouts(client.fd, 2);
    static constexpr char kRequest[] = "GET /api HTTP/1.1\r\nHost: client.example\r\n\r\n";
    REQUIRE(send_all(client.fd, kRequest, sizeof(kRequest) - 1));
    char response[512];
    const i32 response_len = recv_timeout(client.fd, response, sizeof(response), 2000);
    CHECK_GT(response_len, 0);
    CHECK(buf_contains(
        response, static_cast<u32>(response_len), "400", static_cast<u32>(strlen("400"))));
    usleep(100000);
    CHECK_EQ(backend.accepted_count.load(std::memory_order_acquire), 0u);
    CHECK_EQ(backend.request_count.load(std::memory_order_acquire), 0u);

    static constexpr const char* kRejectedRequests[] = {
        "GET /api HTTP/1.0\r\nHost: client.example\r\n\r\n",
        "GET /api HTTP/1.1\r\nHost: client.example\r\nConnection: close\r\n\r\n",
        "GET /api HTTP/1.1\r\nHost: client.example\r\nContent-Length: 0\r\n\r\n",
        "GET /api HTTP/1.1\r\nHost: client.example\r\nConnection: Upgrade\r\n"
        "Upgrade: websocket\r\n\r\n",
    };
    for (const char* request : kRejectedRequests) {
        i32 rejected_client = connect_to(proxy.port);
        REQUIRE_GE(rejected_client, 0);
        set_socket_timeouts(rejected_client, 2);
        REQUIRE(send_all(rejected_client, request, static_cast<u32>(strlen(request))));
        char reject[512];
        const i32 reject_len = recv_timeout(rejected_client, reject, sizeof(reject), 2000);
        close(rejected_client);
        CHECK_GT(reject_len, 0);
        CHECK(buf_contains(
            reject, static_cast<u32>(reject_len), "400", static_cast<u32>(strlen("400"))));
        usleep(50000);
        CHECK_EQ(backend.accepted_count.load(std::memory_order_acquire), 0u);
        CHECK_EQ(backend.request_count.load(std::memory_order_acquire), 0u);
    }
}

TEST(route, failure_policy_bundle_invalid_id_rejects_before_upstream_side_effects_and_owns_bytes) {
    RecordingUpstream backend;
    REQUIRE(backend.setup());
    RouteConfig cfg{};
    auto id = cfg.add_upstream("backend", 0x7F000001, backend.port);
    REQUIRE(id.has_value());
    auto failure = test_failure_policy_spec();
    char mutable_body[] = {'u', '\0', '\n', 'x'};
    failure.body = {mutable_body, sizeof(mutable_body)};
    const char* original_body = failure.body.ptr;
    REQUIRE_EQ(cfg.add_failure_policy(failure), 1u);
    // A failure policy is independently selectable; response id 0 means no
    // response serializer is bundled, while the failure id remains required.
    CHECK_EQ(cfg.add_policy_bundle(99, 1), 0u);
    CHECK_EQ(cfg.add_policy_bundle(0, 99), 0u);
    REQUIRE_EQ(cfg.add_policy_bundle(0, 1), 1u);
    REQUIRE_EQ(cfg.add_response_policy(test_response_policy_spec()), 1u);
    REQUIRE_EQ(cfg.add_policy_bundle(1, 1), 2u);
    CHECK(!cfg.policy_bundle_id_is_valid(0));
    CHECK(cfg.policy_bundle_id_is_valid(1));
    CHECK(!cfg.policy_bundle_id_is_valid(99));
    REQUIRE(cfg.failure_policies[0].body.ptr != original_body);
    CHECK(cfg.failure_policies[0].reason.ptr != failure.reason.ptr);
    CHECK(cfg.failure_policies[0].content_type.ptr != failure.content_type.ptr);
    CHECK(cfg.failure_policies[0].server.ptr != failure.server.ptr);
    mutable_body[0] = 'X';
    CHECK(cfg.failure_policies[0].body.len == sizeof(mutable_body));
    CHECK(cfg.failure_policies[0].body.ptr[0] == 'u');
    CHECK(static_cast<u8>(cfg.failure_policies[0].body.ptr[1]) == 0);
    CHECK(cfg.failure_policies[0].body.ptr[2] == '\n');
    CHECK(cfg.failure_policies[0].body.ptr[3] == 'x');
    REQUIRE(cfg.add_jit_handler("/bad", 'G', &forward_invalid_bundle_handler));
    const RouteConfig* active = &cfg;
    ScopedProxyLoop proxy;
    REQUIRE(proxy.setup(&active, 1000));
    // Direct-RIR callers can return an out-of-range bundle id. The runtime
    // rejects it at the zero-byte preflight boundary before selecting a backend
    // or opening an upstream fd.
    i32 invalid_client = connect_to(proxy.port);
    REQUIRE_GE(invalid_client, 0);
    set_socket_timeouts(invalid_client, 2);
    static constexpr char kInvalidRequest[] = "GET /bad HTTP/1.1\r\nHost: client.example\r\n\r\n";
    REQUIRE(send_all(invalid_client, kInvalidRequest, sizeof(kInvalidRequest) - 1));
    char invalid_response[512];
    const i32 invalid_response_len =
        recv_timeout(invalid_client, invalid_response, sizeof(invalid_response), 2000);
    close(invalid_client);
    CHECK_EQ(invalid_response_len, 0);
    usleep(100000);
    CHECK_EQ(backend.accepted_count.load(std::memory_order_acquire), 0u);
    CHECK_EQ(backend.request_count.load(std::memory_order_acquire), 0u);

    // A valid bundle on an unsupported HEAD domain is also rejected before
    // opening the backend; only the bounded non-HEAD H1 domain is admitted.
    REQUIRE(cfg.add_jit_handler("/head", 'H', &forward_failure_bundle_handler));
    i32 head_client = connect_to(proxy.port);
    REQUIRE_GE(head_client, 0);
    set_socket_timeouts(head_client, 2);
    static constexpr char kHeadRequest[] = "HEAD /head HTTP/1.1\r\nHost: client.example\r\n\r\n";
    REQUIRE(send_all(head_client, kHeadRequest, sizeof(kHeadRequest) - 1));
    char head_response[512];
    const i32 head_response_len =
        recv_timeout(head_client, head_response, sizeof(head_response), 2000);
    close(head_client);
    CHECK_GT(head_response_len, 0);
    CHECK(buf_contains(head_response,
                       static_cast<u32>(head_response_len),
                       "400",
                       static_cast<u32>(strlen("400"))));
    usleep(100000);
    CHECK_EQ(backend.accepted_count.load(std::memory_order_acquire), 0u);
    CHECK_EQ(backend.request_count.load(std::memory_order_acquire), 0u);
}

TEST(route, failure_policy_connect_error_serializes_binary_body_and_releases_slot) {
    DeadEndpoint dead;
    REQUIRE(dead.reserve());
    RouteConfig cfg{};
    REQUIRE(cfg.add_upstream("backend", 0x7F000001, dead.port).has_value());
    cfg.upstreams[0].max_inflight = 1;
    auto failure = test_failure_policy_spec();
    const char body[] = {'u', '\0', '\n', 'x'};
    failure.body = {body, sizeof(body)};
    REQUIRE_EQ(cfg.add_failure_policy(failure), 1u);
    REQUIRE_EQ(cfg.add_policy_bundle(0, 1), 1u);
    REQUIRE_EQ(cfg.add_response_policy(test_response_policy_spec()), 1u);
    REQUIRE_EQ(cfg.add_policy_bundle(1, 1), 2u);
    REQUIRE(cfg.add_jit_handler("/api", 'G', &forward_failure_bundle_two_handler));
    const RouteConfig* active = &cfg;
    ScopedProxyLoop proxy;
    REQUIRE(proxy.setup(&active, 1000));
    i32 client = connect_to(proxy.port);
    REQUIRE_GE(client, 0);
    set_socket_timeouts(client, 2);

    auto read_response = [&](char* out, u32 cap) -> i32 {
        u32 total = 0;
        u32 body_start = 0;
        while (total < cap) {
            const i32 n = recv_timeout(client, out + total, cap - total, 2000);
            if (n <= 0) return n;
            total += static_cast<u32>(n);
            if (body_start == 0) {
                for (u32 i = 0; i + 3 < total; i++) {
                    if (out[i] == '\r' && out[i + 1] == '\n' && out[i + 2] == '\r' &&
                        out[i + 3] == '\n') {
                        body_start = i + 4;
                        break;
                    }
                }
            }
            if (body_start != 0 && total >= body_start + sizeof(body))
                return static_cast<i32>(total);
        }
        return static_cast<i32>(total);
    };

    static constexpr char kRequest[] = "GET /api HTTP/1.1\r\nHost: client.example\r\n\r\n";
    REQUIRE(send_all(client, kRequest, sizeof(kRequest) - 1));
    char response[1024];
    i32 response_len = read_response(response, sizeof(response));
    REQUIRE_GT(response_len, 0);
    const u32 response_size = static_cast<u32>(response_len);
    CHECK(buf_contains(response, response_size, "HTTP/1.1 502 Bad Gateway\r\n", 26));
    CHECK(buf_contains(response, response_size, "Server: rut\r\n", 13));
    CHECK(buf_contains(response, response_size, "Content-Type: text/plain\r\n", 26));
    CHECK(buf_contains(response, response_size, "Content-Length: 4\r\n", 19));
    CHECK(buf_contains(response, response_size, "Connection: keep-alive\r\n", 24));
    const char* body_ptr = nullptr;
    for (u32 i = 0; i + 3 < response_size; i++) {
        if (response[i] == '\r' && response[i + 1] == '\n' && response[i + 2] == '\r' &&
            response[i + 3] == '\n') {
            body_ptr = response + i + 4;
            CHECK_EQ(response_size - (i + 4), sizeof(body));
            break;
        }
    }
    REQUIRE(body_ptr != nullptr);
    CHECK(memcmp(body_ptr, body, sizeof(body)) == 0);

    // A second request proves the failure response honored request-derived
    // keep-alive and that the held upstream slot was released.
    REQUIRE(send_all(client, kRequest, sizeof(kRequest) - 1));
    response_len = read_response(response, sizeof(response));
    CHECK_GT(response_len, 0);
    CHECK(buf_contains(response, static_cast<u32>(response_len), "HTTP/1.1 502", 12));
    close(client);
}

TEST(route, failure_policy_close_intent_emits_close_and_eof) {
    DeadEndpoint dead;
    REQUIRE(dead.reserve());
    RouteConfig cfg{};
    REQUIRE(cfg.add_upstream("backend", 0x7F000001, dead.port).has_value());
    auto failure = test_failure_policy_spec();
    failure.body = {"x", 1};
    REQUIRE_EQ(cfg.add_failure_policy(failure), 1u);
    REQUIRE_EQ(cfg.add_policy_bundle(0, 1), 1u);
    REQUIRE(cfg.add_jit_handler("/api", 'G', &forward_failure_bundle_handler));
    const RouteConfig* active = &cfg;
    ScopedProxyLoop proxy;
    REQUIRE(proxy.setup(&active, 1000));
    i32 client = connect_to(proxy.port);
    REQUIRE_GE(client, 0);
    set_socket_timeouts(client, 2);
    static constexpr char kRequest[] =
        "GET /api HTTP/1.1\r\nHost: client.example\r\nConnection: close\r\n\r\n";
    REQUIRE(send_all(client, kRequest, sizeof(kRequest) - 1));
    char response[1024]{};
    u32 response_len = 0;
    u32 body_start = 0;
    while (response_len < sizeof(response)) {
        const i32 got =
            recv_timeout(client, response + response_len, sizeof(response) - response_len, 2000);
        REQUIRE_GT(got, 0);
        response_len += static_cast<u32>(got);
        if (body_start == 0) {
            for (u32 i = 0; i + 3 < response_len; i++) {
                if (response[i] == '\r' && response[i + 1] == '\n' && response[i + 2] == '\r' &&
                    response[i + 3] == '\n') {
                    body_start = i + 4;
                    break;
                }
            }
        }
        if (body_start != 0 && response_len >= body_start + 1) break;
    }
    REQUIRE_NE(body_start, 0u);
    CHECK_EQ(response_len, body_start + 1);
    CHECK(buf_contains(response, response_len, "HTTP/1.1 502 Bad Gateway\r\n", 26));
    CHECK(buf_contains(response, response_len, "Server: rut\r\n", 13));
    CHECK(buf_contains(response, response_len, "Content-Type: text/plain\r\n", 26));
    CHECK(buf_contains(response, response_len, "Content-Length: 1\r\n", 19));
    CHECK(buf_contains(response, response_len, "Connection: close\r\n", 19));
    CHECK_EQ(memcmp(response + response_len - 1, "x", 1), 0);
    CHECK_FALSE(buf_contains(response, response_len, "Content-Length: 11\r\n", 20));
    const i32 eof = recv_timeout(client, response, sizeof(response), 2000);
    CHECK_EQ(eof, 0);
    close(client);
}

